-- Generated from live FFXI DAT ROM/175/35.DAT via xi-tinkerer on 2026-06-15.
-- Values map key item id -> native DAT name and description text.
return {
    [0] = { name = "in-text name", description = "English Description" },
    [1] = { name = "Zeruhn report", description = "\"The Galka, our main workforce, seem to suffer from low morale, as indicated by their recent insubordination. They seem to have found new hope in the return of their 'Talekeeper,' who disappeared thirty years ago.\" -Overseer Makarim" },
    [2] = { name = "Palborough Mines logs", description = "These logs tell the tale of the pioneers who dug the Palborough Mines. The history of Palborough is said to symbolize the peak of Bastok's industrial revolution." },
    [3] = { name = "blue acidity tester", description = "An acidity tester given to you by Cid. It is currently blue." },
    [4] = { name = "red acidity tester", description = "An acidity tester given to you by Cid. Its color has changed from blue to red." },
    [5] = { name = "letter to the consuls", description = "Issued by the Kingdom of San d'Oria. A letter of introduction to the consulates in Bastok and Windurst. Needed to complete missions in those countries." },
    [6] = { name = "letter to the consuls", description = "Issued by the Republic of Bastok. A letter of introduction to the consulates in San d'Oria and Windurst. Needed to complete missions in those countries." },
    [7] = { name = "letter to the consuls", description = "Issued by the Federation of Windurst. A letter of introduction to the consulates in Bastok and San d'Oria. Needed to complete missions in those countries." },
    [8] = { name = "airship pass", description = "This pass allows you to ride airships to San d'Oria, Bastok, and Windurst from Jeuno." },
    [9] = { name = "airship pass for Kazham", description = "This pass allows you to ride the airship between Kazham and Jeuno." },
    [10] = { name = "overdue book notification", description = "This letter reads: \"This is your final notification to return the following overdue book to the Optistery's Library of Magic: 'Art For Everyone.' Failure to return this book immediately will result in a string of fearsome curses being cast in your direction. Yours sinisterly, Tosuka-Porika, Librarian.\"" },
    [11] = { name = "letter from Domien", description = "This letter reads: \"I do not do business with a promise-breaker.\" -Domien" },
    [12] = { name = "C. L. report", description = "\"As I suspected, the crystal resonance around the 'crag' is much stronger than normal. I believe it is safe to surmise that the same level of crystal resonance can be found near San d'Oria and Windurst, extending straight toward Jeuno.\" -Cid" },
    [13] = { name = "Kindred crest", description = "A crest you found deep in one of the beastmen's lairs. It may be a sign of the return of the Kindred." },
    [14] = { name = "Magicite: Optistone", description = "A crystal you found in Davoi. It is glowing eerily." },
    [15] = { name = "Magicite: Aurastone", description = "A crystal you found in Beadeaux. It is glowing eerily." },
    [16] = { name = "Magicite: Orastone", description = "A crystal you found in Castle Oztroja. It is glowing eerily." },
    [17] = { name = "food offering", description = "A bag full of food the Yagudo like. A present as a symbol of Windurst's friendship with the Yagudo. Your orders are to hand this to one of the Yagudo who stand by the two altars of offerings in Giddeus." },
    [18] = { name = "drink offering", description = "A bag full of drinks the Yagudo like. A present as a symbol of Windurst's friendship with the Yagudo. Your orders are to hand this to one of the Yagudo who stand by the two altars of offerings in Giddeus." },
    [19] = { name = "clock tower oil", description = "Oil for Jeuno's clock tower. Apparently, its gears won't run smoothly without this." },
    [20] = { name = "Yagudo torch", description = "A torch used by beastmen. Use it to venture further into Castle Oztroja." },
    [21] = { name = "crest of Davoi", description = "Needed to break the Orcs' barrier in Davoi." },
    [22] = { name = "letter to Aldo", description = "A letter from Kam'lanaut, Archduke of Jeuno. It is addressed to a certain \"Aldo\" of the Tenshodo." },
    [23] = { name = "bouquet for the pioneers", description = "A traveler named Elki has asked you to take this bouquet to the monument in Gustaberg where his great- grandfather Omran is buried." },
    [24] = { name = "old toolbox", description = "This toolbox contains eleven sets of tools. The first set has the name \"Omran\" inscribed on it, while the name on the last set reads \"Vigilant Owl.\"" },
    [25] = { name = "note from Hariga-Origa", description = "A note you received from Hariga-Origa in the Optistery's Manuscript Room. It simply contains the glyph that Hariga-Origa couldn't read." },
    [26] = { name = "note from Ipupu", description = "A note you received from Ipupu who is out on expedition to the Horutoto Ruins. It not-so-simply contains an explanation of the glyph that Hariga-Origa couldn't read." },
    [27] = { name = "\"Art For Everyone\"", description = "The book from the Library of Magic that a Hume named Orn had out on loan. It is easy to read, with many illustrations, but is thick and heavy." },
    [28] = { name = "cracked Mana Orb", description = "A Mana Orb you obtained from the Horutoto Ruins. It is fractured, with many large cracks in it." },
    [29] = { name = "Kindred report", description = "A report from the consulate, stating that there seems to be a new force influencing the beastmen from the shadows." },
    [30] = { name = "letter to the ambassador", description = "An important document that proves you have been dispatched as an envoy to the embassy in Jeuno." },
    [31] = { name = "sword offering", description = "An offering from Windurst to the beastmen. You received it from Heavens Tower with the instructions to deliver it to the treasure chamber in Giddeus." },
    [32] = { name = "shield offering", description = "An offering from Windurst to the beastmen. You received it from Heavens Tower with the instructions to deliver it to the treasure chamber in Giddeus." },
    [33] = { name = "dull sword", description = "An ordinary sword that the Bastokan Consulate switched for the real sword offering. You seriously wonder whether the Yagudo of Giddeus will accept this or not." },
    [34] = { name = "dark key", description = "This key allows you to enter the deepest part of Giddeus in order to defeat the fearsome monster that has appeared there." },
    [35] = { name = "Adventurer's Certificate", description = "This certification is given to adventurers who have distinguished themselves in all three countries." },
    [36] = { name = "Starway Stairway bauble", description = "This key opens the door to the Starway Stairway from the Clerical Chamber in Heavens Tower." },
    [37] = { name = "first dark Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It hasn't been filled with magic, so it doesn't glow." },
    [38] = { name = "\"Creature Counter\" magic doll", description = "A magic doll you received from the Aurastery. It has a spell cast on it that enables it to count the number of monsters that the bearer defeats. Be warned that the magic wears off after a certain amount of time!" },
    [39] = { name = "off offering", description = "A bag full of drinks presented to the Yagudo as a symbol of Windurst's friendship. Chef Ranpi-Monpi, from the Culinarians' Guild, accidentally mixed in some apple vinegar, causing it to reek hideously." },
    [40] = { name = "Windurst Waters scoop", description = "\"The Great Beast...A Life In Ruins?\" ...by Kyume-Romeh The rumors of the great beast, said to be sealed inside the Horutoto Ruins, have died down. But where does the fearsome beast really lie? Kyume-Romeh finds out in this exclusive report." },
    [41] = { name = "Windurst Walls scoop", description = "\"Zubaba's Forbidden Lover\" ...by Hiwon-Biwon The head lady-in-waiting, yes, the old battle-axe Zubaba herself, is rumored to have a secret lover! How can she, having supposedly devoted herself to the Star Sibyl? A reveal-it-all story of forbidden passion in the most holy of places." },
    [42] = { name = "Port Windurst scoop", description = "\"Who's Watching the Children?\" ...by Yujuju What is that small group of Tarutaru and Mithra children up to in the Port Area? Are they a gang of deadbeat layabouts, a front for some crime syndicate, or much worse? Yujuju goes directly to the source and asks...\"Do their mothers know?\"" },
    [43] = { name = "Windurst Woods scoop", description = "\"Where the Cat Burglar Hides her Kitty\" ...by Umumu The Cat Burglar roams free because the stolen booty is never found. When Capt. Rakoh Buuma searched her house, there was nothing there. So where does the Cat hide the goods? This reporter knows it is hidden deep beneath the eastern magic tower of the Horutoto Ruins...maybe...I think...well kinda...?" },
    [44] = { name = "Temple Knights' Davoi report", description = "Vital intelligence on Orcish activity throughout Davoi, gathered by the Temple Knights." },
    [45] = { name = "silver bell", description = "A mythril bell, said to soothe the soul of even the fiercest Quadav. Needed to open the door to the deeper parts of Beadeaux." },
    [46] = { name = "coruscant rosary", description = "A rosary that glows with an eerie light. It has the power to weaken magic seals. Needed to open the door to the deeper parts of Beadeaux." },
    [47] = { name = "black matinee necklace", description = "A long necklace made from dark bone. It has the power to break the strongest magic seals. Needed to open the door to the deeper parts of Beadeaux." },
    [48] = { name = "Ducal Guard's lantern", description = "A lantern lent to you by a guard in Jeuno. He said that obtaining flames from the four braziers in the stonework rooms of the Eldieme Necropolis will banish evil spirits." },
    [49] = { name = "Ducal Guard's lantern", description = "A lantern lent to you by a guard in Jeuno. He said it has the power to banish evil spirits. It is burning brightly." },
    [50] = { name = "holy candle", description = "A candle from the Temple of the Goddess." },
    [51] = { name = "second dark Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It hasn't been filled with magic, so it doesn't glow." },
    [52] = { name = "third dark Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It hasn't been filled with magic, so it doesn't glow." },
    [53] = { name = "fourth dark Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It hasn't been filled with magic, so it doesn't glow." },
    [54] = { name = "fifth dark Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It hasn't been filled with magic, so it doesn't glow." },
    [55] = { name = "sixth dark Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It hasn't been filled with magic, so it doesn't glow." },
    [56] = { name = "archducal audience permit", description = "Required before seeking audience with the Archduke of Jeuno." },
    [57] = { name = "super soup pot", description = "A special cooking pot that can only be obtained from the Culinarians' Guild in Windurst." },
    [58] = { name = "Two of Swords", description = "The Cardian from Panta-Putta's place. He seems to have shut himself down." },
    [59] = { name = "first glowing Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It has been recharged with magic at the Horutoto Ruins, so it glows brilliantly." },
    [60] = { name = "second glowing Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It has been recharged with magic at the Horutoto Ruins, so it glows brilliantly." },
    [61] = { name = "third glowing Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It has been recharged with magic at the Horutoto Ruins, so it glows brilliantly." },
    [62] = { name = "fourth glowing Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It has been recharged with magic at the Horutoto Ruins, so it glows brilliantly." },
    [63] = { name = "fifth glowing Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It has been recharged with magic at the Horutoto Ruins, so it glows brilliantly." },
    [64] = { name = "sixth glowing Mana Orb", description = "A Mana Orb that the Manustery is in charge of maintaining. It has been recharged with magic at the Horutoto Ruins, so it glows brilliantly." },
    [65] = { name = "rescue training certificate", description = "The bearer of this certificate has successfully completed rescue training on the La Theine Plateau." },
    [66] = { name = "charm of light", description = "The key to opening the door to the room of light beneath the central tower of the Horutoto Ruins. It is said that inside this room, part of the talisman that seals Castle Zvahl is stored." },
    [67] = { name = "hideout key", description = "The key to the Cat Burglar's hideout in the Horutoto Ruins." },
    [68] = { name = "lapis coral", description = "A piece of coral you found in the Maze of Shakhrami that glitters like lapis lazuli." },
    [69] = { name = "message to Jeuno", description = "\"Attempted assassination at the Chateau d'Oraguille. Royaulais unconscious and in poor condition. Return to San d'Oria immediately.\"" },
    [70] = { name = "message to Jeuno", description = "\"An intruder snuck into the President's Office in Bastok. The President himself was attacked. Return to Bastok immediately.\"" },
    [71] = { name = "message to Jeuno", description = "\"A grave matter has occurred beneath the central magic tower of the Horutoto Ruins, in the facility guarded by Heavens Tower. Your instructions are to return to Windurst posthaste.\"" },
    [72] = { name = "new Fei'Yin seal", description = "A new magical parchment to replace the old one that is feared to have failed in Fei'Yin." },
    [73] = { name = "burnt seal", description = "The remains of the magical parchment that sealed off the lands beyond Fei'Yin twenty years ago. It has lost its power after being burned to ashes by a powerful spell." },
    [74] = { name = "shadow fragment", description = "A small part of the Shadow Lord's body. It still emanates some of his dark aura." },
    [75] = { name = "Ronfaure supplies", description = "Deliver these supplies to the guards manning the Ronfaure Outpost before the next conquest results are tallied." },
    [76] = { name = "Zulkheim supplies", description = "Deliver these supplies to the guards manning the Zulkheim Outpost before the next conquest results are tallied." },
    [77] = { name = "Norvallen supplies", description = "Deliver these supplies to the guards manning the Norvallen Outpost before the next conquest results are tallied." },
    [78] = { name = "Gustaberg supplies", description = "Deliver these supplies to the guards manning the Gustaberg Outpost before the next conquest results are tallied." },
    [79] = { name = "Derfland supplies", description = "Deliver these supplies to the guards manning the Derfland Outpost before the next conquest results are tallied." },
    [80] = { name = "Sarutabaruta supplies", description = "Deliver these supplies to the guards manning the Sarutabaruta Outpost before the next conquest results are tallied." },
    [81] = { name = "Kolshushu supplies", description = "Deliver these supplies to the guards manning the Kolshushu Outpost before the next conquest results are tallied." },
    [82] = { name = "Aragoneu supplies", description = "Deliver these supplies to the guards manning the Aragoneu Outpost before the next conquest results are tallied." },
    [83] = { name = "Fauregandi supplies", description = "Deliver these supplies to the guards manning the Fauregandi Outpost before the next conquest results are tallied." },
    [84] = { name = "Valdeaunia supplies", description = "Deliver these supplies to the guards manning the Valdeaunia Outpost before the next conquest results are tallied." },
    [85] = { name = "Li'Telor supplies", description = "Deliver these supplies to the guards manning the Li'Telor Outpost before the next conquest results are tallied." },
    [86] = { name = "Kuzotz supplies", description = "Deliver these supplies to the guards manning the Kuzotz Outpost before the next conquest results are tallied." },
    [87] = { name = "Vollbow supplies", description = "Deliver these supplies to the guards manning the Vollbow Outpost before the next conquest results are tallied." },
    [88] = { name = "lapis monocle", description = "An eyeglass lent to you by Nanaa Mihgo. Looking through this supposedly enables the wearer to detect the existence of lapis coral." },
    [89] = { name = "donation envelope", description = "A bulky envelope addressed to Arnau. Find him in the cathedral." },
    [90] = { name = "Aragoneu pizza", description = "Baked by Rycharde, chef of Mhaura." },
    [91] = { name = "land crab bisque", description = "Cooked by Valgeir, chef of Selbina." },
    [92] = { name = "Mhauran couscous", description = "Made by Rycharde, chef of Mhaura." },
    [93] = { name = "etched ring", description = "A shining silver ring with a name engraved on the inside." },
    [94] = { name = "trader's sack", description = "Property of two merchants, Serafin and Evrard, before they were captured by the Quadav. Deliver to Thunder Hawk." },
    [95] = { name = "fake moustache", description = "A false moustache made from Saruta Cotton that has been scorched by magic. It is fuzzy-wuzzy to the touch and has a splendid handlebar shape. It really makes you look like a world- renowned detective." },
    [96] = { name = "Gardenia pass", description = "\"The bearer of this sigil shall be allowed access through Ranguemont Pass.\"" },
    [97] = { name = "weapons order", description = "An order for a weapons trader named Alexius. Find him somewhere in Jugner Forest." },
    [98] = { name = "weapons receipt", description = "An order confirmation for Helbort's Blades in Southern San d'Oria." },
    [99] = { name = "small bag", description = "A small bag of unknown contents, picked up in Mhaura at the request of the Rhinostery staff in Windurst. \"Handle with care!\" is written on it in bold letters." },
    [100] = { name = "Ranpi-Monpi's special stew", description = "A special stew that the Culinarians' Guild chef, Ranpi-Monpi, made to the best of his cookery skill. It has been carefully prepared from 32 select ingredients and smells absolutely delicious. However, it doesn't look like something a person would dare eat..." },
    [101] = { name = "ferry ticket", description = "A ticket that allows you to board the ferry ship between Mhaura and Selbina, or Mhaura and Al Zahbi." },
    [102] = { name = "stamp sheet", description = "\"Discover Bastok! Get stamps from the guards stationed near the off- limits area and the small archway in the Mines District, the West Gate in the Markets District, the drawbridge and bottom doors of the warehouses, the Goddess statue, and the Cannonry in the Metalworks.\"" },
    [103] = { name = "lost document", description = "This is the last page of the Davoi Report." },
    [104] = { name = "East Block code", description = "A note with codes for the East Block of Davoi." },
    [105] = { name = "South Block code", description = "A note with codes for the South Block of Davoi." },
    [106] = { name = "North Block code", description = "A note with codes for the North Block of Davoi." },
    [107] = { name = "letter from Roh Latteh", description = "\"Dear Mom, Thank you for all the presents you bring me, I like them a lot...but I'd be more happy if you came home early sometimes, even if you don't bring me back anything.\" -Roh" },
    [108] = { name = "painting of a windmill", description = "This painting of a windmill is painted with a unique touch, but it is in very bad condition." },
    [109] = { name = "tattered mission orders", description = "Orders apparently issued by San d'Oria. The writing is no longer legible." },
    [110] = { name = "Monastic Cavern key", description = "A key that opens a door in the Monastic Caverns in Davoi." },
    [111] = { name = "moon crystal", description = "This is needed to pass through the gate that only opens at a certain date and time." },
    [112] = { name = "southeastern star charm", description = "A key to the laboratory that lies beneath the southeastern magic tower of the Horutoto Ruins. It magically disappears upon use." },
    [113] = { name = "Wonder Magic Set", description = "This set rivals Airship Stamp Rally for the hearts of kids everywhere." },
    [114] = { name = "unfinished letter", description = "\"Dear Cid, I'm soon going to be able to open that restaurant I told you about. I'm glad you accepted my resignation. I regret not being able to help you with your work anymore, but I'm sure there are plenty of engineers--\" The letter ends here." },
    [115] = { name = "new model hat", description = "The latest in headwear fashion by Baren-Moren the hatter, who has asked you to advertise it to the local townsfolk. It has a feather on one side and is really quite stylish." },
    [116] = { name = "Angelica's autograph", description = "The signature of the artist Angelica, who is staying at the hostelry in Windurst Waters. You aren't sure which way is up." },
    [117] = { name = "old tiger's fang", description = "A fang you plucked from the carcass of a tiger." },
    [118] = { name = "Tenshodo Member's Card", description = "Please present this card to gain access to the Tenshodo." },
    [119] = { name = "receipt for the prince", description = "A receipt from the armorer. The customer's name is written so flamboyantly, it is completely illegible." },
    [120] = { name = "magic trash", description = "Chululu forgot to put this out on magic trash day." },
    [121] = { name = "Tenshodo application form", description = "An application for the exclusive shop, the Tenshodo. Take it to headquarters to become a member." },
    [122] = { name = "sharp gray stone", description = "A rock you received from the Cat Burglar. At first glance it seems like any other gray stone, but on closer inspection you can see that it sparkles when held at certain angles. It must contain traces of some metal." },
    [123] = { name = "cathedral donation", description = "A great sum of money from Madame Hinaree." },
    [124] = { name = "Qufim supplies", description = "Deliver these supplies to the guards manning the Qufim Outpost before the next conquest results are tallied." },
    [125] = { name = "tattered test sheet", description = "A torn and tattered answer sheet. You can't tell whose test it was, but Professor Koru-Moru has written the following on it: \"Learn from your mistakes, and never try and cover one wrong with another. Think about what you've done.\"" },
    [126] = { name = "\"A Song of Love\"", description = "A romance novel with the picture of a man and a woman making out under the moonlight. It has the blurb: \"They thought only the moon bore witness to their forbidden love, until one fateful night...\"" },
    [127] = { name = "Steaming Sheep invitation", description = "\"Dear Sir, Thank you for visiting us the other day. We have been able to procure the ingredients for that dish you ordered. Please drop by the Steaming Sheep Restaurant whenever you have time.\" -Hilda" },
    [128] = { name = "broken wand", description = "A snapped wand you received from Mashira at the magic incinerator in Garlaige Citadel. It looks like some- one used too much force and broke it. It is probably worthless, but the Minister of the Orastery is said to be attached to it for some reason." },
    [129] = { name = "Gulemont's document", description = "A bond dropped by Gulemont. Find him in the tavern in Port San d'Oria." },
    [130] = { name = "old ring", description = "An old ring found in Castle Oztroja. It seems to be engraved with the seal of the Optistery in Windurst." },
    [131] = { name = "white orb", description = "An orb from the mage in Davoi. Place it into four red pools around Davoi." },
    [132] = { name = "pink orb", description = "The orb from the mage in Davoi. It has absorbed magic from one red pool." },
    [133] = { name = "red orb", description = "The orb from the mage in Davoi. It has absorbed magic from two red pools." },
    [134] = { name = "blood orb", description = "The orb from the mage in Davoi. It has absorbed magic from three red pools." },
    [135] = { name = "cursed orb", description = "The orb from the mage in Davoi. It is now cursed by the magic of the red pools." },
    [136] = { name = "crimson orb", description = "The orb from the mage in Davoi. It now has the power to break the seal at the far end of Davoi." },
    [137] = { name = "key to the Oztroja mines", description = "A key taken from the Yagudo guarding the mines of Castle Oztroja." },
    [138] = { name = "chocobo license", description = "This license is issued to certified chocobo riders. Valid until the end of time." },
    [139] = { name = "cursepaper", description = "This paper copies the effects of any curse its holder receives." },
    [140] = { name = "corrupted dirt", description = "A clump of dirt sampled from a polluted patch of earth in Beadeaux." },
    [141] = { name = "stalactite dew", description = "A drop of condensation from a stalactite in Ordelle's Caves." },
    [142] = { name = "squire certificate", description = "The bearer of this certificate is hereby recognized as a squire, with all its rights and privileges." },
    [143] = { name = "Book of Tasks", description = "The greatest knights in all the land Are watched by others from high nest. The watchers know the task at hand. When lost go East to know the West." },
    [144] = { name = "Book of the East", description = "From the island lake, South runs the flow. Where it goes, Only beastmen know." },
    [145] = { name = "Book of the West", description = "There is one whose body breaks. Death it deals and death it reaps. And in the sky a beacon makes, Where it sits, the knight's soul sleeps." },
    [146] = { name = "knight's soul", description = "The blade of this ancient sword has melted away." },
    [147] = { name = "cold medicine", description = "The old woman's medicine. It works like magic on colds." },
    [148] = { name = "Amaura's formula", description = "Cold Medicine Formula: One chunk of zinc ore One insect wing One malboro vine" },
    [149] = { name = "overdue book notification", description = "This letter reads: \"This is your final notification to return the following overdue library book to the Optistery's Library of Magic: 'A Song of Love' Failure to return this book immediately will result in a string of fearsome curses being cast in your direction. Yours sinisterly, Tosuka-Porika, Librarian.\"" },
    [150] = { name = "Scripture of Water", description = "The content of this scripture is too cryptic for you to decipher." },
    [151] = { name = "Scripture of Wind", description = "The content of this scripture is too cryptic for you to decipher." },
    [152] = { name = "Tami's note", description = "\"Go to the Bat's Lair Inn and buy us the usual thing. -Tami\"" },
    [153] = { name = "thyme moss", description = "This moss thrives in dark, damp places. It helps suppress coughs, apparently." },
    [154] = { name = "cough medicine", description = "A concoction from that old woman, Amaura." },
    [155] = { name = "scroll of treasure", description = "West is a gate, North lies a stream. Stand on the spot To see what I mean." },
    [156] = { name = "Code of Beastmasters", description = "All who would command beasts of nature must heed the wisdom inscribed herein." },
    [157] = { name = "Orcish hut key", description = "The key to a small hut in the Ghelsba Outpost." },
    [158] = { name = "star crested summons", description = "A writ of summons with the emblem of a white star on it. The cursive writing on it twinkles like starlight. It reads: \"Your presence is requested immediately at the Vestal Chambers of Heavens Tower.\"" },
    [159] = { name = "Brugaire goods", description = "Contraband from Portaure of the Brugaire Consortium. If caught, smugglers face temporary suspension of airship boarding rights, so be careful." },
    [160] = { name = "small teacup", description = "A beautifully-decorated teacup. It is marked with a family crest." },
    [161] = { name = "suspicious envelope", description = "A white envelope without name or address. Take it to Monarlais Halver." },
    [162] = { name = "carrier pigeon letter", description = "\"Does your heart still long for the stars of Ifrit, While my soul lingers on the ground far beneath...?\" -Carmelo" },
    [163] = { name = "Carmelo's song sheet", description = "A capriccio titled \"Love and Ice\" written by the bard Carmelo. It is dedicated to someone named Dariah." },
    [164] = { name = "Curilla's bottle", description = "A bottle from General Curilla. Fill it at the hot spring that flows from the Horlais Peak." },
    [165] = { name = "Curilla's bottle", description = "The bottle from General Curilla. It is full of water from the hot spring that flows from the Horlais Peak." },
    [166] = { name = "neutralizer", description = "A neutralizer for poison, kindly concocted by Novalmauge." },
    [167] = { name = "goldsmithing order", description = "\"For the procurement of a fine work of mythril, traditional in form but novel in spirit.\" -Femitte" },
    [168] = { name = "mythril hearts", description = "A pendant crafted by the goldsmith Michea. The emblems of Bastok and San d'Oria are etched side by side." },
    [169] = { name = "testimonial", description = "\"This certifies that you have gathered no less than ten thousand carp. Please spend your time in a manner more beneficial to society. Your achievement is noteworthy for its utter lack of meaning.\" With heartfelt disapproval, Gallijaux & Joulet" },
    [170] = { name = "letter from Zeid", description = "\"Make your blade shine with even deeper darkness, and go to the lost mines. Once there, drown your blade in the waters that call the horrid beast. Only then shall I give you the power you so thirst for. If you lose your blade, go to the place we met, and it shall find you.\" -Zeid" },
    [171] = { name = "Shantotto's new spell", description = "A new and improved black magic spell that Doctor Shantotto modified. It looks like it still has its magical power." },
    [172] = { name = "Shantotto's ex-spell", description = "A new and improved black magic spell that Doctor Shantotto modified...or what's left of it, now that it has lost its magical power..." },
    [173] = { name = "bucket of divine paint", description = "A bucket of special paint you found in the Garlaige Citadel. It is needed to restore the statue of Altana to Her former glory." },
    [174] = { name = "letter from Virnage", description = "A letter of introduction from Friar Virnage to Eperdur in the cathedral." },
    [175] = { name = "spirit incense", description = "Incense created by the friar, Gantineux. It has the power to calm the souls of revenants." },
    [176] = { name = "Gantineux's letter", description = "A letter of introduction from Friar Gantineux to Eperdur in the cathedral." },
    [177] = { name = "seal of banishing", description = "A seal to banish the miasma of the dead through the white magic of the San d'Orian Cathedral." },
    [178] = { name = "magical pattern", description = "A magical pattern that models itself to fit the person who finds it." },
    [179] = { name = "Fei'Yin magic tome", description = "A tome of ancient magic that you found in the depths of Fei'Yin." },
    [180] = { name = "\"Sluice Surveyor Mk. I\"", description = "A magic doll entrusted to you by Professor Koru-Moru. It has been modified to help survey the Toraimarai Canal. It doesn't talk much, but makes a lot of annoying beeping sounds." },
    [181] = { name = "\"Foe Finder Mk. I\"", description = "The magic doll that was shut up inside of Castle Zvahl. Twenty years ago it was the life of Doctor Shantotto's exploration party ...or so it thought." },
    [182] = { name = "earthen charm", description = "The key to the Gate of Earth that exists below the central tower of the Horutoto Ruins." },
    [183] = { name = "letter from the Tenshodo", description = "\"Thief of renown, I have a job for you. Payment will be an item of premium quality. Let's make a deal that is mutually beneficial.\" Vauderame of the Tenshodo" },
    [184] = { name = "Tenshodo envelope", description = "A sealed document. It reads: \"I hereby enter into contract with the Tenshodo.\" For some reason, there is no signature. The package is addressed to Sneaking Tiger." },
    [185] = { name = "signed envelope", description = "A document with Sneaking Tiger's signature. A new clause was added to the end. It reads, \"I agree to all of the above. Signed, V.\"" },
    [186] = { name = "gang whereabouts note", description = "A note you received from Nanaa Mihgo. It has the whereabouts of the two remaining members of Atarefaunet's band of thieves written on it. The first is at the top of an old tower on the Sauromugue Champaign. The second is at the Goblins' Goblet in Jeuno." },
    [187] = { name = "first forged envelope", description = "Documents forged by Nanaa Mihgo. They're so well done that you cannot tell the difference between this and the Tenshodo's original envelope and letter." },
    [188] = { name = "second forged envelope", description = "Documents forged by Nanaa Mihgo. They're so well done that you cannot tell the difference between this and the Tenshodo's original envelope and letter." },
    [189] = { name = "first signed forged envelope", description = "Forged documents signed by Linzaza, one of the few remaining infamous gang members, whom you found at the top of a tower on the Sauromugue Champaign." },
    [190] = { name = "second signed forged envelope", description = "Forged documents signed by Pauluart, one of the few remaining infamous gang members, whom you gambled with at dice in Jeuno." },
    [191] = { name = "letter from Dalzakk", description = "\"Please retrieve the 'San d'Orian martial arts scroll' from a tent in Davoi, then bring it to my master, Oggbi.\" -Dalzakk" },
    [192] = { name = "San d'Orian martial arts scroll", description = "The content of this scroll describes in detail a form of martial art practiced by the people of San d'Oria." },
    [193] = { name = "bomb incense", description = "A little something from Hagain, the old Tenshodo thief from the Sailor's Stay in Mhaura. This is needed to smoke out bomb monsters from the ceiling of the Garlaige Citadel." },
    [194] = { name = "Perchond's envelope", description = "An envelope containing \"glittersand\" that you were asked to find by a knight called Perchond at the Ranguemont Pass. Sir Perchond has also included a personal letter, addressed to Semih Lafihna." },
    [195] = { name = "portal charm", description = "A key that allows you to enter the Sealed Portal beneath the central tower of the Horutoto Ruins by yourself." },
    [196] = { name = "Orcish dried food", description = "Orcish rations left to dry. While edible, they do not look appetizing." },
    [197] = { name = "old pocket watch", description = "Curilla's father, the red mage Rainemard, once used this watch. It ticks no more." },
    [198] = { name = "old boots", description = "These boots were given in return for the old watch. For some reason, they refuse to be worn." },
    [199] = { name = "Balga champion certificate", description = "A certificate that testifies the holder's victory over the Yagudo champion at the Balga Contest. The certificate is signed by Kaa Toru the Just." },
    [200] = { name = "Holy One's oath", description = "A document received from Kaa Toru the Just. This document, written by the Yagudo Holy One, is addressed to the Star Sibyl of Windurst, and contains details pertaining to the Oztroja offerings." },
    [201] = { name = "crawler blood", description = "Blood believed to cleanse the foulest of things when poured on the earth of the Crawlers' Nest." },
    [202] = { name = "Cat Burglar's note", description = "A memo you received from Nanaa Mihgo. It gives the whereabouts of two of the eight thieves from the Tenshodo: û Yatniel is casing the shop, 'Gems by Kshama,' in Jeuno. û Hagain is resting at the Sailor's Stay in Mhaura." },
    [203] = { name = "chieftainness's twinstone earring", description = "One of the pair of matching twin- stone earrings that the Mithra tribal chieftainness, Perih Vashai, entrusted you with. You have been asked to hand it to Semih Lafihna." },
    [204] = { name = "northern vine", description = "A rough-skinned vine taken from the northern side of the Firebloom Tree." },
    [205] = { name = "southern vine", description = "A smooth-skinned vine taken from the southern side of the Firebloom Tree." },
    [206] = { name = "eastern vine", description = "A shiny-skinned vine taken from the eastern side of the Firebloom Tree." },
    [207] = { name = "western vine", description = "A prickly-skinned vine taken from the western side of the Firebloom Tree." },
    [208] = { name = "sword grip material", description = "A rare material used to strengthen sword hilts." },
    [209] = { name = "Yasin's sword", description = "A sword that belonged to Phara's son. She has asked you to deliver it to her grandson, \"Naji the Doorman.\"" },
    [210] = { name = "old gauntlets", description = "A pair of old and filthy gauntlets. Even if you could, you wouldn't want to equip them." },
    [211] = { name = "shadow flames", description = "Flames from a torch in Castle Zvahl. Borghertz has asked you to bring these to him." },
    [212] = { name = "Firebloom Tree wood", description = "Wood from the Firebloom Tree located in the Yuhtunga Jungle. This special material will not burn, even in the hottest of flames." },
    [213] = { name = "letter to Angelica", description = "A letter written by Kazham chieftainness Jakoh Wahcondalo to the Windurstian artist, Angelica. It explains, in detail, the horrors that lie within the Temple of Uggalepih." },
    [214] = { name = "\"Final Fantasy\"", description = "A powerful painting done by the aspiring young artist, Angelica. According to her, it is her most moving piece to date." },
    [215] = { name = "ripped \"Final Fantasy\" painting", description = "The torn remains of Angelica's \"most moving piece to date.\"" },
    [216] = { name = "\"Final Fantasy Part II\"", description = "An even more powerful painting done by the aspiring young artist, Angelica. Obviously, it was not the \"final\" \"Final Fantasy.\"" },
    [217] = { name = "tamer's whistle", description = "A whistle used in ancient times to tame the most ferocious beasts." },
    [218] = { name = "knight's boots", description = "A pair of boots you found in the bowels of a fish. They're too filthy and worn to wear." },
    [219] = { name = "Mique's paintbrush", description = "The brush used by legendary artist Mique. Desired by painters everywhere." },
    [220] = { name = "strange sheet of paper", description = "It appears to be blank." },
    [221] = { name = "knight's confession", description = "A secret letter from Royal Knight Chursarlaud to his captain, Exoroche. In it, he confesses to conspiring with his fellow knight Vilbert to betray the knights. The words appear only when soaked with water from the Orcs' well." },
    [222] = { name = "round frigicite", description = "A piece of frigicite found in a dark cave in Xarcabard." },
    [223] = { name = "square frigicite", description = "A piece of frigicite found in a dark cave in Xarcabard." },
    [224] = { name = "triangular frigicite", description = "A piece of frigicite found in a dark cave in Xarcabard." },
    [225] = { name = "star ring", description = "A ring given to you by the spirit of a bard in the Eldieme Necropolis. It is too tarnished to read the inscription." },
    [226] = { name = "star ring", description = "A ring given to you by the spirit of a bard in the Eldieme Necropolis. You cannot decipher the inscription on it." },
    [227] = { name = "moon ring", description = "This ring was formerly owned by a queen of San d'Oria. It is a pair with the star ring." },
    [228] = { name = "Mertaire's bracelet", description = "A bracelet given to Mertaire by a lost love." },
    [229] = { name = "aquaflora", description = "A flower offered to the spirits of animals that died in battle. One of a set of three." },
    [230] = { name = "aquaflora", description = "A flower offered to the spirits of animals that died in battle. One of a set of three." },
    [231] = { name = "aquaflora", description = "A flower offered to the spirits of animals that died in battle. One of a set of three." },
    [232] = { name = "guiding bell", description = "This bell is believed to guide the souls of pets to Paradise." },
    [233] = { name = "Ordelle whetstone", description = "A stone from Ordelle's Caves. Can make even the dullest blade razor- sharp. Prized by chefs everywhere." },
    [234] = { name = "letter from the Darksteel Forge", description = "This letter requests for the book on darksteel manufacturing to be returned to the forge." },
    [235] = { name = "\"Darksteel Formula\"", description = "A Galkan book describing the intricate process of manufacturing darksteel. The author's name is Gerwitz." },
    [236] = { name = "Koh's letter", description = "A letter from Koh Lenbalalako of Mhaura. A gold earring is enclosed." },
    [237] = { name = "Royal Knights' Davoi report", description = "Vital intelligence on Orcish activity throughout Davoi, gathered by the Royal Knights." },
    [238] = { name = "Sacrificial Chamber key", description = "This key opens the door to the Sacrificial Chamber located deep in the Temple of Uggalepih. It was entrusted to you by the Kazham chieftainness, Jakoh Wahcondalo." },
    [239] = { name = "fire fragment", description = "This crystal fragment, retrieved from the cermet headstone in the Yuhtunga Jungle, glows red with the power of fire. There are eight fragments in total." },
    [240] = { name = "water fragment", description = "This crystal fragment, retrieved from the cermet headstone in the La Theine Plateau, glows blue with the power of water. There are eight fragments in total." },
    [241] = { name = "earth fragment", description = "This crystal fragment, retrieved from the cermet headstone in the Western Altepa Desert, glows yellow with the power of earth. There are eight fragments in total." },
    [242] = { name = "wind fragment", description = "This crystal fragment, retrieved from the cermet headstone in Cape Teriggan, glows green with the power of wind. There are eight fragments in total." },
    [243] = { name = "lightning fragment", description = "This crystal fragment, retrieved from the cermet headstone in the Behemoth's Dominion, glows purple with the power of lightning. There are eight fragments in total." },
    [244] = { name = "ice fragment", description = "This crystal fragment, retrieved from the cermet headstone in the Cloister of Frost, glows blue with the power of ice. There are eight fragments in total." },
    [245] = { name = "light fragment", description = "This crystal fragment, retrieved from the cermet headstone in the Sanctuary of Zi'Tah, glows white with the power of light. There are eight fragments in total." },
    [246] = { name = "dark fragment", description = "This crystal fragment, given to you by Grav'iton, glows with the power of darkness. There are eight fragments in total." },
    [247] = { name = "prismatic fragment", description = "This crystal fragment, given to you by the Dawnmaidens, glows with all the colors of the rainbow." },
    [248] = { name = "southwestern star charm", description = "A key to the laboratory that lies beneath the southwestern magic tower of the Horutoto Ruins. It magically disappears upon use." },
    [249] = { name = "Holy One's invitation", description = "An invitation to the Balga Contest held at the Balga's Dais in Giddeus. Balga's Dais cannot be entered without this invitation." },
    [250] = { name = "Optistery ring", description = "The ring entrusted to the Minister of the Optistery. It bears the Optistery's mark." },
    [251] = { name = "blank Book of the Gods", description = "The Optistery minister, Tosuka-Porika, has entrusted you with this Book of the Gods that has gone blank." },
    [252] = { name = "Book of the Gods", description = "Some of the magical properties of this book have been restored by a wise woman whom you met at the Temple of Uggalepih. You sense an evil force running through the book, but it is not strong enough to cause any fatalities." },
    [253] = { name = "Nonberry's knife", description = "A knife found on a Tonberry cook in Temple of Uggalepih. It can cut almost anything!" },
    [254] = { name = "sublime statue of the Goddess", description = "A statue of the Dawn Goddess, made by the sculptor Mulaujeant from a slab of Elshimo marble. The sheer beauty of this masterpiece strikes a chord in the hearts of all who lay their eyes upon it." },
    [255] = { name = "Rauteinot's parcel", description = "A parcel from Rauteinot, a young missionary sent to Kazham by the San d'Orian Cathedral. The package contains a slab of Elshimo marble and a letter to the San d'Orian sculptor, Mulaujeant." },
    [256] = { name = "treasure map", description = "A piece of paper Magriffon calls \"a map to hidden pirate treasure.\" Some strange numbers are written upon it. (F-7)(H-10)(I-12)" },
    [257] = { name = "strangely shaped coral", description = "A strangely shaped piece of coral you found in the Korroloka Tunnel." },
    [258] = { name = "sealed dagger", description = "A seal has been placed upon this blade, making it impossible to unsheathe." },
    [259] = { name = "Angelica's letter", description = "A letter written by Windurstian artist Angelica to the Kazham chieftainness. The handwriting is so terrible, it is almost impossible to read." },
    [260] = { name = "empty barrel", description = "An empty barrel you received from Washu." },
    [261] = { name = "barrel of Opo-Opo brew", description = "This barrel from Washu contains a special brew made by the Opo-opos." },
    [262] = { name = "Elshimo Lowlands supplies", description = "Deliver these supplies to the guards manning the Elshimo Lowlands Outpost before the next conquest results are tallied." },
    [263] = { name = "Elshimo Uplands supplies", description = "Deliver these supplies to the guards manning the Elshimo Uplands Outpost before the next conquest results are tallied." },
    [264] = { name = "joker card", description = "A card you found in the Toraimarai Canal. The pierrot drawn on the front is dancing a strange jig." },
    [265] = { name = "Orastery ring", description = "The ring entrusted to the Minister of the Orastery. It bears the Orastery's mark." },
    [266] = { name = "Altepa moonpebble", description = "This stone you found in the Altepa Desert glows only at night." },
    [267] = { name = "Rhinostery certificate", description = "This certificate with the signature of four researchers states you have been officially licensed by the Rhinostery. Now you should have clearance to the area behind the Priming Gate in Windurst Walls." },
    [268] = { name = "dreamrose", description = "In her will, the late Queen Leaute asked that this flower forever bloom in her chateau garden. The pollen of the dreamrose is said to cause hallucinations." },
    [269] = { name = "ancient San d'Orian book", description = "An ancient tome discovered in the alleged true tomb of King Ranperre. Not only is it written in ancient San d'Orian, but it is also in code." },
    [270] = { name = "piece of paper", description = "A message found in Queen Leaute's garden. It reads, \"When faced with deceit, often the truth lies behind your back.\"" },
    [271] = { name = "invisible man sticker", description = "Just stick it on and fade from view! One of the seven items from the Junior Investigator's Toolkit made by Chamama. Not to be used for pranks." },
    [272] = { name = "paintbrush of souls", description = "A large paintbrush found in the library of the Temple of Uggalepih. It appears to harbor some mysterious power..." },
    [273] = { name = "old rusty key", description = "A key found in the library of the Temple of Uggalepih." },
    [274] = { name = "ancient tablet fragment", description = "A flat piece of stone found in the Quicksand Caves. It has ancient writing on it and seems to be part of a tablet." },
    [275] = { name = "\"Star Seeker\"", description = "A magic doll lent to you by the Aurastery. It is empowered to track the magical emanations of the ring of the Aurastery minister. The doll will suddenly give directions when you change areas, so you must be careful to pay attention." },
    [276] = { name = "Aurastery ring", description = "The ring entrusted to the Minister of the Aurastery. It bears the Aurastery's mark." },
    [277] = { name = "tablet of ancient magic", description = "A tablet reconstructed from pieces found in the Quicksand Caves. Ancient magic is inscribed on its surface." },
    [278] = { name = "letter from Alfesar", description = "A letter of introduction from Friar Alfesar to Charlaimagnat in the cathedral." },
    [279] = { name = "magic-drained \"Star Seeker\"", description = "A magic doll lent to you by the Aurastery. The magic in the doll has been drained by Sedal-Godjal." },
    [280] = { name = "Rhinostery ring", description = "The ring entrusted to the Minister of the Rhinostery. It bears the Rhinostery's mark." },
    [281] = { name = "Manustery ring", description = "The ring entrusted to the Minister of the Manustery. It bears the Manustery's mark." },
    [282] = { name = "glove of perpetual twilight", description = "This glove must be worn in order to utilize the power of the five ministry rings. Each ring is worn on a different finger. Apururu is the only Tarutaru capable of putting on the glove." },
    [283] = { name = "ancient San d'Orian tablet", description = "A tablet inscribed with a code written in ancient San d'Orian. The characters are beyond comprehension." },
    [284] = { name = "crystal dowser", description = "An instrument comprising a crystal attached to a string. Orcs used this to search for Lightbringer." },
    [285] = { name = "piece of a broken key", description = "A piece of a broken key found in the Temple of Uggalepih." },
    [286] = { name = "piece of a broken key", description = "A piece of a broken key found in the Temple of Uggalepih." },
    [287] = { name = "piece of a broken key", description = "A piece of a broken key found in the Temple of Uggalepih." },
    [288] = { name = "drops of Amnio", description = "Water used in the d'Oraguille coming- of-age ceremony. They say one enters adulthood when the water breaks." },
    [289] = { name = "reinforced cermet", description = "This cermet has been reinforced with ancient Zilart techniques." },
    [290] = { name = "letter from Werei", description = "\"To my dear friend Gumbah... Werei\"" },
    [291] = { name = "Tonberry key", description = "A key to a small room in the Temple of Uggalepih where a Tonberry priest sits trapped." },
    [292] = { name = "thesis on alchemy", description = "A graduation thesis written on the subject of alchemy. However, the Aurastery student who turned this in forgot to put their name on it. \"See me in my office, immediately!\" is printed on the bottom in red ink." },
    [293] = { name = "old piece of wood", description = "\"To whoever may find this... Werei\"" },
    [294] = { name = "dragon curse remedy", description = "A folk remedy said to remove a dragon's curse. Its efficacy is highly dubious." },
    [295] = { name = "sealed iron box", description = "This locked metallic box looks impossible to open by normal means." },
    [296] = { name = "sea serpent statue", description = "The Sahagin are said to worship this statue of a sea serpent." },
    [297] = { name = "Altepa polishing stone", description = "Said to be the only stone capable of restoring a sheen to metals that are no longer used." },
    [298] = { name = "challenge to the Royal Knights", description = "A letter addressed to the Royal Knights. \"The helm of the last dragoon is already in my possession. I will lay bare the inadequacies of the Royal Knights' current leadership and their inability to defend San d'Oria...\"" },
    [299] = { name = "Ranchuriome's legacy", description = "Brugaire's inheritance from his father, Ranchuriome. It is a wooden box containing some sort of heavy object." },
    [300] = { name = "Ronfaure EF insignia", description = "An insignia of the expeditionary force. The inscription on the back reads, \"Perform the following: -Locate and destroy the enemy. -Raid the target's treasure chests. -Seek battles yielding high experience. You will be rewarded upon your victory.\"" },
    [301] = { name = "Zulkheim EF insignia", description = "An insignia of the expeditionary force. The inscription on the back reads, \"Perform the following: -Locate and destroy the enemy. -Raid the target's treasure chests. -Seek battles yielding high experience. You will be rewarded upon your victory.\"" },
