    [309] = { name = "Valdeaunia EF insignia", description = "An insignia of the expeditionary force. The inscription on the back reads, \"Perform the following: -Locate and destroy the enemy. -Raid the target's treasure chests. -Seek battles yielding high experience. You will be rewarded upon your victory.\"" },
