    [312] = { name = "Kuzotz EF insignia", description = "An insignia of the expeditionary force. The inscription on the back reads, \"Perform the following: -Locate and destroy the enemy. -Raid the target's treasure chests. -Seek battles yielding high experience. You will be rewarded upon your victory.\"" },
    [313] = { name = "Vollbow EF insignia", description = "An insignia of the expeditionary force. The inscription on the back reads, \"Perform the following: -Locate and destroy the enemy. -Raid the target's treasure chests. -Seek battles yielding high experience. You will be rewarded upon your victory.\"" },
    [314] = { name = "Elshimo Lowlands EF insignia", description = "An insignia of the expeditionary force. The inscription on the back reads, \"Perform the following: -Locate and destroy the enemy. -Raid the target's treasure chests. -Seek battles yielding high experience. You will be rewarded upon your victory.\"" },
    [315] = { name = "Elshimo Uplands EF insignia", description = "An insignia of the expeditionary force. The inscription on the back reads, \"Perform the following: -Locate and destroy the enemy. -Raid the target's treasure chests. -Seek battles yielding high experience. You will be rewarded upon your victory.\"" },
    [316] = { name = "KEY ITEM", description = "DESCRIPTION" },
    [317] = { name = "KEY ITEM", description = "DESCRIPTION" },
    [318] = { name = "KEY ITEM", description = "DESCRIPTION" },
    [319] = { name = "KEY ITEM", description = "DESCRIPTION" },
    [320] = { name = "whisper of flames", description = "You can sense its presence, but it cannot be seen." },
    [321] = { name = "whisper of tremors", description = "You can sense its presence, but it cannot be seen." },
    [322] = { name = "whisper of tides", description = "You can sense its presence, but it cannot be seen." },
    [323] = { name = "whisper of gales", description = "You can sense its presence, but it cannot be seen." },
    [324] = { name = "whisper of frost", description = "You can sense its presence, but it cannot be seen." },
