    [510] = { name = "mannequin joint diagrams", description = "These diagrams show how to connect a wooden mannequin's parts using a set of complicated metal joints." },
    [511] = { name = "clamming kit", description = "This set comes complete with a scoop for scooping and a bucket for storing all the shellfish you find. A label on the bucket reads: \"Do not remove from island under penalty of death.\"" },
