    [576] = { name = "Ballista License", description = "Your participation in Ballista has been approved by the three nations of Bastok, San d'Oria, and Windurst." },
    [577] = { name = "Ballista Instawarp", description = "Show this ticket to any Ballista event staff to receive a free warp back to your home point. An Instawarp can only be used once and cannot be used while participating in a Ballista match." },
    [578] = { name = "Ballista Instaport", description = "Show this ticket to any Ballista event staff to receive a free teleport to the area where the next match is taking place. An Instaport can only be used once and cannot be used while participating in a Ballista match." },
    [579] = { name = "mysterious amulet", description = "The strange boy gave you this amulet before leaving Dr. Monberaux's clinic. Your body tingles when you clench it in your hand." },
    [580] = { name = "mysterious amulet", description = "The strange boy gave you this amulet before leaving Dr. Monberaux's clinic. You feel that the glow of its power is weaker than before." },
    [581] = { name = "cracked Mimeo Mirror", description = "An unusual mirror owned by Honoi-Gomoi. It is said to reflect the memories of the person who gazes into its glassy surface. Or it would, if it weren't so badly cracked." },
    [582] = { name = "reliquiarium key", description = "This elaborately decorated key supposedly opens the door to the Sacrarium's reliquiarium." },
    [583] = { name = "Mimeo Stone", description = "A glowing stone found in the Attohwa Chasm. The light from the stone seems to be pointing to the top of Parradamo Tor." },
    [584] = { name = "mystic ice", description = "This magical ice is said to harbor the power to call forth powerful winds." },
    [585] = { name = "KEY ITEM", description = "It's spiffier than cheese!" },
    [586] = { name = "Mimeo Jewel", description = "A strange jewel obtained in the Attohwa Chasm. A tiny flame can sometimes be seen dancing within the gem. Taking this jewel to a certain place should transform it into a different item." },
    [587] = { name = "Mimeo Feather", description = "An ancient power sleeping within the earth has metamorphosed the Mimeo Jewel into this beautiful feather. The first feather of three." },
    [588] = { name = "second Mimeo Feather", description = "An ancient power sleeping within the earth has metamorphosed the Mimeo Jewel into this beautiful feather. The second feather of three." },
    [589] = { name = "third Mimeo Feather", description = "An ancient power sleeping within the earth has metamorphosed the Mimeo Jewel into this beautiful feather. The third feather of three." },
    [590] = { name = "light of Holla", description = "This glow represents the courage radiating from your heart." },
    [591] = { name = "light of Dem", description = "This glow represents the justice radiating from your heart." },
    [592] = { name = "light of Mea", description = "This glow represents the trust radiating from your heart." },
    [593] = { name = "light of Vahzl", description = "This glow represents the hope radiating from your heart." },
    [594] = { name = "light of Al'Taieu", description = "This glow represents the compassion radiating from your heart." },
    [595] = { name = "blue bracelet", description = "The mysterious bracelet you found deep within Pso'Xja. It emits a faint blue glow that is only recognizable when you are in the ruins." },
    [596] = { name = "green bracelet", description = "The mysterious bracelet you found deep within Pso'Xja. It emits a light green sparkle that is only recognizable when you are in the ruins." },
    [597] = { name = "dusty tome", description = "A book obtained in Movalpolos. Its pages appear worn from being turned many times." },
    [598] = { name = "pointed jug", description = "A jug obtained in Movalpolos. You can hear some kind of liquid sloshing around inside." },
    [599] = { name = "cracked club", description = "A club obtained in Movalpolos. The cracks along its length speak of frequent use." },
    [600] = { name = "peeling hairpin", description = "A hairpin obtained in Movalpolos. It appears worthless at first glance due to the peeling lacquer, but closer inspection reveals intricate carvings on this masterful piece of jewelry." },
    [601] = { name = "old nametag", description = "A nametag obtained in Movalpolos. Do the Moblins need these to tell each other apart?" },
    [602] = { name = "tiny wristlet", description = "Several white magnolias have been carved in detail upon this small metal wristlet." },
    [603] = { name = "whispering conch", description = "The soft sound of the ocean can be heard when holding this deep-sea shell to one's ear." },
    [604] = { name = "Pso'Xja pass", description = "The slip of paper reads: \"You have been hereby granted permission by the Tenshodo to travel into the deeper areas of the Pso'Xja ruins.\"" },
    [605] = { name = "piece of ripped floorplans", description = "You believe the piece may be from the floorplans of the area you found it in." },
    [606] = { name = "limit breaker", description = "You have been recognized by Nomad Moogles across Vana'diel as having successfully broken your physical and mental limits." },
    [607] = { name = "hyper altimeter", description = "After seven long years of development, the aeronautic engineers of Jeuno have finally constructed an airship-specific altimeter that surpasses all those that came before it." },
    [608] = { name = "molybdenum box", description = "A heavy-duty case made with the rare metal known as molybdenum. It was given to you by Cid's assistant, Raibaht." },
    [609] = { name = "alabaster hairpin", description = "You found this expensive-looking hairpin in the Tavnazian Safehold. Several intricate engravings appear when you hold it to the light." },
    [610] = { name = "Dawn talisman", description = "This talisman bears the same symbol as the holy tome printed by the San d'Orian Cathedral." },
    [611] = { name = "Silver Comet's collar", description = "This collar was found on the grave of a general's son in Batallia Downs. It bears the name \"Silver Comet.\"" },
    [612] = { name = "envelope from Monberaux", description = "Doctor Monberaux has asked you to deliver this message to Ducal Guard Captain Wolfgang. Inside is a tiny slip of paper with a drawing of what looks like Batallia Downs and the inscription \"K9N.\"" },
    [613] = { name = "Delkfutt recognition device", description = "This card-shaped key is needed to unlock a door in Delkfutt's Tower that leads to a secret laboratory." },
    [614] = { name = "deed to Purgonorgo Isle", description = "The deed dropped by the warmachine on Purgonorgo Isle. It seems to bear some relation to the purchase of the tropical island, but the language is beyond your understanding." },
    [615] = { name = "Phoenix armlet", description = "Enormous power is contained within this armlet. It should be strong enough to open the gate that lies in the deepest part of the Pso'Xja ruins." },
    [616] = { name = "Phoenix pearl", description = "Enormous power is contained within this pearl. It should be strong enough to seal the gate that lies in the deepest part of the Pso'Xja ruins." },
    [617] = { name = "manaclipper ticket", description = "A manaclipper boarding pass issued by the Fishermen's Guild." },
    [618] = { name = "barge ticket", description = "A barge boarding pass issued by the Carpenters' Guild." },
    [619] = { name = "All-You-Can-Ride Pass", description = "For GM use only!" },
    [620] = { name = "Tavnazian Archipelago supplies", description = "Deliver these supplies to the guards manning the Tavnazian Archipelago Outpost before the next conquest results are tallied." },
    [621] = { name = "Rivernewort", description = "Said only to be found on Cape Riverne, this rare spice is renowned for its flavor-enhancing qualities." },
    [622] = { name = "Tavnazian cookbook", description = "This appears to be an extremely old book on how to prepare several traditional Tavnazian dishes. Since it was written before the Age of Adventurers, it does not detail how to prepare the recipes using synthesis." },
    [623] = { name = "Washu's flask", description = "A flask you received from Washu. You have been asked to fill it with water from the giant clams in Korroloka Tunnel." },
    [624] = { name = "flask of clam water", description = "This flask is filled with water taken from the giant clams in Korroloka Tunnel." },
    [625] = { name = "pungent providence pot", description = "The odor coming from this pot convinces others that the bearer is actually a Goblin. The terrible smell also serves to keep away pot enthusiasts..." },
    [626] = { name = "torn-out pages", description = "Several pages from a book written by Lord Torresapet B Ordelle on the life of Gwynham Ironheart. These pages were said to have been torn out by Gwynham's daughter Enid." },
    [627] = { name = "Tonberry blackboard", description = "This blackboard is used to communicate with Riche, a Tonberry who is employed as a Carpenters' Landing barge captain." },
    [628] = { name = "letter from Muckvix", description = "A letter from Muckvix addressed to Magriffon, a tactician living in Kazham." },
    [629] = { name = "letter from Magriffon", description = "A letter from Magriffon addressed to Muckvix, a Goblin living in Jeuno. The letter supposedly contains a brilliant idea." },
    [630] = { name = "providence pot", description = "This pot is said to bring astounding fortune upon the bearer. An object of envy for all pot enthusiasts." },
    [631] = { name = "care package", description = "This gift is covered with beautiful wrapping paper, but it appears to have been rewrapped many times. The shape of the package suggests a potion or medicine of some sort." },
    [632] = { name = "glittering fragment", description = "A brightly glittering fragment said to have been left by the ancients. To be used as evidence that the Moblins have discovered a mothercrystal deep beneath the earth." },
    [633] = { name = "storeroom key", description = "The key to a storeroom near the entrance of Norg. For some reason, the key is covered in teeth marks." },
    [634] = { name = "Zeelozok's earplug", description = "An earplug dropped by Zeelozok in Castle Zvahl. It has been designed to emit sound waves." },
