    [669] = { name = "vessel of light", description = "A sacred vessel kept in Tavnazia for generations. Originally one of the crystal devices created by the ancients, it is a weapon used to smite the Emptiness with the light of the crystals. Also known as the Eye of Altana." },
    [670] = { name = "censer of abandonment", description = "The aroma of incense burned in this vessel is said to attract Empty living deep within Promyvion - Holla." },
    [671] = { name = "censer of antipathy", description = "The aroma of incense burned in this vessel is said to attract Empty living deep within Promyvion - Dem." },
    [672] = { name = "censer of animus", description = "The aroma of incense burned in this vessel is said to attract Empty living deep within Promyvion - Mea." },
    [673] = { name = "censer of acrimony", description = "The aroma of incense burned in this vessel is said to attract Empty living deep within Promyvion - Vahzl." },
    [674] = { name = "monarch beard", description = "A scale ripped from the jaw of a mighty wyrm while it was sleeping. Can be used to provoke the fury of a dragon." },
    [675] = { name = "astral covenant", description = "Placing this sheet of parchment on the altar of the Shrouded Maw is said to open a portal to a parallel dimension." },
    [676] = { name = "shaft 2716 operating lever", description = "Use this lever to open the gate leading into Mine Shaft #2716." },
    [677] = { name = "zephyr fan", description = "This seemingly normal fan has the power to temporarily stop the torrential winds that block the path leading into the Bearclaw Pinnacle caves." },
    [678] = { name = "miasma filter", description = "Allows its wearer to bear the poisonous gasses surrounding Boneyard Gully." },
    [679] = { name = "particularly poignant petal", description = "While supposedly a powerful medicine, its odor alone is enough to make one ill." },
    [680] = { name = "antique amulet", description = "An amulet that belonged to Despachiaire's late wife. The origin of this old piece of jewelry is unknown." },
    [681] = { name = "cathedral medallion", description = "An antique amulet that has been polished to a sheen. An inscription is faintly visible on the face of the amulet." },
    [682] = { name = "gold Ballista chevron", description = "Presented only to those who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [683] = { name = "mythril Ballista chevron", description = "Presented only to those who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [684] = { name = "silver Ballista chevron", description = "Presented only to those who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after set period indicated in official Ballista rulebook." },
    [685] = { name = "bronze Ballista chevron", description = "Presented only to those who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [686] = { name = "bloody Ballista chevron", description = "Presented only to those warriors who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [687] = { name = "orange Ballista chevron", description = "Presented only to those monks who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [688] = { name = "white Ballista chevron", description = "Presented only to those white mages who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [689] = { name = "black Ballista chevron", description = "Presented only to those black mages who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [690] = { name = "red Ballista chevron", description = "Presented only to those red mages who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [691] = { name = "green Ballista chevron", description = "Presented only to those thieves who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [692] = { name = "sparking Ballista chevron", description = "Presented only to those paladins who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [693] = { name = "ebon Ballista chevron", description = "Presented only to those dark knights who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [694] = { name = "furry Ballista chevron", description = "Presented only to those beastmasters who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [695] = { name = "brown Ballista chevron", description = "Presented only to those bards who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [696] = { name = "ochre Ballista chevron", description = "Presented only to those rangers who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [697] = { name = "jade Ballista chevron", description = "Presented only to those samurais who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [698] = { name = "transparent Ballista chevron", description = "Presented only to those ninjas who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [699] = { name = "purple Ballista chevron", description = "Presented only to those dragoons who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [700] = { name = "rainbow Ballista chevron", description = "Presented only to those summoners who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [701] = { name = "letters from Ulmia and Prishe", description = "A bundle of letters from Ulmia and Prishe addressed to the people of the safehold. Prishe has scrawled a smiley face on the back of each of the envelopes." },
    [702] = { name = "Petra eater voucher", description = "This coupon will automatically be exchanged for one free temporary item at the start of your next Ballista match. ;Match level restrictions may prevent the exchange." },
    [703] = { name = "catholicon voucher", description = "This coupon will automatically be exchanged for one free temporary item at the start of your next Ballista match. ;Match level restrictions may prevent the exchange." },
    [704] = { name = "red oil", description = "This rare variety of oil was once widely used to lubricate intricate machinery such as mannequins. However, due to the oil's grotesque apperance, production ceased many years ago." },
    [705] = { name = "Marble Bridge coaster", description = "Thanks to the schedule written up on the back of this coaster, you'll know if you can enter the Marble Bridge the moment you step into Upper Jeuno." },
    [706] = { name = "lamp lighter's membership card", description = "When in Lower Jeuno, this card entitles you to hear the recruiting announcement for lamp lighter volunteers." },
    [707] = { name = "shaft gate operating dial", description = "When fitted into the gate leading to Mine Shaft #2716, this jeweled dial can be used to rotate the passages, allowing travel to different rooms." },
    [708] = { name = "mysterious amulet", description = "The amulet given to you by Prishe. Your body tingles when you clench it in your hand." },
    [709] = { name = "mire incense", description = "This natural variety of incense is formed from decaying marsh reeds. When lit, it gives off a strange odor that is said to have supernatural properties." },
    [710] = { name = "Brand of Dawn", description = "The sign of the Dawn Goddess, burned into your mind in the Garden of Ru'Hmet." },
    [711] = { name = "Brand of Twilight", description = "The sign of the Twilight God, burned into your mind in the Garden of Ru'Hmet." },
    [712] = { name = "ornamented scroll", description = "Strange diagrams fill this aged parchment scroll decorated with a beautifully carved jade fastener." },
    [713] = { name = "Better Humes and Mannequins", description = "A tattered copy of a magazine once popular among mannequin craftsmen. Its pages are filled with numerous sketches of various mannequin poses." },
    [714] = { name = "Petra Shovel", description = "When carrying this during a Ballista match, any temporary item you quarry will be automatically placed into your inventory. An item will also be automatically thrown away if you are unable to carry it." },
    [715] = { name = "Caliginous Blade", description = "Gubokka found this blade on the Hume warrior Vigsterkr. It was used by the man who saved Vigsterkr's life." },
    [716] = { name = "Tear of Altana", description = "A divine tear residing within your heart that fills you with love eternal." },
    [717] = { name = "Ballista Band", description = "When wearing this during a Ballista match, you will have the choice of keeping or throwing away the first Petra you quarry." },
    [718] = { name = "Shaded Cruse", description = "A golden pot that appears to be of great value. Wazozo has kept it hidden well, claiming it as her prized treasure. However, it was recently shattered into several pieces." },
    [719] = { name = "letter from Shikaree X", description = "I challenge you to a duel in Boneyard Gully. Let's see what you're made of! Shikaree X" },
    [720] = { name = "Monarch Linn Patrol Permit", description = "A permit given to you by Justinius. Allows the bearer access to Monarch Linn." },
    [721] = { name = "letter from Shikaree Y", description = "I challenge you to a duel in Boneyard Gully. Not afraid of me, are you, sugarplum? Shikaree Y" },
    [722] = { name = "letter from the Mithran Trackers", description = "You are cordially invited to a training session in Boneyard Gully. We await your arrival. Mhag Shikaree Y Shikaree X" },
    [723] = { name = "communication from Tzee Xicu", description = "A missive written by the Yagudo leader, Tzee Xicu the Manifest. It is stored in a oddly shaped container that resembles one of the Orcs' cryptexes." },
    [724] = { name = "Orcish seeker bats", description = "These extremely intelligent bats are used by Orcish troopers and cursemakers to spy on enemies and gather information." },
    [725] = { name = "vault quipus", description = "A colorful knotted rope normally used by the Yagudo to relay messages. According to Hooknox, this one can be used as a key..." },
    [726] = { name = "Goblin recommendation letter", description = "A letter of recommendation written by a Goblin scribe for Shieldwarrior deserter Gu'Zho Thunderblade. You cannot decipher the rows of strange markings that cover this ragged piece of parchment." },
    [727] = { name = "costume kit", description = "The magical disguise kit beloved by Miledo-Shiraddo. The kit contains a \"knitted cap\" allowing the wearer to appear as a child, a pair of \"spectacles\" to transform into an old man, and a pair of \"silver heels\" for the shape of an attractive lady." },
    [728] = { name = "jar of reversion dust", description = "An item created for those who have meddled in shapechanging. Using this magical dust will allow any being to return to their original form." },
    [729] = { name = "remedy voucher", description = "This coupon will automatically be exchanged for one free temporary item at the start of your next Ballista match. ;Match level restrictions may prevent the exchange." },
    [730] = { name = "panacea voucher", description = "This coupon will automatically be exchanged for one free temporary item at the start of your next Ballista match. ;Match level restrictions may prevent the exchange." },
    [731] = { name = "smelling salts voucher", description = "This coupon will automatically be exchanged for one free temporary item at the start of your next Ballista match. ;Match level restrictions may prevent the exchange." },
    [732] = { name = "vitrallum", description = "A metal similar to the material used to create the Mirror of Blighted Gloom. Remains in liquid form at room temperature." },
    [733] = { name = "opalescent stone", description = "This stone can be ground and liquefied into paint that glistens like a pearl." },
    [734] = { name = "Cosmo-Cleanse", description = "A somewhat doubtful alchemy product of the Near East." },
    [735] = { name = "old woman's portrait", description = "Angelica created this portrait using paint made from an opalescent stone." },
    [736] = { name = "glimmering mica", description = "This flat piece of stone is perfect for burning incense. When heated, it begins to glow with a soft, blue-white light." },
    [737] = { name = "mistroot", description = "When thrown onto a flame, this plant creates a cloud of wispy, aromatic smoke." },
    [738] = { name = "lunascent log", description = "When this wood is dried and then burned, it gives off a fragrance reminiscent of a crisp winter night." },
    [739] = { name = "Dynamis - Valkurm sliver", description = "A darkly glowing sliver of black crystal." },
    [740] = { name = "Dynamis - Buburimu sliver", description = "A darkly glowing sliver of black crystal." },
    [741] = { name = "Dynamis - Qufim sliver", description = "A darkly glowing sliver of black crystal." },
    [742] = { name = "Dynamis - Tavnazia sliver", description = "A darkly glowing sliver of black crystal." },
    [743] = { name = "red Sentinel badge", description = "A list of characters are visible on the surface of the badge. S: G8, J9, I8, I8, K5 N: E4, J8, J8, H8, I9 P: J8, H8, H10, H8, G7 C: I9, H9, I9, F7, H7" },
    [744] = { name = "blue Sentinel badge", description = "A list of characters are visible on the surface of the badge. Mi: H6, I7, H5, I6, H9 Ma: I9, J10, K10, E11, E10 P: F6, J5, F8, E6, F5 Me: G7, G8, K7, I8, G8" },
    [745] = { name = "green Sentinel badge", description = "A list of characters are visible on the surface of the badge. Wat: G4, G9, F9, F10, F8 Wal: J11, J6, K7, H3, F5 P: M6, F6, E7, E7, G7 Wo: I5, I10, J3, J13, H10" },
    [746] = { name = "white Sentinel badge", description = "A list of characters are visible on the surface of the badge. R: H9, G8, G7, I6, H7 U: G7, G8, G8, H9, H9 L: G10, H10, I7, J7, H9 P: I8, G8, I8, H8, H8" },
    [747] = { name = "eye of flames", description = "An inexplicable and inescapable gaze that you can sense but cannot see." },
    [748] = { name = "eye of tremors", description = "An inexplicable and inescapable gaze that you can sense but cannot see." },
    [749] = { name = "eye of tides", description = "An inexplicable and inescapable gaze that you can sense but cannot see." },
    [750] = { name = "eye of gales", description = "An inexplicable and inescapable gaze that you can sense but cannot see." },
    [751] = { name = "eye of frost", description = "An inexplicable and inescapable gaze that you can sense but cannot see." },
    [752] = { name = "eye of storms", description = "An inexplicable and inescapable gaze that you can sense but cannot see." },
    [753] = { name = "red invitation card", description = "An invitation card received from a Salaheem's Sentinels representative. You remember something about their headquarters being in a place called Al Zahbi..." },
    [754] = { name = "blue invitation card", description = "An invitation card received from a Salaheem's Sentinels representative. You remember something about their headquarters being in a place called Al Zahbi..." },
    [755] = { name = "green invitation card", description = "An invitation card received from a Salaheem's Sentinels representative. You remember something about their headquarters being in a place called Al Zahbi..." },
    [756] = { name = "white invitation card", description = "An invitation card received from a Salaheem's Sentinels representative. You remember something about their headquarters being in a place called Al Zahbi..." },
    [757] = { name = "healing powder voucher", description = "This coupon will automatically be exchanged for one free temporary item at the start of your next Ballista match. ;Match level restrictions may prevent the exchange." },
    [758] = { name = "Brenner Shovel", description = "When carrying this during a Brenner match, any temporary item you quarry will be automatically placed into your inventory. An item will also be automatically thrown away if you are unable to carry it." },
    [759] = { name = "Brenner Band", description = "When wearing this during a Brenner match, you will have the choice of keeping or throwing away the first Petra you quarry." },
    [760] = { name = "Silver Sea ferry ticket", description = "A ticket that allows you to board the ferry ship between Al Zahbi and Nashmau." },
    [761] = { name = "moonlight ore", description = "A chunk of light ore infused with the energy of the Ro'Maeve ruins. It pulses with powerful lunar radiance..." },
    [762] = { name = "Leujaoam Assault orders", description = "A document that authorizes you to take part in a Leujaoam Sanctum Assault mission." },
    [763] = { name = "Mamool Ja Assault orders", description = "A document that authorizes you to take part in a Mamool Ja Training Grounds Assault mission." },
    [764] = { name = "Lebros Assault orders", description = "A document that authorizes you to take part in a Lebros Cavern Assault mission." },
    [765] = { name = "Periqia Assault orders", description = "A document that authorizes you to take part in a Periqia Assault mission." },
    [766] = { name = "Ilrusi Assault orders", description = "A document that authorizes you to take part in an Ilrusi Atoll Assault mission." },
    [767] = { name = "Dkhaaya's research journal", description = "A journal filled with years of Dkhaaya's research notes on the Olduum civilization. The pages are covered in incomprehensible drawings accompanied by Dkhaaya's scribbled musings." },
    [768] = { name = "electrocell", description = "A small metallic container without a lid. According to Dkhaaya's research, it is possible to store the power of lighting within the electrocell. The process of harnessing the energy remains undeciphered." },
    [769] = { name = "electropot", description = "A pot made of magnetic materials. According to Dkhaaya's research, it is possible to draw iron sand into the pot through its spout." },
    [770] = { name = "electrolocomotive", description = "A toy-like, metallic object with four carriages. The results of Dkhaaya's research into the workings of the electrolocomotive have been applied in the animation of automatons." },
    [771] = { name = "Mark of Zahak", description = "A symbol depicting the Serpentking Zahak, a two-headed snake whose likeness graces the national flag of Aht Urhgan. This mark represents the awakening of a blue mage's powers." },
    [772] = { name = "vial of luminous water", description = "Usually a cloudy liquid, the water in this vial begins to glow brightly when exposed to the rays of the sun. A type of love potion." },
    [773] = { name = "image recorder", description = "This device captures images using a flash of bright light and an Ahriman lens." },
    [774] = { name = "cast metal plate", description = "A long, thin plate of metal you found in Mount Zhayolm. A distinctive pattern is inscribed upon its surface." },
    [775] = { name = "supplies package", description = "A bronze box entrusted to you by Naja Salaheem. It is sealed with animal glue, so you cannot see what it contains. You can hear something soft rolling around inside when you shake the box." },
    [776] = { name = "rainbow berry", description = "An invisible, legendary fruit." },
    [777] = { name = "sapphire Ballista chevron", description = "Presented only to those blue mages who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [778] = { name = "coral Ballista chevron", description = "Presented only to those corsairs who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [779] = { name = "silk Ballista chevron", description = "Presented only to those puppetmasters who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [780] = { name = "PSC Wildcat badge", description = "A bronze Private Second Class mercenary badge from \"Salaheem's Sentinels.\" A scintillant moat carp is emblazoned in its center." },
    [781] = { name = "boarding permit", description = "\"The holder of this permit has been authorized for travel to the Near East in order to take up post as a mercenary. The Empire of Aht Urhgan has a duty to inform our lands should the owner of this permit perish while abroad. The Commissioner of Mhaura\"" },
    [782] = { name = "runic portal use permit", description = "This permit authorizes the use of the runic portals in the Chamber of Passage." },
    [783] = { name = "PFC Wildcat badge", description = "A bronze Private First Class mercenary badge from \"Salaheem's Sentinels.\" Two scintillant moat carps are emblazoned in its center." },
    [784] = { name = "SP Wildcat badge", description = "A bronze Superior Private mercenary badge from \"Salaheem's Sentinels.\" Three scintillant moat carps are emblazoned in its center." },
    [785] = { name = "Raillefal's letter", description = "A letter you agreed to deliver for Raillefal the sage (or was it mercenary?). You can barely make out the words \"Chateau d'Oraguille\" on the envelope." },
    [786] = { name = "Ephramadian gold coin", description = "An exquisite gold coin you retrieved from the grave of a fallen knight. It bears the crest of a crowned dolphin." },
    [787] = { name = "Imperial Army I.D. tag", description = "A metal tag inscribed with an Imperial Army identification number. Needed to sign up for Assault missions." },
    [788] = { name = "Raillefal's note", description = "You can barely make out the words \"I return to my homeland.\"" },
    [789] = { name = "Dark Rider hoofprint", description = "A hardened chunk of clay imprinted by the hoof of a huge warhorse." },
    [790] = { name = "bag of gold pieces", description = "This bag is so heavy that it requires two hands to carry from one place to another. There must be a fortune inside..." },
    [791] = { name = "forgotten hexagun", description = "An old hexagun found in Talacca Cove. It is broken and unusable." },
    [792] = { name = "plasma oil", description = "A special type of oil required to animate automatons." },
    [793] = { name = "plasma rock", description = "A crystallized chunk of plasma oil." },
    [794] = { name = "LC Wildcat badge", description = "A silver Lance Corporal mercenary badge from \"Salaheem's Sentinels.\" A scintillant moat carp is emblazoned in its center." },
    [795] = { name = "C Wildcat badge", description = "A silver Corporal mercenary badge from \"Salaheem's Sentinels.\" Two scintillant moat carps are emblazoned in its center." },
    [796] = { name = "pot of Tsetseroon's stew", description = "This stew is giving off an indescribably foul scent. Could this possibly be edible...?" },
    [797] = { name = "Assault armband", description = "This armband designates you as the leader of an Assault mission. It bears the symbol of a curved sword." },
    [798] = { name = "antique automaton", description = "An automaton found on Arrapago Reef. It is no longer functioning." },
    [799] = { name = "red bell", description = "A Mamool Ja bell, painted red. It makes a clanging sound when swung." },
    [800] = { name = "blue bell", description = "A Mamool Ja bell, painted blue. It makes a tinkling sound when swung." },
    [801] = { name = "musical score - 1st page", description = "A scroll covered in Moblin letters and pictographs. You cannot read the Moblin words, but the pictographs have been drawn to be understandable to Trolls. The score seems to represent a rhythm of some sort." },
    [802] = { name = "musical score - 2nd page", description = "A scroll covered in Moblin letters and pictographs. You cannot read the Moblin words, but the pictographs have been drawn to be understandable to Trolls. The score seems to represent a rhythm of some sort." },
    [803] = { name = "Merrow homunculus", description = "A flask containing a tiny Merrow. She is small enough to fit on the palm of your hand, but appears to be an actual living being. You can hear the soft sound of her breathing as she sleeps..." },
    [804] = { name = "Lamia homunculus", description = "A flask containing a tiny Lamia. She is small enough to fit on the palm of your hand, but appears to be an actual living being. When you peer inside, she glares at you angrily..." },
    [805] = { name = "Munahda's package", description = "\"Furnishings. Handle with care.\" is written on the top of this box. It rattles when shaken." },
    [806] = { name = "white handkerchief", description = "This handkerchief was given to you by a chocobo trainer. It smells faintly of soap." },
    [807] = { name = "confidential Imperial order", description = "A top-secret order written in runes and graced with the mark of Zahak. This order will break the seal at the staging point, but the contents will vanish if it falls into the hands of the enemy." },
    [808] = { name = "secret Imperial order", description = "A top-secret order written in runes and graced with the mark of Zahak. This order will break the seal at the staging point, but the contents will vanish if it falls into the hands of the enemy." },
    [809] = { name = "handkerchief", description = "This handkerchief has the Vana'diel Chocobo Society logo imprinted on it." },
    [810] = { name = "dirty handkerchief", description = "A used handkerchief that smells faintly of sweat and chocobos." },
    [811] = { name = "Replay Debugger", description = "For GM use only!" },
    [812] = { name = "astral compass", description = "A compass that detects powerful astral emanations and displays the location on a map. An improved version of the crystal compass created by the Imperial Alchemists' Guild." },
    [813] = { name = "vial of spectral scent", description = "A scent made by Pyopyoroon that is meant to attract ghosts. The contents of the vial have been mixed with the digestive fluids of a rare malboro." },
    [814] = { name = "empty test tube #1", description = "An empty test tube you received from the alchemist Nafiwaa. Used to collect water from a Mythralline Spring." },
    [815] = { name = "empty test tube #2", description = "An empty test tube you received from the alchemist Nafiwaa. Used to collect water from a Mythralline Spring." },
    [816] = { name = "empty test tube #3", description = "An empty test tube you received from the alchemist Nafiwaa. Used to collect water from a Mythralline Spring." },
    [817] = { name = "empty test tube #4", description = "An empty test tube you received from the alchemist Nafiwaa. Used to collect water from a Mythralline Spring." },
    [818] = { name = "empty test tube #5", description = "An empty test tube you received from the alchemist Nafiwaa. Used to collect water from a Mythralline Spring." },
    [819] = { name = "test tube #1", description = "A test tube containing ocher-colored water from a Mythralline Spring in the Wajaom Woodlands." },
    [820] = { name = "test tube #2", description = "A test tube containing purple-colored water from a Mythralline Spring in the Wajaom Woodlands." },
    [821] = { name = "test tube #3", description = "A test tube containing bluish green water from a Mythralline Spring in the Wajaom Woodlands." },
    [822] = { name = "test tube #4", description = "A test tube containing yellowish green water from a Mythralline Spring in the Wajaom Woodlands." },
    [823] = { name = "test tube #5", description = "A test tube containing milky-white water from a Mythralline Spring in Bhaflau Thickets." },
    [824] = { name = "quartz transmitter", description = "A tiny device that transmits a signal to a corresponding crystal compass. No bigger than a coin, the transmitter emits a powerful astral pulse and runs on mythralline liquid. There are many Imperial citizens who unknowingly carry these transmitters." },
    [825] = { name = "S Wildcat badge", description = "A silver Sergeant mercenary badge from \"Salaheem's Sentinels.\" Three scintillant moat carps are emblazoned in its center." },
    [826] = { name = "SM Wildcat badge", description = "A mythril Sergeant Major mercenary badge from \"Salaheem's Sentinels.\" A scintillant salmon is emblazoned in its center." },
    [827] = { name = "CS Wildcat badge", description = "A mythril Chief Sergeant mercenary badge from \"Salaheem's Sentinels.\" Two scintillant salmons are emblazoned in its center." },
    [828] = { name = "chunk of glittering ore", description = "An unidentified chunk of glittering ore, extracted under duress at the Palborough Mines." },
    [829] = { name = "Brand of the Springserpent", description = "A blue magic brand you received from the Immortal stationed at the Ilrusi Atoll staging point." },
    [830] = { name = "Brand of the Galeserpent", description = "A blue magic brand you received from the Immortal stationed at the Dvucca Isle staging point." },
    [831] = { name = "Brand of the Flameserpent", description = "A blue magic brand you received from the Immortal stationed at the Halvung staging point." },
    [832] = { name = "Brand of the Skyserpent", description = "A blue magic brand you received from the Immortal stationed at the Mamool Ja staging point." },
    [833] = { name = "Brand of the Stoneserpent", description = "A blue magic brand you received from the Immortal stationed at the Azouph Isle staging point." },
    [834] = { name = "magus order slip", description = "This order slip must be presented to claim your completed piece of magus armor." },
    [835] = { name = "sealed Immortal envelope", description = "There is an address written on the envelope: Imperial Livery 2nd Floor, Balrahn Way It is sealed with the Mark of Zahak." },
    [837] = { name = "story of an impatient chocobo", description = "A story Hantileon tells the chocobos under his care." },
    [838] = { name = "story of a curious chocobo", description = "A story Brutus tells the chocobos under his care." },
    [839] = { name = "story of a worrisome chocobo", description = "A story Zopago tells the chocobos under his care." },
    [840] = { name = "story of a youthful chocobo", description = "A story Pulonono tells the chocobos under her care." },
    [841] = { name = "story of a happy chocobo", description = "A story Bashraf tells the chocobos under his care." },
    [842] = { name = "Mamool Ja mandate", description = "This short wooden slat is inscribed with incomprehensible Mamool Ja letters. The official-looking mark at the bottom appears to be granting the bearer some sort of authority or permission." },
    [843] = { name = "Valkeng's memory chip", description = "A small chip handed to you by Shamarhaan. Numerous tiny lambent cells glimmer on its surface." },
    [844] = { name = "toggle switch", description = "A bronze switch that looks to have been made by moblins. It makes a clanking sound when used." },
    [845] = { name = "Leleroon's letter (green)", description = "A letter from Leleroon addressed to a member of the Seagull Phratrie. It smells faintly like a Qiqirn. The address is difficult to make out, but it seems to say \"Big treee nation.\"" },
    [846] = { name = "Leleroon's letter (blue)", description = "A letter from Leleroon addressed to a member of the Seagull Phratrie. It smells faintly like a Qiqirn. The address is difficult to make out, but it seems to say \"Mountain men, strooong and rocks nation.\"" },
    [847] = { name = "Leleroon's letter (red)", description = "A letter from Leleroon addressed to a member of the Seagull Phratrie. It smells faintly like a Qiqirn. The address is difficult to make out, but it seems to say \"Fooorest and castle nation.\"" },
    [848] = { name = "life float", description = "A long, thin inflatable made of manta leather. New Seagull Phratrie members must wear this, but will be left behind if they fall overboard during a battle. Such knowledge tests their will to become corsairs." },
    [849] = { name = "wheel lock trigger", description = "A variety of firing mechanism for a type of gun once popular with the corsairs. This style is no longer widely used due to the fact that it uses complex Ephramadian gears that make mass production difficult." },
    [850] = { name = "story of a diligent chocobo", description = "A Far Eastern tale of a hard-working chocobo. One day, while digging on his farm, the chocobo finds buried treasure. However, the kingdom's wicked bugard sultan becomes envious of the chocobo and locks him up in the palace dungeons. But thanks to a rose that he plants by the window of the cell, his friends are able to find and save him. The end." },
    [851] = { name = "prairie chocograph", description = "The Vana'diel Chocobo Society hereby grants [insert name here] permission to participate in the Chocobo Hot and Cold Game in the following areas: 1. La Theine Plateau 2. Konschtat Highlands 3. Tahrongi Canyon Valid until death." },
    [852] = { name = "bush chocograph", description = "The Vana'diel Chocobo Society hereby grants [insert name here] permission to participate in the Chocobo Hot and Cold Game in the following areas: 1. Jugner Forest 2. Pashhow Marshlands 3. Meriphataud Mountains Valid until death." },
    [853] = { name = "letter from Bernahn", description = "This elegantly written note has been placed inside an envelope of surpassing quality. It is addressed to Galiwao." },
    [854] = { name = "Remnants Permit", description = "An odd circle of papyrus filled completely with complex cuneiform characters. This permit should allow you entrance into the restricted areas of the Ruins of Alzadaal..." },
    [855] = { name = "lilac ribbon", description = "A beautiful lilac ribbon made of velvet. There is a dark stain marring its perfection..." },
    [856] = { name = "coastal chocograph", description = "The Vana'diel Chocobo Society hereby grants [insert name here] permission to participate in the Chocobo Hot and Cold Game in the following areas: 1. Buburimu Peninsula Valid until death." },
    [857] = { name = "dune chocograph", description = "The Vana'diel Chocobo Society hereby grants [insert name here] permission to participate in the Chocobo Hot and Cold Game in the following areas: 1. Valkurm Dunes Valid until death." },
    [858] = { name = "jungle chocograph", description = "The Vana'diel Chocobo Society hereby grants [insert name here] permission to participate in the Chocobo Hot and Cold Game in the following areas: 1. Yuhtunga Jungle 2. Yhoator Jungle Valid until death." },
    [859] = { name = "desert chocograph", description = "The Vana'diel Chocobo Society hereby grants [insert name here] permission to participate in the Chocobo Hot and Cold Game in the following areas: 1. Eastern Altepa Desert 2. Western Altepa Desert Valid until death." },
    [860] = { name = "Periqia Assault area entry permit", description = "A provisional document that authorizes you to enter the Periqia Assault area." },
    [861] = { name = "warrior's armor claim slip", description = "\"Holding 1 set of warrior relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [862] = { name = "melee attire claim slip", description = "\"Holding 1 set of monk relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [863] = { name = "cleric's attire claim slip", description = "\"Holding 1 set of white mage relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [864] = { name = "sorcerer's attire claim slip", description = "\"Holding 1 set of black mage relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [865] = { name = "duelist's armor claim slip", description = "\"Holding 1 set of red mage relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [866] = { name = "assassin's attire claim slip", description = "\"Holding 1 set of thief relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [867] = { name = "valor armor claim slip", description = "\"Holding 1 set of paladin relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [868] = { name = "abyss armor claim slip", description = "\"Holding 1 set of dark knight relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [869] = { name = "monster armor claim slip", description = "\"Holding 1 set of beastmaster relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [870] = { name = "bard's attire claim slip", description = "\"Holding 1 set of bard relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [871] = { name = "scout's attire claim slip", description = "\"Holding 1 set of ranger relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [872] = { name = "saotome armor claim slip", description = "\"Holding 1 set of samurai relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [873] = { name = "koga garb claim slip", description = "\"Holding 1 set of ninja relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [874] = { name = "wyrm armor claim slip", description = "\"Holding 1 set of dragoon relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [875] = { name = "summoner's attire claim slip", description = "\"Holding 1 set of summoner relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [876] = { name = "scourshroom", description = "A rare mushroom that only grows within the Aydeewa Subterrane. Boiled together with olive oil, it is the main ingredient in the potent cleaner known as \"rustkiller.\"" },
    [877] = { name = "percipient eye", description = "A translucent blue stone hanging from a leather cord. Enables the bearer to pierce the spell of concealment upon the Ephramadian treasure in Talacca Cove." },
    [878] = { name = "Nyzul Isle Assault orders", description = "A document that authorizes you to take part in a Nyzul Isle Assault mission." },
    [879] = { name = "runic disc", description = "An enigmatic disc you obtained on Nyzul Isle. Required to operate the Rune of Transfer." },
    [880] = { name = "runic key", description = "An enigmatic key you obtained on Floor 100 of Nyzul Isle." },
    [881] = { name = "Gysahl Medal", description = "This bronze medal of honor has been awarded to you by the CRA for your accomplishments in chocobo racing." },
    [882] = { name = "Rossweisse's feather", description = "A transparent feather from the wing of the valkyrie, Rossweisse." },
    [883] = { name = "Grimgerde's feather", description = "A transparent feather from the wing of the valkyrie, Grimgerde." },
    [884] = { name = "Siegrune's feather", description = "A transparent feather from the wing of the valkyrie, Siegrune." },
    [885] = { name = "Helmwige's feather", description = "A transparent feather from the wing of the valkyrie, Helmwige." },
    [886] = { name = "Schwertleite's feather", description = "A transparent feather from the wing of the valkyrie, Schwertleite." },
    [887] = { name = "Waltraute's feather", description = "A transparent feather from the wing of the valkyrie, Waltraute." },
    [888] = { name = "Ortlinde's feather", description = "A transparent feather from the wing of the valkyrie, Ortlinde." },
    [889] = { name = "Gerhilde's feather", description = "A transparent feather from the wing of the valkyrie, Gerhilde." },
    [890] = { name = "Brunhilde's feather", description = "A transparent feather from the wing of the valkyrie, Brunhilde." },
    [891] = { name = "Mark of the Einherjar", description = "The following rune inscription has been carved on this crimson stone: Sauuage Einherjar, thou hast bien graunted audiens at ye Yhates of ye Underverden." },
    [892] = { name = "photopticator", description = "This improved recording device can capture up to five seconds of moving images." },
    [893] = { name = "luminian dagger", description = "A short mythril blade given to you by Nashmeira. The pommel of the dagger is wrought in luminian and graced by the Mark of Zahak." },
    [894] = { name = "SL Wildcat badge", description = "A gold Second Lieutenant mercenary badge from \"Salaheem's Sentinels.\" A scintillant tuna is emblazoned in its center." },
    [895] = { name = "Biyaada's letter", description = "An introduction letter penned by Biyaada, the senior adjutant to the Skyserpent General. It should prove helpful when you meet the aides to the other Serpent Generals." },
    [896] = { name = "Officer Academy manual", description = "\"Be the best that you can be! Pay your tuition fee to Abquhbah of Salaheem's Sentinels and prepare for the excitement of Officer Academy!\"" },
    [897] = { name = "Allied Council Summons", description = "You have been summoned to the Allied Military Council being held in the Grand Duke Palace in Jeuno. The summons is signed by Trion, Volker, Shantotto, and Wolfgang." },
    [898] = { name = "Nyzul Isle route", description = "A map hastily drawn by Travialce. It shows the route Luzaf's captors used to take him through Nyzul Isle." },
    [899] = { name = "mythril mirror", description = "A circular mirror made of gleaming mythril. A finely-engraved pattern on its surface refracts the light in unusual angles, making reflections hazy and unclear. A relief of the Serpentking Zahak is carved on the back of the mirror." },
    [900] = { name = "FL Wildcat badge", description = "A gold First Lieutenant mercenary badge from \"Salaheem's Sentinels.\" Two scintillant tuna are emblazoned in its center." },
    [908] = { name = "Chocobo Circuit grandstand pass", description = "This pass allows free admission to the Chocobo Circuit grandstand. It does not appear to have an expriration date." },
    [909] = { name = "Captain Wildcat badge", description = "A gold Captain mercenary badge from \"Salaheem's Sentinels.\" Three scintillant tuna are emblazoned in its center." },
    [910] = { name = "pure white feather", description = "A feather that suddenly appeared in your grasp. It glows with a soft platinum light." },
    [911] = { name = "stardust pebble", description = "A brightly glowing stone found in Lake Mechieume during the time of the Great War. The pebbles were so avidly sought after that not a single one remains in the lake today." },
    [912] = { name = "left map piece", description = "One fragment of a map of Grauberg. This piece only shows about a third of the entire area." },
    [913] = { name = "middle map piece", description = "One fragment of a map of Grauberg. This piece only shows about a third of the entire area." },
    [914] = { name = "right map piece", description = "One fragment of a map of Grauberg. This piece only shows about a third of the entire area." },
    [915] = { name = "sequined Ballista chevron", description = "Presented only to those dancers who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [916] = { name = "velvet Ballista chevron", description = "Presented only to those scholars who have displayed excellence on the Ballista battlefield. ;Must be returned to a Herald after a set period indicated in the official Ballista rulebook." },
    [917] = { name = "battle rations", description = "A heavy box marked... Republican Legion Fourth Division Seventh Cohors Eduard Watchtower, N. Gustaberg" },
    [918] = { name = "clump of animal hair", description = "Material used in the construction of a string instrument. You're not sure what animal the hair comes from..." },
    [919] = { name = "xhifhut", description = "A Goblin-made instrument consisting of four main parts: strings, body, bow, and head. The sound created by the xhifhut closely resembles the fricative noises made within the Antica's necks, and is thus often used for inter-species communication." },
    [920] = { name = "warning letter", description = "A letter pressed into your hand by a strange Galka while you stood outside Engelhart's store. It simply reads, \"Stay out of this.\"" },
    [921] = { name = "red recommendation letter", description = "A letter recommending your admission to the Knights of the Iron Ram." },
    [922] = { name = "blue recommendation letter", description = "A letter recommending your admission to the Fourth Division of the Republican Legion." },
    [923] = { name = "green recommendation letter", description = "A letter recommending your admission to the Mithra Mercenary Reserve's Cobra Unit." },
    [924] = { name = "Bronze Ribbon of Service .", description = "A tiny bronze medal attached to a red and white ribbon. Awarded for service in the Allied Campaign." },
    [925] = { name = "Brass Ribbon of Service ..", description = "A tiny brass medal attached to a red and white ribbon. Awarded for service on the campaign battlefield." },
    [926] = { name = "Allied Ribbon of Bravery ...", description = "A tiny silver medal attached to a red and white ribbon. Awarded for outstanding service on the campaign battlefield." },
    [927] = { name = "Allied Ribbon of Glory ....", description = "A tiny mythril medal attached to a red and white ribbon. Awarded for exemplary performance in campaign operations. The most prestigious ribbon obtainable." },
    [928] = { name = "Bronze Star .", description = "A bronze star engraved with clashing swords. Awarded for service on the campaign front." },
    [929] = { name = "Sterling Star ..", description = "A silver star engraved with clashing swords. Awarded for bravery on the campaign front." },
    [930] = { name = "Mythril Star ...", description = "A mythril star engraved with clashing swords. Awarded for outstanding service on the campaign front." },
    [931] = { name = "Golden Star ....", description = "A gold star engraved with clashing swords. Awarded for exemplary service on the campaign front. The most prestigious star obtainable." },
    [932] = { name = "Copper Emblem of Service .", description = "A solid copper emblem designed to resemble a crystal. Awarded for achievements within the Allied Campaign." },
    [933] = { name = "Iron Emblem of Service ..", description = "A solid iron emblem designed to resemble a crystal. Awarded for repeated achievements within the Allied Campaign." },
    [934] = { name = "Steelknight Emblem ...", description = "A solid steel emblem designed to resemble a crystal. Awarded for outstanding achievements within the Allied Campaign." },
    [935] = { name = "Holyknight Emblem ....", description = "A solid darksteel emblem designed to resemble a crystal. Awarded for exemplary achievements within the Allied Campaign." },
    [936] = { name = "Brass Wings of Service .", description = "A pair of wings forged from brass. Awarded for continued service to the Allied Campaign." },
    [937] = { name = "Mythril Wings of Service ..", description = "A pair of wings forged from pure mythril. Awarded for extended service to the Allied Campaign." },
    [938] = { name = "Wings of Integrity ...", description = "A pair of wings forged from pure gold. Awarded for loyal service to the Allied Campaign." },
    [939] = { name = "Wings of Honor ....", description = "A pair of wings forged from pure platinum. Awarded for undying loyalty to the Allied Campaign. The most prestigious wings obtainable." },
    [940] = { name = "Starlight Medal .", description = "A ruby star set in the center of a gold medal. Awarded to champions of the Allied Campaign." },
    [941] = { name = "Moonlight Medal ..", description = "A sapphire moon set in the center of a platinum medal. Awarded to heroes of the Allied Campaign." },
    [942] = { name = "Dawnlight Medal ...", description = "A remarkably scintillant medal of pure luminium. Awarded to legends of the Allied Campaign." },
    [943] = { name = "Medal of Altana ....", description = "An adaman medal engraved with the outline of the Dawn Goddess. Awarded to saviors of the Allied Campaign. The most prestigious decoration obtainable." },
    [944] = { name = "sliced pole", description = "A pole you found at an Orc lookout platform in Jugner Forest. The pole has been sliced length-wise, creating a half-moon shape on its ends." },
    [945] = { name = "supply order", description = "A list of supplies requested by the army's quartermaster." },
    [946] = { name = "grimoire", description = "A copy of an ancient magical tome augmented with various military strategies. Its astral properties allow the possessor to command the grimoire to appear and disappear at will." },
    [947] = { name = "Zonpa-Zippa's All-Purpose Putty", description = "Guaranteed to perfectly patch up any problem, or your money back." },
    [948] = { name = "Scoop-Dedicated Linkpearl", description = "A linkpearl created by Naiko-Paneiko solely for transmitting only the hottest in news, leads, and scoops." },
    [949] = { name = "firepower case", description = "A case containing munitions for a variety of firearms and artillery. A sign reading \"Keep Away From Fire!\" is affixed to the front." },
    [950] = { name = "charred propeller", description = "Linen cloth loosely hangs from the burnt remnants of a wooden frame." },
    [951] = { name = "piece of shattered lumber", description = "Several crystal shards lie deeply imbedded in this splinter of wood." },
    [952] = { name = "oxidized plate", description = "A brass plate bearing the letters E, O, and S." },
    [953] = { name = "piece of kionite", description = "A lustrous blue stone taken from Vunkerl Inlet." },
    [954] = { name = "Ranpi-Monpi Specialty", description = "A specialty dish prepared for you by Ranpi-Monpi with a somewhat unseemly appearance. It has a very unique aroma..." },
    [955] = { name = "culinary knife", description = "A cooking knife given to you by Ranpi-Monpi. It appears to be well used, with many nicks and blemishes visible on the blade." },
    [956] = { name = "fireblossom", description = "A beautiful, perennial flower that grows in Grauberg." },
    [957] = { name = "\"The Healing Herb\"", description = "An academic journal on herbalism, published in the Far East. It focuses primarily on the medicinal properties of herbs." },
    [958] = { name = "small starfruit", description = "A small starfruit secretly planted by the young Ajido-Marujido." },
    [959] = { name = "inky black Yagudo feather", description = "A Yagudo feather dropped by the young Ajido-Marujido. It is much larger than a normal Yagudo feather, and radiates a distinct malevolence." },
    [960] = { name = "campaign supplies", description = "An important package of supplies to be delivered to your nation's stronghold." },
    [961] = { name = "mine shaft key", description = "A key used by the Quadav in the mines of Pashhow." },
    [962] = { name = "\"The Essence of Dance\"", description = "A textbook that provides practical information on dancing at the advanced level. Written by Annika Brilioth." },
    [963] = { name = "Jugner gate crystal", description = "A forgotten gate crystal found in the Jugner Forest of the past. Needed to teleport to Jugner Forest [S]." },
    [964] = { name = "Pashhow gate crystal", description = "A forgotten gate crystal found in the Pashhow Marshlands of the past. Needed to teleport to Pashhow Marshlands [S]." },
    [965] = { name = "Meriphataud gate crystal", description = "A forgotten gate crystal found in the Meriphataud Mountains of the past. Needed to teleport to Meriphataud Mountains [S]." },
    [966] = { name = "Vunkerl herb", description = "Supposedly the rare herb found only in Vunkerl Inlet." },
    [967] = { name = "Vunkerl herb memo", description = "00:00^07:59 San d'Oria 08:00^15:59 Bastok 16:00^23:59 Windurst" },
    [968] = { name = "evil warding seal", description = "A seal that wards off evil through the white magic of the San d'Orian Cathedral." },
    [969] = { name = "ornate package", description = "A neatly wrapped package adorned with the crest of the San d'Orian Cathedral." },
    [970] = { name = "sheaf of handmade incense", description = "Special incense given to you by Pecca-Pocca. Used as an offering to honor the memory of the departed." },
    [971] = { name = "leather-bound book", description = "A book Yoran-Oran borrowed from the Library of Magic. The title, \"Forlorn Beauty,\" suggests it to be a romance novel." },
    [972] = { name = "lynx pelt", description = "An old lynx pelt you found inside Castle Oztroja. It looks to have been dropped by someone." },
    [973] = { name = "Wyatt's proposal", description = "A proposal for a collaborative performance between troupes Brilioth and Valeriano." },
    [974] = { name = "fort key", description = "A key used to open doors in Fort Karugo-Narugo" },
    [975] = { name = "Ulbrecht's sealed letter", description = "A letter entrusted to you by Ulbrecht and addressed to Prof. Schultz. Sealed with a heavy magic, it appears impervious to conventional letter-opening methods." },
    [976] = { name = "Schultz's sealed letter", description = "A letter entrusted to you by Prof. Schultz to be delivered to Ulbrecht. Sealed with a heavy magic, it seems to be impervious to conventional letter-opening techniques." },
    [977] = { name = "unaddressed sealed letter", description = "A letter consisting of a single sheet bearing cryptic writing. It reads: Only when nourished and bathed in deep crimson depths of the most magicked bloods, shall the true tome of stratagems be borne. And that which riseth forth..." },
    [978] = { name = "porting magic transcript", description = "A transcript of a stratagem taken by Erlene that involves instantaneous travel over great distances. A similar stratagem seems to be in existence somewhere in Grauberg..." },
    [979] = { name = "sample of Grauberg chert", description = "A viable sample of the hornlike chert which dominates the Grauberg landscape. Useful in some forms of research." },
    [980] = { name = "Drogarogan bonemeal", description = "A fine powder procured from the enormous structure known as Drogaroga's Spine. Useful in some forms of research." },
    [981] = { name = "Slug mucus", description = "The viscous mucus left in the wake of a moving Slug. Sticky, wet, and disgusting. Useful in some forms of research." },
    [982] = { name = "Djinn ember", description = "The last vestigial flames of a deceased Djinn. They burn with an air of maliciousness. Useful in some forms of research." },
    [983] = { name = "Rafflesia dreamspit", description = "The slumber-inducing liquid vomited forth by Rafflesia plants upon catching live prey. Useful in some forms of research." },
    [984] = { name = "Peiste dung", description = "The fecal discharge of a wild, healthy Peiste, the scent of which defies description. Useful in some forms of research." },
    [985] = { name = "Ulbrecht's mortarboard", description = "The characteristic mortarboard of a scholar. Left behind by Ulbrecht in the haste of his escape." },
    [986] = { name = "Beastman Confederate crate", description = "A wooden cargo crate abandoned by the Beastman Confederate, whose seal is branded on the outer surface. It is extremely heavy." },
    [987] = { name = "military scrip", description = "A military bill issued by the Royal Knights during the Crystal War. Certified to be convertible into any currency." },
    [988] = { name = "silvermine key", description = "A key used to gain access to the abandoned Silvermines." },
    [989] = { name = "red prize balloon", description = "A radiant red balloon you received as a prize for clearing hard mode at Spot the Difference." },
    [990] = { name = "blue prize balloon", description = "A brilliant blue balloon you received as a prize for clearing hard mode at the Shooting Gallery." },
    [991] = { name = "green prize ballon", description = "A gleaming green balloon you received as a prize for clearing hard mode at the Chocobo Chick Catchery." },
    [992] = { name = "Travonce's escort award", description = "A slip given to you by Tavonce acknowledging your successful completion of an escort behest." },
    [993] = { name = "Ken's escort award", description = "A slip given to you by Ken acknowledging your successful completion of an escort behest." },
    [994] = { name = "Emptiness investigation note", description = "A memo reminding you to assist your fellow in an investigation of the Emptiness." },
    [995] = { name = "tigris stone", description = "This stone disk taken from an Orcish officer bears a crudely engraved tiger crest. It can be used as an access pass to Darkheir Grradhod's command center in La Vaule." },
    [996] = { name = "diamond seal", description = "This diamond taken from a Quadav officer has been masterfully cut into the shape of the Quadav royal seal. It is said to be the key to the Qulun Dome, Za'Dha Adamantking's seat of power." },
    [997] = { name = "Xicu's rosary", description = "This ceremonial rosary taken from a Yagudo officer is made with polished coral beads. Using it as an offering will open a secret passageway to the Altar Room, the sanctuary of Soo Luma the Ascended." },
    [998] = { name = "maroon seal", description = "A maroon Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [999] = { name = "apple green seal", description = "An apple green Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1000] = { name = "charcoal grey seal", description = "A charcoal grey Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1001] = { name = "deep purple seal", description = "A deep purple Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1002] = { name = "chestnut-colored seal", description = "A chestnut-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1003] = { name = "lilac-colored seal", description = "A lilac-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1004] = { name = "cerise seal", description = "A cerise Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1005] = { name = "salmon-colored seal", description = "A salmon-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1006] = { name = "purplish grey seal", description = "A purplish grey Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1007] = { name = "gold-colored seal", description = "A gold-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1008] = { name = "copper-colored seal", description = "A copper-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1009] = { name = "bright blue seal", description = "A bright blue Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1010] = { name = "pine green seal", description = "A pine green Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1011] = { name = "amber-colored seal", description = "An amber-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1012] = { name = "fallow-colored seal", description = "A fallow-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1013] = { name = "taupe-colored seal", description = "A taupe-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1014] = { name = "sienna-colored seal", description = "A sienna-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1015] = { name = "lavender-colored seal", description = "A lavender-colored Far Eastern tally seal given to you by Sanraku the traveling painter." },
    [1016] = { name = "Sicklemoon salt", description = "A solar-evaporated salt harvested from coastlines along the Sicklemoon Straits. If it comes in contact with the engraved tablet at the Wajaom Woodlands..." },
    [1017] = { name = "Silver Sea salt", description = "A solar-evaporated salt harvested from coastlines along the Silver Sea. If it comes in contact with the engraved tablet at Mount Zhayolm..." },
    [1018] = { name = "Cyan Deep salt", description = "A solar-evaporated salt harvested from coastlines along the Cyan Deep. If it comes in contact with the engraved tablet at Caedarva Mire..." },
    [1019] = { name = "Orcish warmachine body", description = "The wooden body of an Orcish warmachine stripped from a wreck found in the Jugner Forest. It is in surprisingly serviceable condition." },
    [1020] = { name = "Paparoon's sealed invitation", description = "A formal letter composed in a regal hand and bearing the imperial seal of the serpent. It bears a signature in the written in the exotic Qiqirn language." },
    [1021] = { name = "Data Analyzer and Logger EX", description = "A peculiar plush doll Rakuru-Rakoru from the Orastery has lent to you. Despite its endearing nickname, \"Dale,\" it is in fact a high-tech device that collects and analyzes monster data from battles." },
    [1022] = { name = "Mayakov show ticket", description = "A ticket to admit one person to Troupe Mayakov's dance performance. The show is entitled \"Troupe Mayakov, Taking It to the Stars.\" It appears to be well worn with age and abuse, and could easily be mistaken for a piece of trash." },
    [1023] = { name = "Serpentking Zahak relief", description = "A detailed work in bas relief of the Serpentking Zahak, in all his two-headed glory. The piece strikes you as considerably old." },
    [1024] = { name = "Sakura racing badge", description = "A luminescent tin badge, embossed with an effigy in profile of none other that the adorable icon of chocobo racing herself, everyone's beloved Sakura." },
    [1025] = { name = "Serpentking Zahak relief shard", description = "A mere fragment of what was no doubt an inspiring likeness of Serpentking Zahak. Sadly, only one head remains. The piece strikes you as considerably old." },
    [1026] = { name = "\"Imperial Lineage\" chapter I", description = "A chapter from an unabridged account of the genealogy of all Orcish sovereigns to date, as recorded by Goblin scribes. Those who recite the work in its entirety are said to be granted an audience with His Imperial Majesty, the Emperor himself." },
    [1027] = { name = "\"Imperial Lineage\" chapter II", description = "A chapter from an unabridged account of the genealogy of all Orcish sovereigns to date, as recorded by Goblin scribes. Those who recite the work in its entirety are said to be granted an audience with His Imperial Majesty, the Emperor himself." },
    [1028] = { name = "\"Imperial Lineage\" chapter III", description = "A chapter from an unabridged account of the genealogy of all Orcish sovereigns to date, as recorded by Goblin scribes. Those who recite the work in its entirety are said to be granted an audience with His Imperial Majesty, the Emperor himself." },
    [1029] = { name = "\"Imperial Lineage\" chapter IV", description = "A chapter from an unabridged account of the genealogy of all Orcish sovereigns to date, as recorded by Goblin scribes. Those who recite the work in its entirety are said to be granted an audience with His Imperial Majesty, the Emperor himself." },
    [1030] = { name = "\"Imperial Lineage\" chapter V", description = "A chapter from an unabridged account of the genealogy of all Orcish sovereigns to date, as recorded by Goblin scribes. Those who recite the work in its entirety are said to be granted an audience with His Imperial Majesty, the Emperor himself." },
    [1031] = { name = "\"Imperial Lineage\" chapter VI", description = "A chapter from an unabridged account of the genealogy of all Orcish sovereigns to date, as recorded by Goblin scribes. Those who recite the work in its entirety are said to be granted an audience with His Imperial Majesty, the Emperor himself." },
    [1032] = { name = "\"Imperial Lineage\" chapter VII", description = "A chapter from an unabridged account of the genealogy of all Orcish sovereigns to date, as recorded by Goblin scribes. Those who recite the work in its entirety are said to be granted an audience with His Imperial Majesty, the Emperor himself." },
    [1033] = { name = "\"Imperial Lineage\" chapter VIII", description = "A chapter from an unabridged account of the genealogy of all Orcish sovereigns to date, as recorded by Goblin scribes. Those who recite the work in its entirety are said to be granted an audience with His Imperial Majesty, the Emperor himself." },
    [1034] = { name = "The Words of Do'Nhu I", description = "The first of eight tablets inscribed with the words of the Quadav god Do'Nhu. Legend has it that Do'Nhu's counterpart deity, Gu'Dha, will appear before he who cantillates the inscriptions on all tablets." },
    [1035] = { name = "The Words of Do'Nhu II", description = "The second of eight tablets inscribed with the words of the Quadav god Do'Nhu. Legend has it that Do'Nhu's counterpart deity, Gu'Dha, will appear before he who cantillates the inscriptions on all tablets." },
    [1036] = { name = "The Words of Do'Nhu III", description = "The third of eight tablets inscribed with the words of the Quadav god Do'Nhu. Legend has it that Do'Nhu's counterpart deity, Gu'Dha, will appear before he who cantillates the inscriptions on all tablets." },
    [1037] = { name = "The Words of Do'Nhu IV", description = "The fourth of eight tablets inscribed with the words of the Quadav god Do'Nhu. Legend has it that Do'Nhu's counterpart deity, Gu'Dha, will appear before he who cantillates the inscriptions on all tablets." },
    [1038] = { name = "The Words of Do'Nhu V", description = "The fifth of eight tablets inscribed with the words of the Quadav god Do'Nhu. Legend has it that Do'Nhu's counterpart deity, Gu'Dha, will appear before he who cantillates the inscriptions on all tablets." },
    [1039] = { name = "The Words of Do'Nhu VI", description = "The sixth of eight tablets inscribed with the words of the Quadav god Do'Nhu. Legend has it that Do'Nhu's counterpart deity, Gu'Dha, will appear before he who cantillates the inscriptions on all tablets." },
    [1040] = { name = "The Words of Do'Nhu VII", description = "The seventh of eight tablets inscribed with the words of the Quadav god Do'Nhu. Legend has it that Do'Nhu's counterpart deity, Gu'Dha, will appear before he who cantillates the inscriptions on all tablets." },
    [1041] = { name = "The Words of Do'Nhu VIII", description = "The last of eight tablets inscribed with the words of the Quadav god Do'Nhu. Legend has it that Do'Nhu's counterpart deity, Gu'Dha, will appear before he who cantillates the inscriptions on all tablets." },
    [1042] = { name = "Habalo's Eclogue - verse I", description = "The first verse of the eclogue penned by the first Yagudo Manifest, Ree Habalo. It is said that he who recites all eight verses will be visited by the Yagudo of legend." },
    [1043] = { name = "Habalo's Eclogue - verse II", description = "The second verse of the eclogue penned by the first Yagudo Manifest, Ree Habalo. It is said that he who recites all eight verses will be visited by the Yagudo of legend." },
    [1044] = { name = "Habalo's Eclogue - verse III", description = "The third verse of the eclogue penned by the first Yagudo Manifest, Ree Habalo. It is said that he who recites all eight verses will be visited by the Yagudo of legend." },
    [1045] = { name = "Habalo's Eclogue - verse IV", description = "The fourth verse of the eclogue penned by the first Yagudo Manifest, Ree Habalo. It is said that he who recites all eight verses will be visited by the Yagudo of legend." },
    [1046] = { name = "Habalo's Eclogue - verse V", description = "The fifth verse of the eclogue penned by the first Yagudo Manifest, Ree Habalo. It is said that he who recites all eight verses will be visited by the Yagudo of legend." },
    [1047] = { name = "Habalo's Eclogue - verse VI", description = "The sixth verse of the eclogue penned by the first Yagudo Manifest, Ree Habalo. It is said that he who recites all eight verses will be visited by the Yagudo of legend." },
    [1048] = { name = "Habalo's Eclogue - verse VII", description = "The seventh verse of the eclogue penned by the first Yagudo Manifest, Ree Habalo. It is said that he who recites all eight verses will be visited by the Yagudo of legend." },
    [1049] = { name = "Habalo's Eclogue - verse VIII", description = "The eighth and final verse of the eclogue penned by the first Yagudo Manifest, Ree Habalo. It is said that he who recites all eight verses will be visited by the Yagudo of legend." },
    [1050] = { name = "signal firecracker", description = "A Bastokan signal firecracker designed to produce a loud, piercing bang claimed to be audible up to a distance of ten malms. Used as a means of communication in tactical missions where visual contact between operatives is limited." },
    [1051] = { name = "number eight shelter key", description = "A mythril key etched only with the number \"8.\"" },
    [1052] = { name = "torn patches of leather", description = "The grisly remains of Hampu-Kampu's beautifully handcrafted handbag after having met its cruel end at the claws of young Tek Lengyon." },
    [1053] = { name = "repaired handbag", description = "Hampu-Kampu's handcrafted handbag has been masterfully restored to its original mint condition by Kipopo at the Tanners' Guild in San d'Oria." },
    [1054] = { name = "mirage attire claim slip", description = "\"Holding 1 set of blue mage relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [1055] = { name = "commodore attire claim slip", description = "\"Holding 1 set of corsair relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [1056] = { name = "pantin attire claim slip", description = "\"Holding 1 set of puppetmaster relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [1057] = { name = "etoile attire claim slip", description = "\"Holding 1 set of dancer relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [1058] = { name = "argute attire claim slip", description = "\"Holding 1 set of scholar relic armor for the adventurer whose name is inscribed on the back of this slip.\"" },
    [1059] = { name = "argent attire claim slip", description = "\"Holding 1 argent set for the adventurer whose name is inscribed on the back of this slip.\"" },
    [1060] = { name = "Conquest promotion voucher", description = "These tickets are distributed as a means to encourage adventurers to participate in the ever-ongoing conquest. It is equivalent to a predetermined number of conquest points, and may be exchanged for goods in the same manner." },
    [1061] = { name = "Cernunnos resin", description = "A lump of solidified resin harvested from a treant species thought to be long extinct. Known for its medicinal properties." },
    [1062] = { name = "Count Borel's letter", description = "A letter impressed with the seal of Halver M Borel." },
    [1063] = { name = "underpass hatch key", description = "A key to unlock the hatch located atop a defensive wall out in Batallia Downs. Needed to gain access to Jeuno's underground." },
    [1064] = { name = "bottle of treant tonic", description = "A medicine prepared by Amaura, using Cernunnos resin as its active ingredient. While potent in its own right, its healing power is limited to the alleviation of symptoms." },
    [1065] = { name = "timber survey checklist", description = "A memo hastily scrawled by Ramua of the San d'Orian Carpenters' Guild, asking you to procure the following samples from Jugner Forest: - arrowwood log, ash log, yew log, willow log, walnut log" },
    [1066] = { name = "snow-themed gift token", description = "A Starlight Celebration gift token adorned with a frolicking snowflake design. Take it to your friendly neighborhood festival moogle to have it exchanged for a lovely present." },
    [1067] = { name = "star-themed gift token", description = "A Starlight Celebration gift token adorned with a twinkling star design. Take it to your friendly neighborhood festival moogle to have it exchanged for a lovely present." },
    [1068] = { name = "bell-themed gift token", description = "A Starlight Celebration gift token adorned with a jingling bell design. Take it to your friendly neighborhood festival moogle to have it exchanged for a lovely present." },
    [1069] = { name = "flare grenade", description = "A tactical hand grenade that emits a blinding flash of light." },
    [1070] = { name = "Ronfaure maple syrup", description = "The mellow sweetness of this syrup, harvested from maple trees in Ronfaure, has endeared itself to the citizens of San d'Oria." },
    [1071] = { name = "long-life biscuits", description = "These hard-baked biscuits serve as emergency rations during days of disaster and dearth in San d'Oria." },
    [1072] = { name = "flask of Kingdom water", description = "A flask of freshly drawn groundwater, chilled by its passage through the Kingdom's extensive aquifer network." },
    [1073] = { name = "biscuit a la Rholont", description = "New life has been breathed into ordinary long-life biscuits by way of aromatic slices of Chalaimbille and a generous drizzling of maple syrup." },
    [1074] = { name = "letter to Count Aurchiat", description = "Captain Rongelouts of the Iron Rams has instructed you to deliver this letter to his Cardinal Stag counterpart, Count Aurchiat." },
    [1075] = { name = "length of Jugner ivy", description = "The robust resilience of this variety of creeper makes it an ideal choice for use in rope making." },
    [1076] = { name = "darkfire cinder", description = "Curious jet-black cinders that smolder with perpetual heat. A vital resource of the Allied Forces, used in the creation of enchanted ammunition." },
    [1077] = { name = "floelight stone", description = "These alabaster stones are chill to the touch and emanate a faint, hazy light. A vital resource of the Allied Forces, used in the creation of enchanted arrowheads." },
    [1078] = { name = "liquid quicksilver", description = "An unusual substance resembling molten metal. A requisite ingredient in the casting of enchanted ammunition." },
    [1079] = { name = "gelid sulfur", description = "Though appearing at first glance to be ordinary sulfur, it is cool to the touch. A requisite ingredient in the casting of enchanted ammunition." },
    [1080] = { name = "beastbane bullets", description = "The freshly cast bullets crackle with a frozen flame..." },
    [1081] = { name = "Gleipnir", description = "The mystic fetters fashioned by Rimilala to subdue the Great Beast Fenrir. Lighter and softer than silk, yet stronger than the hardest chains of darksteel." },
    [1082] = { name = "scintillant strand", description = "A timeworn tatter of a peculiar silken fiber. It shimmers with a curious ethereal light..." },
    [1083] = { name = "refulgent strand", description = "A timeworn tatter of a peculiar silken fiber. It shimmers with a curious ethereal light..." },
    [1084] = { name = "irradiant strand", description = "A timeworn tatter of a peculiar silken fiber. It shimmers with a curious ethereal light..." },
    [1085] = { name = "bowl of bland Goblin salad", description = "Batagreens have been haphazardly sliced into irregularly sized chunks and drizzled with a runny, watered-down bittern dressing to form this distinctly unappetizing salad." },
    [1086] = { name = "jug of greasy Goblin juice", description = "Freshly squeezed rolanberries and fish oil... Two great tastes that were never meant to go together." },
    [1087] = { name = "chunk of smoked Goblin grub", description = "An oversized hunk of meat that has been charred, seared, and smoked well beyond the point of recognition and palatability. You detect a hint of bonemeal-based Goblin seasoning." },
    [1088] = { name = "Seedspall Roseum", description = "A shard of the Seed Crystal retrieved from a veggie-loving Goblin. It tingles to the touch and radiates an otherworldly red-tinged light." },
    [1089] = { name = "Seedspall Caerulum", description = "A shard of the Seed Crystal retrieved from a health-conscious Goblin. It tingles to the touch and radiates an otherworldly blue-tinged light." },
    [1090] = { name = "Seedspall Viridis", description = "A shard of the Seed Crystal retrieved from a particularly carnivorous Goblin. It tingles to the touch and radiates an otherworldly green-tinged light." },
    [1091] = { name = "Mark of Seed", description = "A glowing outline in the shape of a seed shines from the back of your hand. You feel as if it is beckoning you to the Qu'Bia Arena." },
    [1092] = { name = "Amicitia Stone", description = "A fragment of the Seed Crystal found on the first floor of Delkfutt's Tower. It resembles a garnet in hue and luster." },
    [1093] = { name = "Veritas Stone", description = "A fragment of the Seed Crystal found on the second floor of Delkfutt's Tower. It resembles an amethyst in hue and luster." },
    [1094] = { name = "Sapientia Stone", description = "A fragment of the Seed Crystal found on the third floor of Delkfutt's Tower. It resembles an aquamarine in hue and luster." },
    [1095] = { name = "Sanctitas Stone", description = "A fragment of the Seed Crystal found on the fourth floor of Delkfutt's Tower. It resembles a diamond in hue and luster." },
    [1096] = { name = "Felicitas Stone", description = "A fragment of the Seed Crystal found on the fifth floor of Delkfutt's Tower. It resembles an emerald in hue and luster." },
    [1097] = { name = "Divitia Stone", description = "A fragment of the Seed Crystal found on the sixth floor of Delkfutt's Tower. It resembles a moonstone in hue and luster." },
    [1098] = { name = "Studium Stone", description = "A fragment of the Seed Crystal found on the seventh floor of Delkfutt's Tower. It resembles a ruby in hue and luster." },
    [1099] = { name = "Amoris Stone", description = "A fragment of the Seed Crystal found on the eighth floor of Delkfutt's Tower. It resembles a sardonyx in hue and luster." },
    [1100] = { name = "Caritas Stone", description = "A fragment of the Seed Crystal found on the ninth floor of Delkfutt's Tower. It resembles a sapphire in hue and luster." },
    [1101] = { name = "Constantia Stone", description = "A fragment of the Seed Crystal found on the tenth floor of Delkfutt's Tower. It resembles an opal in hue and luster." },
    [1102] = { name = "Spei Stone", description = "A fragment of the Seed Crystal found on the eleventh floor of Delkfutt's Tower. It resembles a topaz in hue and luster." },
    [1103] = { name = "Salus Stone", description = "A fragment of the Seed Crystal found on the twelfth floor of Delkfutt's Tower. It resembles a lapis lazuli in hue and luster." },
    [1104] = { name = "Omnis Stone", description = "The twelve stones resonate with each other, their lights coalescing to form an ethereal rainbow. Closely examining the lights, you can make out a faint, flickering image of the Stellar Fulcrum." },
    [1105] = { name = "Crimson Key", description = "This ancient key has been weathered by the years, save for the single flawless ruby that gleams softly from its resting place in the grip." },
    [1106] = { name = "Viridian Key", description = "This ancient key has been weathered by the years, save for the single flawless emerald that gleams softly from its resting place in the grip." },
    [1107] = { name = "Amber Key", description = "This ancient key has been weathered by the years, save for the single flawless topaz that gleams softly from its resting place in the grip." },
    [1108] = { name = "Azure Key", description = "This ancient key has been weathered by the years, save for the single flawless sapphire that gleams softly from its resting place in the grip." },
    [1109] = { name = "Ivory Key", description = "This ancient key has been weathered by the years, save for the single flawless pearl that gleams softly from its resting place in the grip." },
    [1110] = { name = "Ebon Key", description = "This ancient key has been weathered by the years, save for the single flawless onyx that gleams softly from its resting place in the grip." },
    [1111] = { name = "Delkfutt key", description = "This key is needed to gain access to certain areas of Delkfutt's Tower." },
    [1112] = { name = "beastbane arrowheads", description = "The freshly cast arrowheads crackle with a frozen flame..." },
    [1113] = { name = "red-labeled crate", description = "A small wooden crate adorned with a nondescript red label, underneath which you can detect the remains of a label of a different color. Though not heavy, you sense that there is something within..." },
    [1114] = { name = "blue-labeled crate", description = "A small wooden crate adorned with a nondescript blue label, underneath which you can detect the remains of a label of a different color. Though not heavy, you sense that there is something within..." },
    [1115] = { name = "green-labeled crate", description = "A small wooden crate adorned with a nondescript green label, underneath which you can detect the remains of a label of a different color. Though not heavy, you sense that there is something within..." },
    [1116] = { name = "\"Elite Training: Introduction\"", description = "A transcript of pages 1-10 of the elite training section of the Field Manual. Trade this along with beastmen's seals, gil, or a piece of equipment at designated locations in order to commence your training." },
    [1117] = { name = "\"Elite Training: Chapter 1\"", description = "A transcript of pages 11-20 of the elite training section of the Field Manual. Trade this along with beastmen's seals, gil, or a piece of equipment at designated locations in order to commence your training." },
    [1118] = { name = "\"Elite Training: Chapter 2\"", description = "A transcript of pages 21-30 of the elite training section of the Field Manual. Trade this along with beastmen's seals, gil, or a piece of equipment at designated locations in order to commence your training." },
    [1119] = { name = "\"Elite Training: Chapter 3\"", description = "A transcript of pages 31-40 of the elite training section of the Field Manual. Trade this along with beastmen's seals, gil, or a piece of equipment at designated locations in order to commence your training." },
    [1120] = { name = "\"Elite Training: Chapter 4\"", description = "A transcript of pages 41-50 of the elite training section of the Field Manual. Trade this along with beastmen's seals, gil, or a piece of equipment at designated locations in order to commence your training." },
    [1121] = { name = "\"Elite Training: Chapter 5\"", description = "A transcript of pages 51-60 of the elite training section of the Field Manual. Trade this along with beastmen's seals, gil, or a piece of equipment at designated locations in order to commence your training." },
    [1122] = { name = "\"Elite Training: Chapter 6\"", description = "A transcript of pages 61-70 of the elite training section of the Field Manual. Trade this along with beastmen's seals, gil, or a piece of equipment at designated locations in order to commence your training." },
    [1123] = { name = "\"Elite Training: Chapter 7\"", description = "A transcript of pages 71-75 of the elite training section of the Field Manual. Trade this along with beastmen's seals, gil, or a piece of equipment at designated locations in order to commence your training." },
    [1124] = { name = "unadorned ring", description = "Bereft of a stone, this simple yet elegant ring exudes an air of melancholy." },
    [1125] = { name = "Mog Kupon A-DBcd", description = "Issued by the Mog House Management Union (MHMU). Tradeable for relic equipment from Dynamis - Beaucedine." },
    [1126] = { name = "Mog Kupon A-DXar", description = "Issued by the Mog House Management Union (MHMU). Tradeable for relic equipment from Dynamis - Xarcabard." },
    [1127] = { name = "Prismatic Key", description = "This ancient key has been weathered by the years, save for the single flawless diamond that rests in the grip. When light catches it, it reflects a dazzling, many-colored rainbow." },
    [1128] = { name = "shadow bug", description = "A minute bug-shaped device that allows the close surveillance of the chosen subject. Part of Cait Sith's mysterious arsenal of gadgets." },
    [1129] = { name = "white coral key", description = "A delicate fragment of pure white coral adorns the head of this timeworn key." },
    [1130] = { name = "blue coral key", description = "A delicate fragment of marine blue coral adorns the head of this timeworn key." },
    [1131] = { name = "peach coral key", description = "A delicate fragment of peach-colored coral adorns the head of this timeworn key." },
    [1132] = { name = "black coral key", description = "A delicate fragment of jet-black coral adorns the head of this timeworn key." },
    [1133] = { name = "red coral key", description = "A delicate fragment of deep red coral adorns the head of this timeworn key." },
    [1134] = { name = "angel skin key", description = "A delicate fragment of rare angel skin coral adorns the head of this timeworn key." },
    [1135] = { name = "oxblood key", description = "A delicate fragment of rare oxblood coral adorns the head of this timeworn key." },
    [1136] = { name = "sturdy metal strip", description = "A sturdy-looking strip of mythril. With the right tools, it could be used to reinforce the foundation of a Mog House." },
    [1137] = { name = "piece of rugged tree bark", description = "A thick and rugged sheet of chestnut bark. With the right tools, it could be used to repair the roof of a Mog House." },
    [1138] = { name = "savory lamb roast", description = "This roasted rump of lamb tantalizes your nostrils with a mouthwatering aroma. Even with the right tools...it couldn't be used to repair a Mog House in any conceivable way." },
    [1139] = { name = "Orb of Swords", description = "Found in the Horutoto Ruins, this Mana Orb emanates a powerful magical aura. The emblem of a sword gleams on its surface." },
    [1140] = { name = "Orb of Cups", description = "Found in the Horutoto Ruins, this Mana Orb emanates a powerful magical aura. The emblem of a chalice gleams on its surface." },
    [1141] = { name = "Orb of Batons", description = "Found in the Horutoto Ruins, this Mana Orb emanates a powerful magical aura. The emblem of a scepter gleams on its surface." },
    [1142] = { name = "Orb of Coins", description = "Found in the Horutoto Ruins, this Mana Orb emanates a powerful magical aura. The emblem of a coin gleams on its surface." },
    [1143] = { name = "ripe starfruit", description = "Ripened to perfection, this piece of starfruit gives off the luscious aroma of its sweet nectar." },
    [1144] = { name = "moldy, worm-eaten chest", description = "This filthy, worm-eaten chest purportedly contains your moogle friend's entire life savings." },
    [1145] = { name = "stone of Surya", description = "A ruby of flawless cut and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1146] = { name = "stone of Chandra", description = "A pearl of flawless purity and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1147] = { name = "stone of Mangala", description = "A red coral of flawless cut and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1148] = { name = "stone of Budha", description = "An emerald of flawless cut and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1149] = { name = "stone of Brihaspati", description = "A yellow sapphire of flawless cut and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1150] = { name = "stone of Shukra", description = "A diamond of flawless cut and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1151] = { name = "stone of Shani", description = "A blue sapphire of flawless cut and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1152] = { name = "stone of Rahu", description = "A hessonite of flawless cut and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1153] = { name = "stone of Ketu", description = "A cat's-eye of flawless cut and luster, created by a legendary king to honor one of the nine cosmic forces. It is said the complete set shall grant its owner entry into the halls of darkness..." },
    [1154] = { name = "Trivia Challenge Kupon", description = "A prize obtained by completing \"The Elemental Casket of Mystique and Mystery.\" It reads, \"This kupon entitles one (1) lucky contestant to participate in the 'Vrtra's 64,000,000 Gil Question' challenge at our Xarcabard venue, kupo.\"" },
    [1155] = { name = "Gauntlet Challenge Kupon", description = "A prize obtained by completing \"Vrtra's 64,000,000 Gil Question.\" It reads, \"This kupon entitles one (1) lucky contestant to participate in the 'Gauntlet of Fortitude' at our Castle Zvahl Baileys festival venue, kupo.\"" },
    [1156] = { name = "Festival Souvenir Kupon", description = "A prize obtained by successfully navigating \"The Gauntlet of Fortitude.\" It reads, \"The lucky holder of this kupon is eligible for a very special souvenir at our stalls situated in Castle Zvahl Keep, kupo!\"" },
    [1157] = { name = "pocket mogbomb", description = "A small handbomb obtained from \"The Elemental Casket of Mystique and Mystery.\" The moogle emcee has offered you a special prize for its return." },
    [1158] = { name = "Navaratna talisman", description = "The set of nine cosmic gems, joined by an otherworldly force to form a dazzling pendant. Dancing wisps of ethereal light beckon you to the halls of darkness..." },
    [1159] = { name = "Mega Bonanza Kupon", description = "A gaudily illustrated ticket with flowery letters that read, \"This kupon entitles one (1) incredibly lucky contestant to participate in the exclusive Mega Mog Bonanza-Rama-Palooza! How exciting is that, kupo!?\"" },
    [1160] = { name = "aroma bug", description = "A minute bug-shaped device that releases a distinctive fragrance for a set duration. Part of Cait Sith's mysterious arsenal of gadgets." },
    [1161] = { name = "umbra bug", description = "A minute bug-shaped device that allows the bearer to enter a barrier of Cait Sith's making. Part of Cait Sith's mysterious arsenal of gadgets." },
    [1162] = { name = "north-bound petition", description = "Signatures you have gathered from Kingdom knights adorn this sheet of parchment." },
    [1163] = { name = "Ponono's charm", description = "A charming little wristband comprised of three intertwining strands of vividly hued thread, crafted by Ponono of the Windurstian Clothcrafters' guild." },
    [1164] = { name = "delicate wool thread", description = "A spool of fine wool thread entrusted to you by Ponono. Magically treated with her family's secret recipe, it will take on a brilliant hue if dipped in the waters of the Knightwell in West Ronfaure." },
    [1165] = { name = "delicate linen thread", description = "A spool of fine linen thread entrusted to you by Ponono. Magically treated with her family's secret recipe, it will take on a brilliant hue if dipped in the waters of the Fay Spring of Grauberg." },
    [1166] = { name = "delicate cotton thread", description = "A spool of fine cotton thread entrusted to you by Ponono. Magically treated with her family's secret recipe, it will take on a brilliant hue if dipped in the waters of Lake Tepokalipuka in East Sarutabaruta." },
    [1167] = { name = "enchanted wool thread", description = "A spool of fine wool thread entrusted to you by Ponono. Having been dipped in the mystic waters of the Knightwell, it now shimmers with a brilliant red hue." },
    [1168] = { name = "enchanted linen thread", description = "A spool of fine linen thread entrusted to you by Ponono. Having been dipped in the mystic waters of the Fay Spring, it now shimmers with a brilliant blue hue." },
    [1169] = { name = "enchanted cotton thread", description = "A spool of fine cotton thread entrusted to you by Ponono. Having been dipped in the mystic waters of Lake Tepokalipuka, it now shimmers with a brilliant green hue." },
    [1170] = { name = "wax seal", description = "The curious odor it emits is the only feature that distinguishes this goblin-fashioned replica of the official Bastokan seal from the real thing." },
    [1171] = { name = "sack of victuals", description = "Lovingly assembled for the incarcerated Zeid by his number one fan, Gentle Tiger, this cloth sack is stuffed chock full of Galkan sausages, meat jerky, and assorted other provisions sure to rouse the spirits of a down-on-his-luck Galka." },
    [1172] = { name = "commander's endorsement", description = "A letter of recommendation drafted by Captain Herbert, certifying you as loyal, fit, and able to serve as a security officer in the President's retinue." },
    [1173] = { name = "succulent dragon fruit", description = "A particularly luscious and juicy specimen of the tasty cactus fruit. The preferred delicacy of the young Mithran gourmand Syu Befrathi." },
    [1174] = { name = "shard of optistone", description = "A shard of magicite retrieved from deep in the heart of Davoi. Murky whorls of menacing energy wrench and twist within." },
    [1175] = { name = "shard of aurastone", description = "A shard of magicite retrieved from deep in the heart of Beadeaux. Murky whorls of menacing energy wrench and twist within." },
    [1176] = { name = "shard of orastone", description = "A shard of magicite retrieved from deep in the heart of Castle Oztroja. Whorls of murky, menacing energy wrench and twist within." },
    [1177] = { name = "prospector's pan", description = "A simple, unadorned pan of iron used to pan for gold and other precious metals. Lent to you by Titus of the Alchemists' Guild." },
    [1178] = { name = "corked ampoule", description = "A small bottle with a cork stopper to seal in the contents, entrusted to you by Titus of the Alchemists' Guild. You are to return it to him with twenty grains of magical gold dust." },
    [1179] = { name = "ampoule of gold dust", description = "This small bottle contains twenty grains of gold dust retrieved from the streams of Grauberg. Titus will be thrilled to hear word of your success!" },
    [1180] = { name = "vial of military prism powder", description = "Standard issue Kingdom prism powder, concocted according to a secret formula for enhanced and longer lasting invisibility." },
    [1181] = { name = "lance fish", description = "A saltwater fish whose streamlined shape gave birth to its moniker. Its sinewy flesh, while spurned by other races, has made it a perennial favorite among Gigas." },
    [1182] = { name = "paladin lobster", description = "A crustacean armored in an imposing shell of peerless hardiness that inspired its name. Its pungent flesh has earned it a home among the Gigas' most sought-after delicacies." },
    [1183] = { name = "scutum crab", description = "With a carapace resembling a shield, the poisonous flesh of this crab is said to assault the Gigas palate with a stimulating tang they find irresistible." },
    [1184] = { name = "Moogle key", description = "A timeworn key wrought of an unknown metal, adorned with the sign of the Moogle constellation on its discoid grip." },
    [1185] = { name = "Bird key", description = "A timeworn key wrought of an unknown metal, adorned with the sign of the Bird constellation on its discoid grip." },
    [1186] = { name = "Cactuar key", description = "A timeworn key wrought of an unknown metal, adorned with the sign of the Cactuar constellation on its discoid grip." },
    [1187] = { name = "Bomb key", description = "A timeworn key wrought of an unknown metal, adorned with the sign of the Bomb constellation on its discoid grip." },
    [1188] = { name = "Chocobo key", description = "A timeworn key wrought of an unknown metal, adorned with the sign of the Chocobo constellation on its discoid grip." },
    [1189] = { name = "Tonberry key", description = "A timeworn key wrought of an unknown metal, adorned with the sign of the Tonberry constellation on its discoid grip." },
    [1190] = { name = "Behemoth key", description = "A timeworn key wrought of an unknown metal, adorned with the sign of the Behemoth constellation on its discoid grip." },
    [1191] = { name = "Domina's scarlet seal", description = "An enchanted sheet of parchment issued to you by Domina Shantotto, mounted on a counterseal that serves to contain its power until attached to the corresponding protocrystal. It feels faintly warm to the touch." },
    [1192] = { name = "Domina's cerulean seal", description = "An enchanted sheet of parchment issued to you by Domina Shantotto, mounted on a counterseal that serves to contain its power until attached to the corresponding protocrystal. It feels oddly moist to the touch." },
    [1193] = { name = "Domina's emerald seal", description = "An enchanted sheet of parchment issued to you by Domina Shantotto, mounted on a counterseal that serves to contain its power until attached to the corresponding protocrystal. It dances within your grip as if blown about by a breeze." },
    [1194] = { name = "Domina's amber seal", description = "An enchanted sheet of parchment issued to you by Domina Shantotto, mounted on a counterseal that serves to contain its power until attached to the corresponding protocrystal. An earthy aroma emanates from it." },
    [1195] = { name = "Domina's violet seal", description = "An enchanted sheet of parchment issued to you by Domina Shantotto, mounted on a counterseal that serves to contain its power until attached to the corresponding protocrystal. A tingling sensation runs through your hand at its touch." },
    [1196] = { name = "Domina's azure seal", description = "An enchanted sheet of parchment issued to you by Domina Shantotto, mounted on a counterseal that serves to contain its power until attached to the corresponding protocrystal. It feels faintly chill to the touch." },
    [1197] = { name = "scarlet counterseal", description = "Domina Shantotto's scarlet seal has been attached to the fire protocrystal and is no longer mounted on this sheet of magicked parchment. It should serve as proof of obedience to your empress." },
    [1198] = { name = "cerulean counterseal", description = "Domina Shantotto's cerulean seal has been attached to the water protocrystal and is no longer mounted on this sheet of magicked parchment. It should serve as proof of obedience to your empress." },
    [1199] = { name = "emerald counterseal", description = "Domina Shantotto's emerald seal has been attached to the wind protocrystal and is no longer mounted on this sheet of magicked parchment. It should serve as proof of obedience to your empress." },
    [1200] = { name = "amber counterseal", description = "Domina Shantotto's amber seal has been attached to the earth protocrystal and is no longer mounted on this sheet of magicked parchment. It should serve as proof of obedience to your empress." },
    [1201] = { name = "violet counterseal", description = "Domina Shantotto's violet seal has been attached to the lightning protocrystal and is no longer mounted on this sheet of magicked parchment. It should serve as proof of obedience to your empress." },
    [1202] = { name = "azure counterseal", description = "Domina Shantotto's azure seal has been attached to the ice protocrystal and is no longer mounted on this sheet of magicked parchment. It should serve as proof of obedience to your empress." },
    [1203] = { name = "black book", description = "A well-worn book containing a record of Tenshodo transactions for the past calendar year. Black tiger hide has been used to bind its pages together." },
    [1204] = { name = "luminous red fragment", description = "A peculiar triangular fragment formed of a luminous material seemingly not of this world. Although it transitions through a number of hues, red is its predominant color. Your keen sense of geometry tells you that six of these will form a perfect hexagon." },
    [1205] = { name = "luminous beige fragment", description = "A peculiar triangular fragment formed of a luminous material seemingly not of this world. Although it transitions through a number of hues, beige is its predominant color. Your keen sense of geometry tells you that six of these will form a perfect hexagon." },
    [1206] = { name = "luminous green fragment", description = "A peculiar triangular fragment formed of a luminous material seemingly not of this world. Although it transitions through a number of hues, green is its predominant color. Your keen sense of geometry tells you that six of these will form a perfect hexagon." },
    [1207] = { name = "luminous yellow fragment", description = "A peculiar triangular fragment formed of a luminous material seemingly not of this world. Although it transitions through a number of hues, yellow is its predominant color. Your keen sense of geometry tells you that six of these will form a perfect hexagon." },
    [1208] = { name = "luminous purple fragment", description = "A peculiar triangular fragment formed of a luminous material seemingly not of this world. Although it transitions through a number of hues, purple is its predominant color. Your keen sense of geometry tells you that six of these will form a perfect hexagon." },
    [1209] = { name = "luminous blue fragment", description = "A peculiar triangular fragment formed of a luminous material seemingly not of this world. Although it transitions through a number of hues, blue is its predominant color. Your keen sense of geometry tells you that six of these will form a perfect hexagon." },
    [1210] = { name = "fire sap crystal", description = "The sap of the Great Star Tree in crystallized form, found within the gloom of the Toraimarai Canal. It is faintly aglow with fire energy." },
    [1211] = { name = "water sap crystal", description = "The sap of the Great Star Tree in crystallized form, found within the gloom of the Toraimarai Canal. It is faintly aglow with water energy." },
    [1212] = { name = "wind sap crystal", description = "The sap of the Great Star Tree in crystallized form, found within the gloom of the Toraimarai Canal. It is faintly aglow with wind energy." },
    [1213] = { name = "earth sap crystal", description = "The sap of the Great Star Tree in crystallized form, found within the gloom of the Toraimarai Canal. It is faintly aglow with earth energy." },
    [1214] = { name = "lightning sap crystal", description = "The sap of the Great Star Tree in crystallized form, found within the gloom of the Toraimarai Canal. It is faintly aglow with lightning energy." },
    [1215] = { name = "ice sap crystal", description = "The sap of the Great Star Tree in crystallized form, found within the gloom of the Toraimarai Canal. It is faintly aglow with ice energy." },
    [1216] = { name = "light sap crystal", description = "The sap of the Great Star Tree in crystallized form, found within the gloom of the Toraimarai Canal. It is faintly aglow with light energy." },
    [1217] = { name = "dark sap crystal", description = "The sap of the Great Star Tree in crystallized form, found within the gloom of the Toraimarai Canal. It is faintly aglow with dark energy." },
    [1218] = { name = "Tablet of Hexes: Greed", description = "The first in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Temple of Uggalepih. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1219] = { name = "Tablet of Hexes: Envy", description = "The second in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Temple of Uggalepih. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1220] = { name = "Tablet of Hexes: Malice", description = "The third in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Temple of Uggalepih. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1221] = { name = "Tablet of Hexes: Deceit", description = "The fourth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Temple of Uggalepih. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1222] = { name = "Tablet of Hexes: Pride", description = "The fifth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Temple of Uggalepih. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1223] = { name = "Tablet of Hexes: Bale", description = "The sixth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Temple of Uggalepih. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1224] = { name = "Tablet of Hexes: Despair", description = "The seventh in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1225] = { name = "Tablet of Hexes: Regret", description = "The eighth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1226] = { name = "Tablet of Hexes: Rage", description = "The ninth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1227] = { name = "Tablet of Hexes: Agony", description = "The tenth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1228] = { name = "Tablet of Hexes: Dolor", description = "The eleventh in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1229] = { name = "Tablet of Hexes: Rancor", description = "The twelfth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1230] = { name = "Tablet of Hexes: Strife", description = "The thirteenth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1231] = { name = "Tablet of Hexes: Penury", description = "The fourteenth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1232] = { name = "Tablet of Hexes: Blight", description = "The fifteenth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1233] = { name = "Tablet of Hexes: Death", description = "The sixteenth in a concatenation of ancient stone tablets passed down over millennia by the Tonberry race, found within the Den of Rancor. Engraved in indecipherable runes, a single tablet is said to hold the anguish of a thousand tortured souls." },
    [1234] = { name = "synergy crucible", description = "This compact receptacle designed for use with a synergy furnace serves the dual purpose of shielding the materials within from sudden surges of elemental forces and dispensing fewell to facilitate the synergy process." },
    [1235] = { name = "Mog Kupon AW-Abs", description = "Issued by the Mog House Management Union (MHMU). Tradeable for spoils from Absolute Virtue." },
    [1236] = { name = "Mog Kupon AW-Pan", description = "Issued by the Mog House Management Union (MHMU). Tradeable for items from Pandemonium Warden." },
    [1237] = { name = "magelight signal flare", description = "A magically powered signal flare of Windurstian design, used as a means of communication on the battlefield." },
    [1238] = { name = "alchemical signal flare", description = "An alchemically constructed signal flare of Bastokan design, used as a means of communication on the battlefield." },
    [1239] = { name = "distress signal flare", description = "A distress signal flare of San d'Orian design, the emitted light universally recognized the Middle Lands over as an emergency call for aid." },
    [1240] = { name = "Imperial missive", description = "A letter addressed to the four nations of the Middle Lands, penned by Ghatsad and bearing the seals of the Empress and the Aht Urhgan Archaeological Research Institute. It contains detailed data on the iron colossus and a concise summary of the Empire's plight." },
    [1241] = { name = "San d'Orian approval letter", description = "A document bearing the official seal of House d'Oraguille, pledging the Kingdom's support in the operation to reactivate the colossus." },
    [1242] = { name = "Bastokan approval letter", description = "A document bearing the waterwheel-and-chimney seal of Bastok, pledging the Republic's support in the operation to reactivate the colossus." },
    [1243] = { name = "Windurstian approval letter", description = "A document bearing a seal depicting the Great Star Tree and the five ministries, pledging the Federation's support in the operation to reactivate the colossus." },
    [1244] = { name = "Jeunoan approval letter", description = "A document bearing a seal of the sun shining upon the three great bridges of Jeuno, pledging the Grand Duchy's support in the operation to reactivate the colossus." },
    [1245] = { name = "present for Megomak", description = "A box wrought of solid bronze, nondescript save for the embossed caduceus that graces its lid. A sturdy lock prevents you from ascertaining its contents, though Ghatsad claims it will serve you well in your negotiations with the Moblin Megomak." },
    [1246] = { name = "lightning cell", description = "A chain of rusty metallic receptacles haphazardly strung together with mottled wire. If Megomak speaks true, its underwhelming appearance belies the capability to store and discharge copious amounts of energy." },
    [1247] = { name = "Megomak's shopping list", description = "A grimy, tattered piece of parchment upon which \"plumbago: 3 slabs\" has been hastily jotted down in a near-illegible scrawl." },
    [1248] = { name = "whisper of radiance", description = "You can sense its presence, but it cannot be seen." },
    [1249] = { name = "talisman of the rebel gods", description = "An exquisitely wrought talisman bearing the twin emblems of Ephramad, the crowned dolphin and the Dark Rider. Painstakingly restored, it looks just as it must have when Kingdom soldiers carried it into battle." },
    [1250] = { name = "message from Yoyoroon", description = "\"Yooo find loooky charm in Airy-pago, maybe yooo dooo?\" has been scribbled in sloppy yet somehow charming handwriting. A far more legible postscript reads, \"A treat or two from the Shararat Teahouse would be most welcome.\"" },
    [1251] = { name = "whisper of gloom", description = "You can sense its presence, but it cannot be seen." },
    [1252] = { name = "spatial pressure barometer", description = "A handheld device outfitted with a befuddling array of knobs and switches. According to Ghatsad, you need only keep it in your possession to collect all the necessary data from the Hazhalm spatial distortion." },
    [1253] = { name = "clear abyssite", description = "A colorless, transparent stone of otherworldly origin, its core aglitter with innumerable refracted light. It is said to react to beings that originate from its home world." },
    [1254] = { name = "colorful abyssite", description = "Contact with a creature native to its home world has caused this formerly colorless stone to take on a hodgepodge of hues. You sense a growing power emanating from within." },
    [1255] = { name = "blue abyssite", description = "The confused hues of this otherworldly stone have stabilized and become a rich blue. You sense tremendous power emanating from within." },
    [1256] = { name = "orange abyssite", description = "The confused hues of this otherworldly stone have stabilized and become a vibrant orange. You sense tremendous power emanating from within." },
    [1257] = { name = "brown abyssite", description = "The confused hues of this otherworldly stone have stabilized and become a mellow brown. You sense tremendous power emanating from within." },
    [1258] = { name = "yellow abyssite", description = "The confused hues of this otherworldly stone have stabilized and become a blazing yellow. You sense tremendous power emanating from within." },
    [1259] = { name = "purple abyssite", description = "The confused hues of this otherworldly stone have stabilized and become a deep purple. You sense tremendous power emanating from within." },
    [1260] = { name = "black abyssite", description = "Even the darkest night pales to gray beside the abyssal black of this stone. It feels ripe to burst with unadulterated power." },
    [1261] = { name = "Magian trial log", description = "A mystical tome bestowed upon you by the Magian Mooglehood, said to record your attempts and exploits in the trials to the last detail." },
    [1262] = { name = "Mog Kupon A-Lum", description = "Issued by the Mog House Management Union (MHMU). Tradeable for spoils from notorious monsters in Lumoria." },
    [1263] = { name = "talisman key", description = "The necessary alchemical enhancements having been completed by Ghatsad, this talisman now possesses the power to transport its bearer to the innermost chambers of the Hazhalm Testing Grounds." },
    [1264] = { name = "letter from Halver", description = "A congratulatory letter from Halver. It bears the wax seal of the Kingdom of San d'Oria." },
    [1265] = { name = "letter from Naji", description = "A congratulatory letter from Naji. It comes adorned with an illustration lovingly drawn by the man himself." },
    [1266] = { name = "letter from Zubaba", description = "A congratulatory letter from Zubaba. It is impressed with the emblem of the Federation of Windurst." },
    [1267] = { name = "letter from Maat", description = "A congratulatory letter from Maat. The odor of sweat clings stubbornly to it." },
    [1268] = { name = "letter from Despachiaire", description = "A congratulatory letter from Despachiaire. Its musty smell puts you in mind of a disused storeroom." },
    [1269] = { name = "letter from Jakoh Wahcondalo", description = "A congratulatory letter from Jakoh Wahcondalo. It exudes the faint odor of fish." },
    [1270] = { name = "Zvahl passkey", description = "Crafted from the same chill stone that forms the foreboding walls of the fortress itself, this key will grant its bearer passage to the deepest, dankest chambers of the Shadow Lord's stronghold." },
    [1271] = { name = "traverser stone", description = "A magically imbued stone that allows travel to Abyssea. Also serves as a stabilizing agent that realigns and anchors your essence to foreign dimensions." },
    [1272] = { name = "traverser stone", description = "A magically imbued stone that allows travel to Abyssea. Also serves as a stabilizing agent that realigns and anchors your essence to foreign dimensions." },
    [1273] = { name = "traverser stone", description = "A magically imbued stone that allows travel to Abyssea. Also serves as a stabilizing agent that realigns and anchors your essence to foreign dimensions." },
    [1274] = { name = "traverser stone", description = "A magically imbued stone that allows travel to Abyssea. Also serves as a stabilizing agent that realigns and anchors your essence to foreign dimensions." },
    [1275] = { name = "traverser stone", description = "A magically imbued stone that allows travel to Abyssea. Also serves as a stabilizing agent that realigns and anchors your essence to foreign dimensions." },
    [1276] = { name = "traverser stone", description = "A magically imbued stone that allows travel to Abyssea. Also serves as a stabilizing agent that realigns and anchors your essence to foreign dimensions." },
    [1277] = { name = "poet god's key", description = "This ornate bamboo key with its sharp jutting protrusions is at once ghastly and beautiful. The surface is graven with an excerpt from the legendary eclogue of Ree Habalo, the first Manifest of the Yagudo." },
    [1278] = { name = "Orcish infiltration kit", description = "Includes a meticulously recreated Orcish costume that is accurate right down to the ripe stench. Fashioned by a genius San d'Orian engineer of undisclosed identity for use in covert operations into Fort Ghelsba." },
