    [1444] = { name = "white stratum abyssite", description = "A pure white geode shaped like a six-pointed star, carried by all who seek to participate in Voidwatch operations at planar rifts. Its exact properties far beyond layman comprehension, it is said to feed off the energies of slain Voidwalkers to take on heightened powers..." },
