    [1538] = { name = "crimson traverser stone", description = "Richly coated in multiple layers of melted cruor, this unique variety of traverser stone aligns users to the existential phase of Abyssea - Empyreal Paradox." },
    [1539] = { name = "voidstone", description = "Developed by a Jeuno-based research team, this mineral compound has the power to pull energies from beyond planar rifts into the bearer's own existential phase. An essential item issued to all soldiers of the Voidwatch." },
    [1540] = { name = "voidstone", description = "Developed by a Jeuno-based research team, this mineral compound has the power to pull energies from beyond planar rifts into the bearer's own existential phase. An essential item issued to all soldiers of the Voidwatch." },
    [1541] = { name = "voidstone", description = "Developed by a Jeuno-based research team, this synthetic mineral compound grants its bearer the power to manipulate dimensional alignment. An indispensible item furnished to all soldiers of the Voidwatch." },
    [1542] = { name = "voidstone", description = "Developed by a Jeuno-based research team, this synthetic mineral compound grants its bearer the power to manipulate dimensional alignment. An indispensible item furnished to all soldiers of the Voidwatch." },
    [1543] = { name = "voidstone", description = "Developed by a Jeuno-based research team, this synthetic mineral compound grants its bearer the power to manipulate dimensional alignment. An indispensible item furnished to all soldiers of the Voidwatch." },
    [1544] = { name = "voidstone", description = "Developed by a Jeuno-based research team, this synthetic mineral compound grants its bearer the power to manipulate dimensional alignment. An indispensible item furnished to all soldiers of the Voidwatch." },
    [1545] = { name = "crimson granules of time", description = "Thought to have once flowed within the prismatic hourglass, these granules of sand cast a dark red light." },
    [1546] = { name = "azure granules of time", description = "Thought to have once flowed within the prismatic hourglass, these granules of sand cast a deep blue light." },
    [1547] = { name = "amber granules of time", description = "Thought to have once flowed within the prismatic hourglass, these granules of sand cast a yellowish light." },
    [1548] = { name = "alabaster granules of time", description = "Thought to have once flowed within the prismatic hourglass, these granules of sand cast a pure white light." },
    [1549] = { name = "obsidian granules of time", description = "Thought to have once flowed within the prismatic hourglass, these granules of sand cast an opaque, black light." },
    [1550] = { name = "prismatic hourglass", description = "The granules inside this time piece glimmer with a myriad of colors, yet no matter how violently one upends this device, they move not an inch. Rumors abound that it holds some connection to the Shrouded Land of Dynamis." },
    [1551] = { name = "Mog Kupon W-R90", description = "Issued by the Mog House Management Union (MHMU). Tradeable for level 90 relic weapons." },
    [1552] = { name = "Mog Kupon W-M90", description = "Issued by the Mog House Management Union (MHMU). Tradeable for level 90 mythic weapons." },
    [1553] = { name = "Mog Kupon W-E90", description = "Issued by the Mog House Management Union (MHMU). Tradeable for level 90 empyrean equipment." },
    [1554] = { name = "Mog Kupon A-E+2", description = "Issued by the Mog House Management Union (MHMU). Tradeable for Empyrean equipment +2." },
    [1555] = { name = "Mog Kupon I-Seal", description = "Issued by the Mog House Management Union (MHMU). Tradeable for seals used in the enhancement of job-specific equipment." },
    [1556] = { name = "beguiling petrifact", description = "A bewitching light shines forth from within the crystallized walls of this fragment ripped from a Voidwalker, as if beckoning its bearer to come hither." },
    [1557] = { name = "seductive petrifact", description = "A tantalizing light shines forth from within the crystallized walls of this fragment ripped from a Voidwalker, as if appealing to its bearer's most ardent desires." },
    [1558] = { name = "maddening petrifact", description = "A crazed light shines forth from within the crystallized walls of this fragment ripped from a Voidwalker, as if seeking to breach the bearer's last bastion of sanity." },
    [1559] = { name = "vat of martello fuel", description = "A thick, viscous liquid infused with magic that serves to power a martello's restorative capabilities. Highly dense, it is considerably heavier than it appears." },
    [1560] = { name = "fuel reservoir", description = "A spare tank that can be installed in a martello to increase its fuel capacity. Cast of steel and of considerable size, it is extremely unwieldy to transport." },
    [1561] = { name = "empty fuel vat", description = "A vat for holding martello fuel, now empty." },
    [1562] = { name = "cracked fuel reservoir", description = "A martello fuel reservoir, cracked beyond the point of utility due to excessive wear and tear." },
    [1563] = { name = "vial of lambent potion", description = "A bitter potion steeped in ground lambent scales, said to be a powerful restorative for memories and the mind." },
    [1564] = { name = "clear demilune abyssite", description = "A colorless, transparent stone of otherworldly origin, shaped like a crescent moon. Its core aglitter with innumerable refracted light, it is said to react to the presence of Abyssean fiends." },
    [1565] = { name = "colorful demilune abyssite", description = "Contact with an Abyssean fiend has caused this formerly colorless crescent stone to take on a hodgepodge of hues. You sense a growing power emanating from within." },
    [1566] = { name = "scarlet demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a deep red. You sense tremendous power emanating from within." },
    [1567] = { name = "azure demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a rich blue. You sense tremendous power emanating from within." },
    [1568] = { name = "viridian demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a vivid green. You sense tremendous power emanating from within." },
    [1569] = { name = "anti-Abyssean grenade #01", description = "An experimental grenade loaded with an explosive charge optimized for use against Abyssean monsters." },
    [1570] = { name = "anti-Abyssean grenade #02", description = "An experimental grenade loaded with an explosive charge optimized for use against Abyssean monsters." },
    [1571] = { name = "anti-Abyssean grenade #03", description = "An experimental grenade loaded with an explosive charge optimized for use against Abyssean monsters." },
    [1572] = { name = "rainbow pearl", description = "A hefty round pearl whose color transitions through a rainbow of hues. A key component in the repairs of searing wards." },
    [1573] = { name = "chipped wind cluster", description = "A cluster of wind crystals that is slightly the worse for wear. A key component in the repairs of searing wards." },
    [1574] = { name = "piece of dried ebony lumber", description = "A piece of processed ebony lumber that has been magically purged of all moisture. A key component in the repairs of searing wards." },
    [1575] = { name = "Captain Rashid's linkpearl", description = "A replacement linkpearl entrusted to you by Captain Ayame, with instructions that it be delivered to Captain Rashid at Camp Courage." },
    [1576] = { name = "Captain Argus's linkpearl", description = "A replacement linkpearl entrusted to you by Captain Ayame, with instructions that it be delivered to Captain Argus at Camp Hope." },
    [1577] = { name = "Captain Helga's linkpearl", description = "A replacement linkpearl entrusted to you by Captain Ayame, with instructions that it be delivered to Captain Helga at Camp Vigilance." },
    [1578] = { name = "seal of the resistance", description = "A seal that identifies you as a resistance soldier dispatched by Captain Ayame. Show this and state the password of \"rose on the heath,\" and even the wariest resistance officer will have no cause to doubt your identity." },
    [1579] = { name = "sunbeam fragment", description = "A sunbeam fragment found at the bottom of a ravine in the La Theine Plateau. Becomes invisible by night." },
    [1580] = { name = "Lugarhoo's eyeball", description = "The left eyeball of Lugarhoo, the vicious gnole said to have savaged Curilla. The depth of its luster shifts with the lunar phase." },
    [1581] = { name = "vial of purification agent (blk.)", description = "A vial you received from Miageau filled with a chemical for treating contaminated water. It is affixed with a black label." },
    [1582] = { name = "vial of purification agent (brz.)", description = "A vial you received from Miageau filled with a chemical for treating contaminated water. It is affixed with a bronze label." },
    [1583] = { name = "vial of purification agent (slv.)", description = "A vial you received from Miageau filled with a chemical for treating contaminated water. It is affixed with a silver label." },
    [1584] = { name = "vial of purification agent (gld.)", description = "A vial you received from Miageau filled with a chemical for treating contaminated water. It is affixed with a gold label." },
    [1585] = { name = "black-labeled vial", description = "This vial contains a water sample drawn from a La Theine pond after it had been treated with a purification agent." },
    [1586] = { name = "bronze-labeled vial", description = "This vial contains a water sample drawn from a La Theine pond after it had been treated with a purification agent." },
    [1587] = { name = "silver-labeled vial", description = "This vial contains a water sample drawn from a La Theine pond after it had been treated with a purification agent." },
    [1588] = { name = "gold-labeled vial", description = "This vial contains a water sample drawn from a La Theine pond after it had been treated with a purification agent." },
    [1589] = { name = "rainbow-colored linkpearl", description = "A colorful linkpearl you received from Glenne. It appears optimized for use by intelligence operatives." },
    [1590] = { name = "grey abyssite", description = "The confused hues of this otherworldly stone have stabilized and become an ashen grey. You sense tremendous power emanating from within." },
    [1591] = { name = "ripe starfruit", description = "A starfruit from the stores of the Manustery. By its color and mouth- watering aroma, you would swear it was freshly picked." },
    [1592] = { name = "vial of flower-wower fertilizer", description = "Developed by the Rhinostery and (supposedly) perfected by Piketo-Puketo of the Culinarians' Guild, this liquid is said to \"inject even the droopy-woopiest plants with a shotaru of vim and vigor!\"" },
    [1593] = { name = "Tahrongi tree nut", description = "A hard-shelled nut roughly the size of your fist. It would appear that the fertilizer was as effective as advertised..." },
    [1594] = { name = "bucket of compound compost", description = "A gooey, fetid substance of decaying plant and animal waste matter prepared by Rhinostery researchers. Said to be a preferred snack of mandragora and similar species." },
    [1595] = { name = "cup of Tahrongi cactus water", description = "A clear liquid that gives off a faintly floral aroma. It is believed to be a natural remedy for an assortment of ailments and afflictions." },
    [1596] = { name = "hastily scrawled poster", description = "This grimy, smudged parchment bears a drawing of two indescript stick figures that appear to have been drawn by an artistically challenged child. A near-illegible scrawl underneath reads, \"Deer Boss! We r fyne. Come fynd us quicklee! -Cha 'n Bopa\"" },
    [1597] = { name = "bloodied arrow", description = "This broken arrow was retrieved from the body of a particularly fearsome fiend that had been terrorizing Abyssea - Tahrongi. The arrowhead has been snapped clean off." },
    [1598] = { name = "crimson bloodstone", description = "This gemlike substance of coagulated blood was cut from the body of a monstrous fiend that had been roaming Abyssea - Tahrongi. It resembles an oversized, semitransparent piece of cruor." },
    [1599] = { name = "Kupofried's medallion", description = "The new form taken by your hard-earned gil, if Kupofried the moogle is to be believed. Allows the use of veridical confluxes located in Vana'diel and the Walk of Echoes." },
    [1600] = { name = "pinch of moist Dangruf sulfur", description = "With access to the Dangruf Wadi sealed off by landslides, even a pinch of this rather ordinary sulfur fetches a prohibitive price." },
    [1601] = { name = "Naji's gauger plate", description = "Entrusted to you by Naji, upon this plate is burned the soulprint of a massive purple-skinned fiend. This vital intel must be delivered to Captain Helga without delay." },
    [1602] = { name = "Naji's linkpearl", description = "A linkpearl that Captain Helga has ordered you to deliver to the intelligence expert Naji. It will allow him to relay his latest findings to Captain Ayame at Central Command." },
    [1603] = { name = "pot of martial relish", description = "An irresistibly tasty hot relish made from an age-old recipe, said to grant the resilience of a thousand thorned roses." },
    [1604] = { name = "Thierride's bean creation", description = "Rusty Anchor Pub owner Thierride's latest culinary creation. The rising steam fills your nostrils with the rich aroma of freshly baked beans." },
    [1605] = { name = "tiny memory fragment", description = "The fragment of Lilisette's memory you obtained at the Rusty Anchor Pub. It glows feebly, as if struggling for purchase on existence." },
    [1606] = { name = "large memory fragment", description = "The fragments of Lilisette's memory you found scattered across present- day Vana'diel have melded together to form this larger piece. It radiates warmly with the promise of life." },
    [1607] = { name = "fey stone", description = "A night immersed in the pristine waters of the fey spring has imbued your philosopher's stone with counter-curse properties...hopefully." },
    [1608] = { name = "large memory fragment", description = "The fragment of Lilisette's memory you obtained in past Southern San d'Oria. Born of a daughter's desire to save her father from the jaws of death, it emanates an aura of hope and sorrow." },
    [1609] = { name = "torn recipe page", description = "Roughly torn off a tome, this lone page contains the recipe for what appears to be a traditional Tavnazian dish. It is soiled from its time out in the wilderness." },
    [1610] = { name = "mineral gauge for dummies", description = "Developed by Sieglinde the alchemist, this stick-shaped contraption is used to analyze the mineral composition of soil. Simply thrust it into the earth, and the result will be displayed by way of a colored light." },
    [1611] = { name = "tube of alchemical fertilizer", description = "A liquid fertilizer especially blended by Sieglinde the alchemist, complete with its own injector tube. Although potent, it suffers from severely short shelf-life." },
    [1612] = { name = "large memory fragment", description = "The fragment of Lilisette's memory you obtained in past Batallia Downs. A recollection of Lilisette's escapades as matchmaker for Ragelise and Portia, it emanates a bittersweet aura." },
    [1613] = { name = "large memory fragment", description = "A fragment of Lilisette's memory you obtained in past Vana'diel. Born of her longing to be close to a dear friend, it emanates an aura of fondness." },
    [1614] = { name = "pulse martello repair pack", description = "A shipment of supplies lost en route to the Attohwa resistance outpost. Contains materials used in the maintenance of the pulse martello." },
    [1615] = { name = "clone ward reinforcement pack", description = "A shipment of supplies lost en route to the Attohwa resistance outpost. Contains materials used in the reinforcement of clone wards." },
    [1616] = { name = "pack of outpost repair tools", description = "A shipment of supplies lost en route to the Attohwa resistance outpost. Contains tools used in the maintenance of traps and other defensive structures." },
    [1617] = { name = "Parradamo supply pack", description = "A pack containing a linkpearl and emergency rations, to be delivered to one of the scouts that have gone missing at Parradamo Tor." },
    [1618] = { name = "Parradamo supply pack", description = "A pack containing a linkpearl and emergency rations, to be delivered to one of the scouts that have gone missing at Parradamo Tor." },
    [1619] = { name = "Parradamo supply pack", description = "A pack containing a linkpearl and emergency rations, to be delivered to one of the scouts that have gone missing at Parradamo Tor." },
    [1620] = { name = "Parradamo supply pack", description = "A pack containing a linkpearl and emergency rations, to be delivered to one of the scouts that have gone missing at Parradamo Tor." },
    [1621] = { name = "Parradamo supply pack", description = "A pack containing a linkpearl and emergency rations, to be delivered to one of the scouts that have gone missing at Parradamo Tor." },
    [1622] = { name = "gasponia stamen", description = "The bulbous stamen of the gasponia flower, vividly colored in noxious hues of red and yellow." },
    [1623] = { name = "rockhopper", description = "A rare, distant relative of the grasshopper that makes its habitat in mountainous regions." },
    [1624] = { name = "phial of counteragent", description = "A formula concocted by Yoran-Oran to induce a reverse mutation in the venomous gasponia flower." },
    [1625] = { name = "damaged stewpot", description = "A large, impressive-looking stewpot bearing the mark of the Windurst Culinarians' Guild. A fist-sized hole in its base renders it useless in its current state..." },
    [1626] = { name = "Naruru's stewpot", description = "A large, impressive-looking stewpot bearing the mark of the Windurst Culinarians' Guild, restored just like nouveau by zee ezteemed Ranpi-Monpi." },
    [1627] = { name = "magicked hempen sack", description = "This seemingly nondescript hempen sack has been magically primed for use in transporting pulse martello and clone ward repair materials." },
    [1628] = { name = "magicked flaxen sack", description = "This seemingly nondescript flaxen sack has been magically primed for use in transporting ensorceled battle provisions." },
    [1629] = { name = "paralysis trap fluid", description = "This luminous solution serves as the fuel for rear traps." },
    [1630] = { name = "paralysis trap fluid bottle", description = "This trap fluid bottle has been emptied of its contents and should be returned to the resistance sapper." },
    [1631] = { name = "weakening trap fluid", description = "This luminous solution serves as the fuel for fore traps." },
    [1632] = { name = "weakening trap fluid bottle", description = "This trap fluid bottle has been emptied of its contents and should be returned to the resistance sapper." },
    [1633] = { name = "Iron Eater's pearlsack", description = "A worn grey pearlsack entrusted to you from Iron Eater." },
    [1635] = { name = "medical supply chest", description = "A chest laden with medical supplies for use on the battlefront." },
    [1636] = { name = "woodworker's belt", description = "Cheupirudaux's pride and joy, this handy, many-pocketed belt stores all the repair tools a woodworker could ever need. Stuffed into one pocket is a memo that reads, \"Two if it creaks, four if it wavers, five if it crumbles.\"" },
    [1637] = { name = "espionage pearlsack", description = "The pearls contained in this sack are small in size and dyed with specks of dark green and brown, so as to fool the eyes of one's subject." },
    [1638] = { name = "chipped linkshell", description = "Though weathered somewhat by the elements, this linkshell appears serviceable." },
    [1639] = { name = "grimy linkshell", description = "Though weathered somewhat by the elements, this linkshell appears serviceable." },
    [1640] = { name = "cracked linkshell", description = "Though weathered somewhat by the elements, this linkshell appears serviceable." },
    [1641] = { name = "pocket supply pack", description = "A supply pack entrusted to you by Deraquien. Containing a basic set of lightweight metals, it is designed for hassle-free transport. Deliver it to Elmemague at the outpost, and do so on foot, as it will not withstand the stress of conflux teleportation." },
    [1642] = { name = "standard supply pack", description = "A supply pack entrusted to you by Deraquien. Containing a standard assortment of materials, it is transportable with only moderate difficulty. Deliver it to Elmemague at the outpost, and do so on foot, as it will not withstand the stress of conflux teleportation." },
    [1643] = { name = "hefty supply pack", description = "A supply pack entrusted to you by Deraquien. Containing a full set of high-density metals, it is positively exhausting to carry. Deliver it to Elmemague at the outpost, and do so on foot, as it will not withstand the stress of conflux teleportation." },
    [1644] = { name = "pack of molten slag", description = "Whatever materials were once contained in this supply pack, they are little more than refuse now, having been reduced to a molten mess by the energies of a veridical conflux. You should report the failure of your mission to Deraquien." },
    [1645] = { name = "letter of receipt", description = "A letter from Captain Elmemague at the outpost, certifying the successful delivery of a set of building materials. Return it to Deraquien for your reward." },
    [1646] = { name = "smudged letter", description = "A letter from Teigero-Bangero addressed to his missing wife and child. The ink is smudged in numerous places, most likely from the despondent father's tears..." },
    [1647] = { name = "yellow linkpearl", description = "A linkpearl of vivid yellow entrusted to you by Naruru for her husband Teigero-Bangero. It shines bright, befitting the sunny disposition this loving wife and mother once possessed..." },
    [1648] = { name = "jester's hat", description = "A motley cap that was the favorite of Panta-Putta, Teigero-Bangero and Naruru's willful young son. He now wanders Abyssea - Misareaux in search of his lost mother and father..." },
    [1649] = { name = "jade demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a vivid green. You sense tremendous power emanating from within." },
    [1650] = { name = "sapphire demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a rich blue. You sense tremendous power emanating from within." },
    [1651] = { name = "crimson demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a deep red. You sense tremendous power emanating from within." },
    [1652] = { name = "emerald demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a rich green. You sense tremendous power emanating from within." },
    [1653] = { name = "vermillion demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a vivid red. You sense tremendous power emanating from within." },
    [1654] = { name = "indigo demilune abyssite", description = "The confused hues of this otherworldly crescent stone have stabilized and become a deep blue. You sense tremendous power emanating from within." },
    [1655] = { name = "Atma of the Heir", description = "Fabricated from cruor and the distilled memories of your adventures, this crystalline mass pulsates with energy." },
