    [1700] = { name = "tiny memory fragment", description = "The fragment of Lilisette's memory you obtained in Northern San d'Oria. It glows feebly, as if struggling for purchase on existence." },
    [1701] = { name = "tiny memory fragment", description = "The fragment of Lilisette's memory you obtained in Batallia Downs. It glows feebly, as if struggling for purchase on existence." },
    [1702] = { name = "EX-01 martello core", description = "This martello core expands the pulse martello's functionality, enabling it to reduce martello recast time in the area." },
    [1703] = { name = "EX-02 martello core", description = "This martello core expands the pulse martello's functionality, enabling it to reduce veridical conflux operating costs in the area." },
    [1704] = { name = "EX-03 martello core", description = "This martello core expands the pulse martello's functionality, enabling it to enhance support effect potency in the area." },
    [1705] = { name = "EX-04 martello core", description = "This martello core expands the pulse martello's functionality, enabling it to increase experience yield in the area." },
    [1706] = { name = "EX-05 martello core", description = "This martello core expands the pulse martello's functionality, enabling it to increase cruor yield in the area." },
    [1707] = { name = "EX-06 martello core", description = "This martello core expands the pulse martello's functionality, enabling it to increase the rate of pyxis manifestation in the area." },
    [1708] = { name = "EX-07 martello core", description = "This martello core expands the pulse martello's functionality, enabling it to increase treasure yield in the area." },
    [1709] = { name = "Mog Kupon W-E85", description = "Issued by the Mog House Management Union (MHMU). Tradeable for level 85 empyrean weapons." },
    [1710] = { name = "Mog Kupon A-RJob", description = "Issued by the Mog House Management Union (MHMU). Tradeable for job-specific Dynamis accessories." },
    [1711] = { name = "silver pocket watch", description = "Belonging to a Cardian, this rugged timepiece appears somber for want of the ornamentation that no longer adorns it." },
    [1712] = { name = "elegant gemstone", description = "This tastefully wrought gemstone appears to have once adorned an unknown object." },
    [1713] = { name = "wivre egg", description = "This wivre egg is slightly warm to the touch." },
    [1714] = { name = "wivre egg", description = "This wivre egg radiates forth a toasty warmth." },
    [1715] = { name = "wivre egg", description = "This uncommonly glossy wivre egg permeates with the heady warmth of life impending." },
    [1716] = { name = "torch coal", description = "The burning heart of the Torch, the Divine Goddess who bathes this chill, sunless realm with Her benevolent Warmth and Light. May She ever protect us from the Shadow!" },
    [1717] = { name = "subniveal mines", description = "Compact explosives designed to function optimally when buried in snowdrifts. Blasting power may be regulated by the amount of firesand loaded into their chambers." },
    [1718] = { name = "piece of sodden oak lumber", description = "This log is too waterlogged to be of much use as a building material." },
    [1719] = { name = "sodden linen cloth", description = "This cloth is too waterlogged to be of much use as a building material." },
    [1720] = { name = "dhorme khimaira's mane", description = "A thick, bristly mane cut from a mighty dhorme khimaira." },
    [1721] = { name = "Imperial pearl", description = "A linkpearl sought by Zazarg, that serves as his only means of contact with his comrades back in the Empire." },
    [1722] = { name = "Ronfaure dawndrop", description = "This mysterious dewdrop you found in past Vana'diel is faintly aglow with magic." },
    [1723] = { name = "La Vaule dawndrop", description = "This mysterious dewdrop you found in past Vana'diel is faintly aglow with magic." },
    [1724] = { name = "Jugner dawndrop", description = "This mysterious dewdrop you found in past Vana'diel is faintly aglow with magic." },
    [1725] = { name = "Beaucedine dawndrop", description = "This mysterious dewdrop you found in past Vana'diel is faintly aglow with magic." },
    [1726] = { name = "Xarcabard dawndrop", description = "This mysterious dewdrop you found in past Vana'diel is faintly aglow with magic." },
    [1727] = { name = "Throne Room dawndrop", description = "This mysterious dewdrop you found in past Vana'diel is faintly aglow with magic." },
    [1728] = { name = "Walk of Echoes dawndrop", description = "This mysterious dewdrop you found at the crossroads of reality and time is faintly aglow with magic." },
    [1729] = { name = "San d'Oria dawndrop", description = "This mysterious dewdrop you found in past Vana'diel is faintly aglow with magic." },
    [1730] = { name = "bottled punch bug", description = "Tightly sealed inside a bottle to prevent its escape, this bug forms part of Cait Sith's mysterious arsenal of gadgets." },
    [1731] = { name = "primal glow", description = "The dawndrops you gathered have melded together to form this pure glow of primal light." },
    [1732] = { name = "moonshade earring", description = "A memento of your everlasting bond with Lilisette, simply but tastefully wrought in a timeless moon and star motif." },
    [1733] = { name = "pinch of pixie dust", description = "This rare, magic-imbued dust found on the bodies of pixiekind sparkles brilliantly with the colors of the rainbow." },
    [1734] = { name = "wedding invitation", description = "A cordial invitation to witness the joining of Sir Ragelise and Portia in holy matrimony at the Temple of the Goddess in Upper Jeuno." },
    [1735] = { name = "snoll reflector", description = "A soul reflector modified by Guilboire that serves to attract the presence of snolls, as well as accelerate their rate of hypothermal combustion." },
    [1736] = { name = "frosted snoll reflector", description = "This snoll reflector is covered in frost as a result of close-range hypothermal combustion. Guilboire will be eager to analyze this data." },
