    [2032] = { name = "Anima Synthesis", description = "This forbidden type of alchemy is used to drain elemental energy from remnants of lost memories, and transform it into a partially materialized \"quasispirit\" known as anima." },
    [2033] = { name = "Alchemic Purification", description = "This special alchemy ability allows you to enchant catalysts with the power of white magic." },
    [2034] = { name = "Alchemic Ensorcellment", description = "This special alchemy ability allows you to enchant catalysts with the power of black magic." },
    [2035] = { name = "Trituration", description = "This special alchemy ability allows you to place ingredients in a triturator, making it easier to process more medicines with one crystal." },
    [2036] = { name = "Concoction", description = "This special alchemy ability allows you to concentrate ingredients to create medicines in the form of a solid drop. These drops have the same effect as their liquid equivalents." },
    [2037] = { name = "Iatrochemistry", description = "This special alchemy ability allows you to augment an automaton using the techniques of chemical medicine." },
    [2038] = { name = "miasmal counteragent recipe", description = "The alchemist Harith's recipe for a counteragent to clear up the miasmas in Attohwa Chasm. It reads: Water crystal, one seashell, one onz of salinator, two vials of distilled water." },
    [2039] = { name = "Way of the Alchemist", description = "A deceptively slim volume containing a staggering wealth of knowledge for the expert alchemist. You are particularly struck by a chapter entitled \"Talk Like an Alchemist: How to Sound Positively Profound.\"" },
    [2040] = { name = "Raw Fish Handling", description = "This special cooking ability allows you to prepare raw fish while maintaining your ingredients' freshness." },
    [2041] = { name = "Noodle Kneading", description = "This special cooking ability allows you to prepare flour and water into tasty pasta." },
    [2042] = { name = "Patissier", description = "This special cooking ability allows you to prepare tasty sweets and cakes." },
    [2043] = { name = "Stewpot Mastery", description = "This special cooking ability allows you to prepare hearty stews." },
    [2044] = { name = "Way of the Culinarian", description = "A deceptively slim volume containing a staggering wealth of knowledge for the the expert chef. You are particularly struck by a chapter entitled \"The Svelte Chef: How to Enjoy Your Own Creations Without Putting On the Ponzes!\"" },
