    [2048] = { name = "Voidwatch alarum", description = "A missive bearing the Jeunoan seal. It reads, \\\"In the name of the Grand Duke, you are hereby summoned to arms for the Voidwatch operation. Report with all haste to the Palace for further briefing.\\\"" },
    [2049] = { name = "Voidwatcher''s emblem: Jeuno", description = "An unadorned bronze badge signifying that the wearer is authorized to participate in Voidwatch operations conducted in the Jeuno region." },
    [2050] = { name = "Voidwatcher''s emblem: Qufim", description = "An unadorned bronze badge signifying that the wearer is authorized to participate in Voidwatch operations conducted in the Qufim region." },
    [2051] = { name = "loadstone", description = "Striking this enigmatic stone causes it to grow heavy for a brief period of time. The process behind its creation is a Goblin trade secret and shall never be revealed to outsiders." },
    [2052] = { name = "soul gem", description = "What started as an unknown mass expelled from your body by means of a cryptic Far Eastern ritual is now a brilliant, shimmering gemstone. Life energy flows and pulsates from within." },
    [2053] = { name = "soul gem clasp", description = "An unadorned clasp said to have the power to release the energies harbored within a soul gem." },
    [2054] = { name = "tricolor Voidwatcher's emblem", description = "Stripes of crimson, blue, and green on this simple yet stately badge signify that its wearer is authorized to participate in Voidwatch operations in the greater three nations region." },
    [2055] = { name = "starlight Voidwatcher's emblem", description = "A single ruby star is set in this silver badge, authorizing its bearer to participate in the Voidwatch effort at Vunkerl Inlet, Grauberg, and Fort Karugo-Narugo." },
    [2056] = { name = "red present", description = "Wrapped in exquisite yet simple red wrapping paper, this Starlight Celebration gift is sure to help warm the cockles of anyone's heart." },
    [2057] = { name = "blue present", description = "Wrapped in exquisite yet simple blue wrapping paper, this Starlight Celebration gift is sure to calm even the most conflicted of souls." },
    [2058] = { name = "green present", description = "Wrapped in exquisite yet simple green wrapping paper, this Starlight Celebration gift is sure to refresh even the weariest of travelers." },
    [2059] = { name = "heart of the bushin", description = "Through Atori-Tutori's tutelage, the memories of great warriors past have been burned deep into your body and soul..." },
    [2060] = { name = "hyacinth stratum abyssite", description = "A violet-blue geode shaped like a six-pointed star, carried by all who seek to participate in Voidwatch operations at planar rifts. Its exact properties far beyond layman comprehension, it is said to feed off the energies of slain Voidwalkers to take on heightened powers..." },
    [2061] = { name = "hyacinth stratum abyssite II", description = "A violet-blue geode shaped like a six-pointed star, carried by all who seek to participate in Voidwatch operations at planar rifts. Its exact properties far beyond layman comprehension, it is said to feed off the energies of slain Voidwalkers to take on heightened powers..." },
    [2062] = { name = "amber stratum abyssite", description = "A brownish-yellow geode shaped like a six-pointed star, carried by all who seek to participate in Voidwatch operations at planar rifts. Its exact properties far beyond layman comprehension, it is said to feed off the energies of slain Voidwalkers to take on heightened powers..." },
    [2063] = { name = "amber stratum abyssite II", description = "A brownish-yellow geode shaped like a six-pointed star, carried by all who seek to participate in Voidwatch operations at planar rifts. Its exact properties far beyond layman comprehension, it is said to feed off the energies of slain Voidwalkers to take on heightened powers..." },
    [2064] = { name = "clairvoy ant", description = "This unique insect has been bred by the caits for the sole purpose of projecting images of its surroundings back to them." },
    [2065] = { name = "Kupofried's corundum", description = "This crystalline concoction, fashioned from voidstones by the clever Kupofried, seems to resonate with a strange entity that resides beyond the distortion within the Walk of Echoes." },
    [2066] = { name = "Kupofried's corundum", description = "This crystalline concoction, fashioned from voidstones by the clever Kupofried, seems to resonate with a strange entity that resides beyond the distortion within the Walk of Echoes." },
    [2067] = { name = "Kupofried's corundum", description = "This crystalline concoction, fashioned from voidstones by the clever Kupofried, seems to resonate with a strange entity that resides beyond the distortion within the Walk of Echoes." },
    [2068] = { name = "bronze astrarium", description = "Though its gears and pinions have long since come to rest, this clockwork calendar apparatus recovered from the Nyzul Isle ruins remains a fascinating window into a long-lost civilization." },
    [2069] = { name = "silver astrarium", description = "Though its gears and pinions have long since come to rest, this clockwork calendar apparatus recovered from the Nyzul Isle ruins remains a fascinating window into a long-lost civilization." },
    [2070] = { name = "mythril astrarium", description = "Though its gears and pinions have long since come to rest, this clockwork calendar apparatus recovered from the Nyzul Isle ruins remains a fascinating window into a long-lost civilization." },
    [2071] = { name = "gold astrarium", description = "Though its gears and pinions have long since come to rest, this clockwork calendar apparatus recovered from the Nyzul Isle ruins remains a fascinating window into a long-lost civilization." },
    [2072] = { name = "platinum astrarium", description = "Though its gears and pinions have long since come to rest, this clockwork calendar apparatus recovered from the Nyzul Isle ruins remains a fascinating window into a long-lost civilization." },
    [2073] = { name = "\"Demons in the Rye\" chronicle", description = "This brittle parchment contains the last remaining record of some of the first battles that took place between adventurers and the ferocious beasts of Rolanberry Fields." },
    [2074] = { name = "\"Monstrous Mayhem\" report", description = "This dossier recounts the harrowing events surrounding the appearance and subsequent slaying of certain enormous monsters that assaulted the three nations." },
    [2075] = { name = "\"Culling Is Caring\" poster", description = "Once hung far and wide throughout the three nations and Jeuno, this poster exhorted every citizen in the realm to do their part in quelling the beastman menace." },
    [2076] = { name = "\"Merry Moogle Memorial\" guide", description = "The hastily assembled sentences scrawled haphazardly throughout this itinerary served only to further confuse any moogle not used to touring with others." },
    [2077] = { name = "Connor's Communique", description = "Addressed to someone by the name of Shirba-Girba in ink that has faded over the generations, the passages in this correspondence that remain legible seem to touch upon a linkshell heirloom left behind by the writer's father." },
    [2078] = { name = "\"Pernicious Presents\" brief", description = "This brittle parchment contains the last remaining record of some of the first battles that took place between adventurers and the terrible treants." },
    [2079] = { name = "Little Goblin's Adventure Vol.1", description = "The whimsical prose of this first volume of travel diaries could only have been written by that cheeky Gobbie who calls himself Fab." },
