    [2131] = { name = "handcrafted spatula", description = "At the behest of the MHMU, the Carpenters' Guild crafted a limited quantity of these wooden wonders and branded their handles with the guild's seal of quality." },
    [2132] = { name = "transmuted candle", description = "At the behest of the MHMU, the Alchemists' Guild crafted a limited quantity of these wax wonders via some mysterious and clandestine process." },
    [2133] = { name = "gourmet whipped cream", description = "At the behest of the MHMU, the Culinarians' Guild whipped up a limited quantity of these creamy curiosities by employing some mysterious and clandestine recipe." },
    [2134] = { name = "ancient papyrus shred", description = "A shred of papyrus describing forgotten magic. It appears to be torn mid-sentence." },
    [2135] = { name = "ancient papyrus shred", description = "A shred of papyrus describing forgotten magic. It appears to be torn mid-sentence." },
    [2136] = { name = "ancient papyrus shred", description = "A shred of papyrus describing forgotten magic. It appears to be torn mid-sentence." },
    [2137] = { name = "exoray mold crumb", description = "A speck of sticky material that forms the majority of the exoray's body, too meager in quantity to be of any use." },
    [2138] = { name = "exoray mold crumb", description = "A speck of sticky material that forms the majority of the exoray's body, too meager in quantity to be of any use." },
    [2139] = { name = "exoray mold crumb", description = "A speck of sticky material that forms the majority of the exoray's body, too meager in quantity to be of any use." },
    [2140] = { name = "bomb coal fragment", description = "A carbonized chunk of an explosure, too meager in quantity to be of any use." },
    [2141] = { name = "bomb coal fragment", description = "A carbonized chunk of an explosure, too meager in quantity to be of any use." },
    [2142] = { name = "bomb coal fragment", description = "A carbonized chunk of an explosure, too meager in quantity to be of any use." },
    [2143] = { name = "shining fragment", description = "A whitish fragment of indeterminate matter that appears to have been forcefully chipped off some larger object. It exudes a faint glow." },
    [2144] = { name = "glossy fragment", description = "A blackish fragment of indeterminate matter that appears to have been forcefully chipped off some larger object. It exudes a faint glow." },
    [2145] = { name = "grimoire page", description = "A piece of parchment that temporarily records your journeys in Meeble Burrows." },
    [2146] = { name = "Moblin pheromone sack", description = "A tiny sack containing a substance said to exude Moblin virility. A quick dab on the ears should fool the Meebles into letting you into the caves." },
    [2147] = { name = "golden wing", description = "Proof that you had what it takes to beat the Adjunct course in Sauromugue Champaign." },
    [2148] = { name = "moss-covered shard", description = "A trinket only those conquering the Assistant course in Sauromugue Champaign possess." },
    [2149] = { name = "essence of perfervidity", description = "Essence contained in a glass bottle. Let none doubt your prowess, Instructor!" },
    [2150] = { name = "branded wing", description = "Seared into the feathery texture of this wing are the memories of your success on the Associate Researcher course in Sauromugue Champaign." },
    [2151] = { name = "malicious horn", description = "Only the most dedicated of Researchers can lay claim to the bent igneous horn of the Meeble Burrows' most dread beast in Sauromugue Champaign!" },
    [2152] = { name = "sheet of San d'Orian tunes", description = "Sheet music that can be played on an orchestrion. Music List: The Kingdom of San d'Oria Chateau d'Oraguille Ronfaure" },
    [2153] = { name = "sheet of Bastokan tunes", description = "Sheet music that can be played on an orchestrion. Music List: The Republic of Bastok Metalworks Gustaberg" },
    [2154] = { name = "sheet of Windurstian tunes", description = "Sheet music that can be played on an orchestrion. Music List: The Federation of Windurst Heavens Tower Sarutabaruta" },
    [2155] = { name = "geomagnetron", description = "The specially charged stone has the ability to store the kinetic units necessary for waypoint travel." },
    [2156] = { name = "Adoulinian charter permit", description = "The bearer of this document is officially certified for travel to Adoulin to participate in the Adoulinian colonization initiative. While in Adoulin, the bearer is entitled to all the protections afforded by Adoulin's government. In the event of the bearer's untimely death, Adoulin bears the responsibility of notifying next of kin." },
    [2157] = { name = "Pioneer's Badge", description = "Emblazoned with the Sacred City of Adoulin's insignia, this tightly woven pin proclaims to all who gaze upon it that its wearer is a pioneer." },
    [2158] = { name = "temporary geomagnetron", description = "Given to expectant pioneers, this smooth, ash-colored stone has the ability to record energies from founts of power and to store the kinetic units necessary for warping." },
    [2159] = { name = "aged Matriarch Naakual crest", description = "An emblem wrested from Colkhab, one of the seven ferocious creatures that protect the wilds of Ulbuka. It has certainly seen better days, as the design that was once carved into it has been worn away over the years." },
    [2160] = { name = "aged Riptide Naakual crest", description = "An emblem wrested from Tchakka, one of the seven ferocious creatures that protect the wilds of Ulbuka. It has certainly seen better days, as the design that was once carved into it has been worn away over the years." },
    [2161] = { name = "aged Firebrand Naakual crest", description = "An emblem wrested from Achuka, one of the seven ferocious creatures that protect the wilds of Ulbuka. It has certainly seen better days, as the design that was once carved into it has been worn away over the years." },
    [2162] = { name = "aged Ligneous Naakual crest", description = "An emblem wrested from Yumcax, one of the seven ferocious creatures that protect the wilds of Ulbuka. It has certainly seen better days, as the design that was once carved into it has been worn away over the years." },
    [2163] = { name = "aged Booming Naakual crest", description = "An emblem wrested from Hurkan, one of the seven ferocious creatures that protect the wilds of Ulbuka. It has certainly seen better days, as the design that was once carved into it has been worn away over the years." },
    [2164] = { name = "aged Flashfrost Naakual crest", description = "An emblem wrested from Kumhau, one of the seven ferocious creatures that protect the wilds of Ulbuka. It has certainly seen better days, as the design that was once carved into it has been worn away over the years." },
    [2165] = { name = "aged Undying Naakual crest", description = "An emblem wrested from Teodor, the Undying Naakual and former Deathborne Xol. It certainly has seen better days, as the design that was once carved into it has been worn away over the years." },
    [2166] = { name = "prototype attuner", description = "A crystal that stores kinetic units and allows the recording of geomagnetic founts. Due to its nature as a prototype, its appearance is rather unrefined." },
    [2167] = { name = "watercraft", description = "This boat enabling passage across the treacherous Zoldeff River can be folded in upon itself as if by magic." },
    [2171] = { name = "restrainment resilience", description = "A survival skill that grants the fortitude to overcome the amnesiac effects of spinescent protuberances found throughout Eastern Ulbuka." },
    [2179] = { name = "cupful of dust-laden sap", description = "This amber sap contains trace amounts of dust left behind by feeding twitherym." },
    [2180] = { name = "mantid bait", description = "Twitching slightly, this chapuli is just alive enough to serve as suitable mantid bait." },
    [2185] = { name = "vial of toxic Zoldeff water", description = "Water isn't supposed to be purple... but in the Zoldeff River, it sure is!" },
    [2186] = { name = "fistful of pristine sand", description = "Some otherworldly energies have prevented this sand from succumbing to the corruption of the Zoldeff River." },
    [2190] = { name = "rime ice fragment", description = "This rime ice, found in Morimar Basalt Fields, lacks any kind of beauty or luster." },
    [2192] = { name = "broken harpoon", description = "A harpoon that shows many signs of wear, the most prevalent being the head that snapped completely in half. Luckily, the Inventors' Coalition should be able to make this spear right as rain." },
    [2193] = { name = "extravagant harpoon", description = "Not only can this harpoon spear fish, but thanks to the Inventors' Coalition, it can also expand and retract as well as move its head rhythmically in time with the waves." },
    [2196] = { name = "geomagnetic compass", description = "A device created by Anastase to assist in the discovery of geomagnetic founts." },
    [2197] = { name = "ocular orb", description = "A penumbral mist swirls within this eye, proving your deeds in the Adjunct Course in Batallia Downs." },
    [2198] = { name = "pile of noxious grime", description = "A putrid substance that marks your success in the Assistant Course in Batallia Downs." },
    [2199] = { name = "pulsating shard", description = "A symbol filled with hidden magic that displays your prowess in the Instructor Course in Batallia Downs." },
    [2200] = { name = "dinner invitation", description = "A cordial entreaty to join the leaders of the Twelve Orders for dinner at Castle Adoulin once their assembly has adjourned." },
    [2201] = { name = "rockberry", description = "A berry delicious treat for raptors. Hard as rock and solid as stone, rockberries can only be eaten by animals with jaws of iron." },
    [2202] = { name = "rockberry", description = "A berry delicious treat for raptors. Hard as rock and solid as stone, rockberries can only be eaten by animals with jaws of iron." },
    [2203] = { name = "rockberry", description = "A berry delicious treat for raptors. Hard as rock and solid as stone, rockberries can only be eaten by animals with jaws of iron." },
    [2204] = { name = "\"Logging\"", description = "A survival skill that helps adventurers clear the twisted trees that impede the progress of colonization in Eastern Ulbuka." },
    [2205] = { name = "\"Watercrafting\"", description = "A survival skill that grants the capacity to use portable boats to cross treacherous waters in Eastern Ulbuka." },
    [2206] = { name = "\"Demolishing\"", description = "A survival skill that grants the ability to crush walls and boulders of hardened magma that prevent further passage in Eastern Ulbuka." },
    [2207] = { name = "toxin resilience", description = "A survival skill that grants the fortitude to withstand the otherwise overpowering poisons of pungent fungi located in Eastern Ulbuka." },
    [2208] = { name = "paresis resilience", description = "A survival skill that grants the strength to counteract the debilitating effects of numbing blossoms found throughout Eastern Ulbuka." },
    [2209] = { name = "calor resilience", description = "A survival skill that grants the hardihood to overcome the burning effects of steam spouts throughout Eastern Ulbuka." },
    [2210] = { name = "Hen. FS building mat. container", description = "A collection of materials to assist in the construction of a frontier station in Foret de Hennetiel." },
    [2211] = { name = "Mor. FS building mat. container", description = "A collection of materials to assist in the construction of a frontier station in the Morimar Basalt Fields." },
    [2212] = { name = "Hen. FS resource container", description = "A collection of materials from Foret de Hennetiel that are bound for the Couriers' Coalition." },
    [2213] = { name = "Mor. FS resource container", description = "A collection of materials from Morimar Basalt Fields that are bound for the Couriers' Coalition." },
    [2214] = { name = "Cei. FB op. materials container", description = "A collection of materials that must be delivered to a frontier bivouac in the Ceizak Battlegrounds." },
    [2215] = { name = "Hen. FB op. materials container", description = "A collection of materials that must be delivered to a frontier bivouac in Foret de Hennetiel." },
    [2216] = { name = "Mor. FB op. materials container", description = "A collection of materials that must be delivered to a frontier bivouac in the Morimar Basalt Fields." },
    [2217] = { name = "lost article", description = "Left behind by a careless pioneer, this article should be delivered to the Mummers' Coalition with utmost haste." },
    [2218] = { name = "lost article", description = "Left behind by a careless pioneer, this article should be delivered to the Mummers' Coalition with utmost haste." },
    [2219] = { name = "lost article", description = "Left behind by a careless pioneer, this article should be delivered to the Mummers' Coalition with utmost haste." },
    [2220] = { name = "flayed mantid corpse", description = "Battered nearly beyond recognition, this mantid had been the scourge of the Ceizak Battlegrounds." },
    [2221] = { name = "chapuli horn", description = "This horn, white as ivory, signifies your victory over the flora-destroying chapuli." },
    [2225] = { name = "hot spring report #1", description = "This report documents a hot spring in Morimar Basalt Fields." },
    [2226] = { name = "hot spring report #2", description = "This report documents a hot spring in Morimar Basalt Fields." },
    [2227] = { name = "hot spring report #3", description = "This report documents a hot spring in Morimar Basalt Fields." },
    [2228] = { name = "hot spring report #4", description = "This report documents a hot spring in Morimar Basalt Fields." },
    [2229] = { name = "hot spring report #5", description = "This report documents a hot spring in Morimar Basalt Fields." },
    [2232] = { name = "magma survey report", description = "This report, scribbled on fresh parchment, contains details of the colors, viscosity, and latent energy of the magma in Moh Gates." },
    [2234] = { name = "reive unity", description = "It is only when pioneers band together that they are at their strongest. Fighting jointly with others in any reive will initiate a surge of power within you." },
    [2236] = { name = "\"Critical Chop\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique enables the occasional procurement of higher quality resources." },
    [2237] = { name = "\"Cherished Axe\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique occasionally prevents the bearer's tools from breaking." },
    [2238] = { name = "\"Critical Smash\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique enables the occasional procurement of higher quality resources." },
    [2239] = { name = "\"Cherished Pick\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique occasionally prevents the bearer's tools from breaking." },
    [2240] = { name = "\"Critical Slice\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique enables the occasional procurement of higher quality resources." },
    [2241] = { name = "\"Cherished Sickle\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique prevents the bearer's tools from breaking." },
    [2242] = { name = "\"Redoubled Chop\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique occasionally enables the user to procure two materials with one stroke." },
    [2243] = { name = "\"Conservative Chop\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique occasionally preserves stamina." },
    [2244] = { name = "\"Redoubled Smash\"", description = "Developed by the Pioneers' Coalition to aid in gathering, this technique occasionally enables the user to procure two materials with one stroke." },
