    [2256] = { name = "Tavnazia warp rune", description = "Engraved with runic energies that permit limited waypoint-based warping, this stone grants access to Tavnazia." },
    [2257] = { name = "Whitegate warp rune", description = "Engraved with runic energies that permit limited waypoint-based warping, this stone grants access to Aht Urhgan Whitegate." },
    [2258] = { name = "Nashmau warp rune", description = "Engraved with runic energies that permit limited waypoint-based warping, this stone grants access to Nashmau." },
    [2261] = { name = "rusted pickaxe", description = "Fished up from foul water, this pickaxe is covered with rust from its pointed edge all the way down its shaft." },
    [2262] = { name = "tiny seed", description = "A tiny seed Kyff found during his adventures in the forests of Ulbuka." },
    [2263] = { name = "bottle of fertilizer X", description = "A bottle of highly potent fertilizer designed by the Inventors' Coalition for use in growing vegetables and plants in the Civic Arboretum." },
    [2264] = { name = "waypoint scanner kit", description = "This kit emits copious amounts of steam and its gears are grinding noisily. Could it really be used to examine potential issues with the waypoints?" },
    [2265] = { name = "royal fiat banning colonization", description = "An official missive from the king to his ministers, stating: \"Henceforth, participation in colonization-related activities is prohibited. We decree that the city shall refocus its resources on mercantile pursuits, the execution of which shall be entrusted to the leaders of the Twelve Orders.\"" },
    [2266] = { name = "record of the 17th Assembly", description = "Outlined in these minutes is the abolition of royal sovereignty and the establishment of a legislative body. They also record a proposal to increase the nation's authority abroad by enhancing its naval resources." },
    [2267] = { name = "copy of the alliance agreement", description = "Ratified by all leaders of the Twelve Orders, this document testifies to the formation of the Sacred City of Adoulin Alliance and its current political body." },
    [2268] = { name = "Ulbukan navigation chart", description = "Weathered by years of exposure to sea salt winds, this parchment is covered with faint lines delineating the myriad currents and trade routes in the vicinity of the Eastern Ulbuka archipelago, along with barely legible letters spelling \"Tavnazia.\"" },
    [2269] = { name = "copy of \"Adoulin's Patroness\"", description = "\"Oh, Mistress Svenja! Thy soft embrace doth rid pioneers of their sorrows, and thy smile the sun's impetus to rise every morrow. I cannot express how much I love thee, Mistress Svenja, except to say you set me free.\"" },
    [2270] = { name = "memo from Midras", description = "This parchment inked in hastily scribbled script contains the name of a chemical substance that Midras needs to procure from his father, Cid." },
    [2271] = { name = "Cid's catalyst", description = "This finely-ground yellow powder smells of fetid ash. Midras requires it to create an explosive substance." },
    [2272] = { name = "chunk of milky white minerals", description = "This fist-sized rock mined in Sih Gates contains a variety of substances said to aid in the creation of more efficient, potent vegetable fertilizer." },
    [2273] = { name = "F.A.I.L. badge", description = "A flimsy pin with childish scribblings on it that announce the bearer's affiliation with the Fantastic Adoulin Imperial Liberators." },
    [2274] = { name = "Western Adoulin patrol route", description = "\"Pioneers' Coalition Ò Couriers' Coalition Ò Adoulin Waterfront Ò Platea Triumphus Ò Inventors' Coalition Ò Wharf with ships bound for Adoulin's residential district Ò Mummers' Coalition Ò Report back.\"" },
    [2275] = { name = "misdelivered parcel", description = "Originally destined for C-6 in the Rala Waterways, the Couriers' Coalition accidentally sent this package to the Adoulin Waterfront. It looks to have been struck with a sword numerous times and is covered in strange symbols." },
    [2276] = { name = "Eastern Adoulin patrol route", description = "\"Peacekeepers' Coalition Ò Wharf to Yahse Hunting Grounds Ò Statue of the Goddess Ò Minister of education's residence Ò Adoulin Castle Ò Docks to Adoulin's residential area Ò Scouts' Coalition Ò Report back.\"" },
    [2277] = { name = "hot springs care package", description = "What better way to lure in an old man visiting the hot springs in Morimar Basalt Fields than with some boiled eggs and fruit-flavored milk?" },
    [2278] = { name = "fistful of homeland soil", description = "The smell of this light brown soil reminds you of your pre-adventuring youth. Perhaps Sylvie can use this to construct your luopan." },
    [2279] = { name = "Yahse wildflower petal", description = "Picked from a flower that only grows along the shore of the Yahse Hunting Grounds, petals such as this are rumored to be the main ingredient in a distinctive occult ink." },
    [2280] = { name = "habitual behavior barometer", description = "A handheld device based on the spatial pressure barometer developed in the Near East and modified by the Armathrwn Society, you need only keep it in your possession to collect all the necessary data from Naakual dwellings." },
    [2281] = { name = "brier-proof net", description = "Composed of strong metallic links, this net may weigh one down a tad, but it also provides unrivaled protection against limb-severing groves of thorny plants." },
    [2282] = { name = "compass of transference", description = "Based on the technology employed in airship propulsion, this mechanism transports its bearer to the epicenter of an extremely murky energy distortion." },
    [2283] = { name = "magma mitigation set", description = "Specially crafted from heat-resistant materials, this set of boots and gloves will prevent pioneers with even the most delicate skin from suffering a single burn while climbing the searing heat of mafic cliffs." },
    [2284] = { name = "resurrection retardant axe", description = "Coated with a solution that impedes the regrowth of any trees with which it comes into contact, this battle-axe allows its bearer passage through even the most impenetrable of Eastern Ulbukan thickets. Its blades degrade quickly once coated, however, and cannot be used more than once." },
    [2285] = { name = "insulator tablet", description = "Once consumed, this bitter medicine vastly limits the body's ability to conduct electricity. While it begins working nearly instantaneously, its effects don't last much longer. Due to a horde of dangerous side effects, surveyors highly caution against using it in quick succession." },
    [2286] = { name = "anti-glaciation gear", description = "This set of climbing gear consists of a finely woven coat and a trusty ice pick. The coat's sorcery-imbued fibers perform the dual function of increasing the amount of heat emitted from one's frame and trapping it. The pick is coated with a special substance that bonds to whatever it comes in contact with, ensuring pioneers do not get blown away." },
    [2288] = { name = "Land of Milk and Honey hive", description = "True to its name, this beehive collects divine honey and nectar. One of the Inventors' Coalition's secret weapons, it has the strange power to attract bees and wasps of all shapes and sizes." },
    [2289] = { name = "full Land of Milk and Honey hive", description = "This beehive is almost completely full, with ten bees stored inside." },
    [2290] = { name = "luopan", description = "This tiny object serves as a pylon of geomantic energies. No true geomancer would be caught dead without one." },
    [2291] = { name = "Rala simulacrum", description = "A statue assembled from three different segments that grants its bearer access to skirmishes in Rala Waterways [U]." },
    [2292] = { name = "Yorcia simulacrum", description = "A statue assembled from three different segments that grants its bearer access to skirmishes in Yorcia Weald [U]." },
    [2293] = { name = "Cirdas simulacrum", description = "A statue assembled from three different segments that grants its bearer access to skirmishes in Cirdas Caverns [U]." },
    [2294] = { name = "Ra'Kaznar simulacrum", description = "A statue assembled from three different segments that grants its bearer access to skirmishes in Ra'Kaznar [U]." },
    [2296] = { name = "celadon yantric planchette", description = "This board is made of finely polished celadon yggrete and is attuned to lift the veil shrouding a fracture in Ceizak Battlegrounds." },
    [2297] = { name = "zaffre yantric planchette", description = "This board is made of finely polished zaffre yggrete and is attuned to lift the veil shrouding a fracture in Foret de Hennetiel." },
    [2298] = { name = "alizarin yantric planchette", description = "This board is made of finely polished alizarin yggrete and is attuned to lift the veil shrouding a fracture in Morimar Basalt Fields." },
    [2299] = { name = "detached stinger", description = "Ripped from the abdomen of the vicious Muyingwa, this stinger drips with a venom so acidic that it instantaneously sears any flesh with which it comes in contact." },
    [2300] = { name = "craggy fin", description = "Torn from the back of the foul Dakuwaqa, this deep grey appendage cuts with such precision that it causes eddies to form in the flesh it slices through." },
    [2301] = { name = "flame-scarred skull", description = "Severed from the lifeless body of the nefarious Tojil, this skull contains black patches that mark the dancing of unholy flames." },
    [2302] = { name = "map of Rala Waterways [U]", description = "A map of Rala Waterways [U]. Displays your party members' current location." },
    [2303] = { name = "map of Yorcia Weald [U]", description = "A map of Yorcia Weald [U]. Displays your party members' current location." },
    [2304] = { name = "map of Cirdas Caverns [U]", description = "A map of Cirdas Caverns [U]. Displays your party members' current location." },
    [2305] = { name = "map of Outer Ra'Kaznar [U]", description = "A map of Outer Ra'Kaznar [U]. Displays your party members' current location." },
    [2307] = { name = "map of Escha - Zi'Tah", description = "A map of Escha - Zi'Tah. Displays your party members' current location." },
    [2308] = { name = "map of Escha - Ru'Aun", description = "A map of Escha - Ru'Aun. Displays your party members' current location." },
    [2309] = { name = "map of Reisenjima", description = "A map of Reisenjima. Displays your party members' current location." },
    [2334] = { name = "Mog Kupon A-DeII", description = "Issued by the Mog House Management Union (MHMU). Tradeable for spoils from bosses in Delve." },
    [2335] = { name = "Mog Kupon A-De", description = "Issued by the Mog House Management Union (MHMU). Tradeable for spoils from notorious monsters in Delve." },
    [2336] = { name = "Mog Kupon A-Sal", description = "Issued by the Mog House Management Union (MHMU). Tradeable for Salvge +1 armor." },
    [2337] = { name = "Mog Kupon A-Nyz", description = "Issued by the Mog House Management Union (MHMU). Tradeable for armor from Nyzul Isle Uncharted Survey." },
    [2338] = { name = "Mog Kupon I-S5", description = "Issued by the Mog House Management Union (MHMU). Tradeable for rank V simulacra segments." },
    [2339] = { name = "Mog Kupon I-S2", description = "Issued by the Mog House Management Union (MHMU). Tradeable for rank II simulacra segments." },
    [2340] = { name = "Mog Kupon I-Orche", description = "Issued by the Mog House Management Union (MHMU). Tradeable for orchestrion sheet music." },
    [2341] = { name = "sheet of E. Adoulinian tunes", description = "Sheet music that can be played on an orchestrion. Music List: The Sacred City of Adoulin" },
    [2342] = { name = "sheet of W. Adoulinian tunes", description = "Sheet music that can be played on an orchestrion. Music List: The Pioneers" },
    [2343] = { name = "Hennebloom leaf", description = "This bumpy leaf was torn off a small cobalt flower growing in the farthest reaches of Foret de Hennetiel." },
    [2344] = { name = "impure celadon yggzi", description = "A petrified celadon yggzi bead of questionable quality." },
    [2345] = { name = "semi-pure celadon yggzi", description = "A semi-pure petrified celadon yggzi bead with large variances in shape." },
    [2346] = { name = "impure zaffre yggzi", description = "A petrified zaffre yggzi bead of questionable quality." },
    [2347] = { name = "semi-pure zaffre yggzi", description = "A semi-pure petrified zaffre yggzi bead with large variances in shape." },
    [2348] = { name = "impure alizarin yggzi", description = "A petrified alizarin yggzi bead of questionable quality." },
    [2349] = { name = "semi-pure alizarin yggzi", description = "A semi-pure petrified alizarin yggzi bead with large variances in shape." },
    [2350] = { name = "ring of supernal disjunction", description = "A simply crafted ring of gold that separates spirit from body and enables its bearer to possess bestial vessels." },
    [2351] = { name = "gladiatorial writ of summons", description = "A surreal document with letters that seem to hover above the parchment upon which they were written, this testimonial serves as evidence that its bearer is a gladiator and thus permitted to combat monipulators." },
    [2352] = { name = "\"Ephemeral Endeavor\"", description = "This rune--engraved by Octavien-- signifies that its bearer has spread their wings and soared to new heights as a rune fencer." },
    [2353] = { name = "\"Enlightened Endeavor\"", description = "Bestowed upon rune fencers endeavoring to ascend to greater heights, the character itself continuously exudes an occult aura around its bearer." },
    [2354] = { name = "rune saber", description = "A blade so thin that it cannot be used in combat. It responds to all runic elements and glows a pale shade of blue." },
    [2355] = { name = "flask of fruiserum", description = "This liquid can ice over entire rivers of magma in an instant. According to its label, imbibing it can also cause unpleasant side effects such as upset stomach, severe brain freeze, and immediate death." },
    [2356] = { name = "frost-encrusted flame gem", description = "A brilliant jewel that harbors the elemental power of fire, which can be seen raging under a thick layer of frost." },
    [2357] = { name = "letter from Octavien", description = "\"I understand that you may not have time for this due to your myriad scholarly duties, but I beseech you to impart your wisdom regarding the mysterious runic devices to the messenger who handed you this note. Without either this person's help or yours, we will not be able to uncover the meaning behind the contraptions.\"" },
    [2358] = { name = "stone of Ignis", description = "A rune stone left behind by Sverdhried and recovered from an enigmatic contraption in the Eldieme Necropolis." },
    [2359] = { name = "stone of Gelus", description = "A rune stone left behind by Sverdhried and recovered from an enigmatic contraption in Ordelle's Caves." },
    [2360] = { name = "stone of Flabra", description = "A rune stone left behind by Sverdhried and recovered from an enigmatic contraption in the Gusgen Mines." },
    [2361] = { name = "stone of Tellus", description = "A rune stone left behind by Sverdhried and recovered from an enigmatic contraption in the Outer Horutoto Ruins." },
    [2362] = { name = "stone of Sulpor", description = "A rune stone left behind by Sverdhried and recovered from an enigmatic contraption in Crawlers' Nest." },
    [2363] = { name = "stone of Unda", description = "A rune stone left behind by Sverdhried and recovered from an enigmatic contraption in Dangruf Wadi." },
    [2364] = { name = "stone of Lux", description = "A rune stone left behind by Sverdhried and recovered from an enigmatic contraption in the Maze of Shakhrami." },
    [2365] = { name = "stone of Tenebrae", description = "A rune stone left behind by Sverdhried and recovered from an enigmatic contraption in Garlaige Citadel." },
    [2366] = { name = "stone of unknown runic origins", description = "A rune stone recovered from an enigmatic contraption in King Ranperre's Tomb." },
    [2367] = { name = "stone of unknown runic origins", description = "A rune stone recovered from an enigmatic contraption in Ranguemont Pass." },
    [2368] = { name = "stone of unknown runic origins", description = "A rune stone recovered from an enigmatic contraption in Fei'Yin." },
    [2369] = { name = "\"Secrets of Runic Enhancement\"", description = "A slightly smaller tome than most of this genre. A drawing of some ancient equipment adorns its cover, and an elegantly inscribed description on the back claims that this volume contains the most clandestine of techniques for augmenting runic equipment." },
    [2370] = { name = "runic kinegraver", description = "An unassuming cubic device that, when outfitted with a rune and placed to one's forehead, projects moving images for the viewer." },
    [2371] = { name = "vial of vivid rainbow extract", description = "A dye fashioned from Yahse wildflower petals boiled in the waters of a river with the rune Ignis. It is used to color various pieces of highly sought-after equipment and is rumored to act as a talisman as well." },
    [2372] = { name = "Insidio's extinguished lantern", description = "Evidence that the ogre-like orobon named Insidio has been vanquished. This once mesmerizingly bright orb will charm innocent bystanders no longer." },
    [2373] = { name = "vessel of summoning", description = "This tiny container holds a translucent green liquid said to lure in powerful elementals. Geomancers hoping to prove their ability use this as part of their rites of passage." },
    [2374] = { name = "silver luopan", description = "Prepared by Sylvie, this special luopan can calm the rage of the lifestream." },
    [2375] = { name = "Lhaiso Neftereh's bell", description = "This ancient bell, passed down since the time of Sih Renaye, confers the uncanny ability to converse with the higher power." },
    [2376] = { name = "Midras's explosive sample", description = "The explosive device engineered by Midras makes up for its lack of force by employing a chemical reaction to shatter its target." },
    [2377] = { name = "report on Midras's explosive", description = "This report, scribbled hastily on fresh parchment, contains highly technical explanations that are indecipherable by the common man." },
    [2378] = { name = "tray of Adoulinian delicacies", description = "This covered tray contains an exquisite meal of Adoulin's finest sea bounty, fished and prepared by Alienor herself. One person could not possibly consume all of it." },
    [2379] = { name = "small bag of Adoulinian delicacies", description = "This small bag contains some of the food Alienor prepared for her grandfather, Anastase. One of the members of his expedition would surely enjoy this treat." },
    [2380] = { name = "waypoint recalibration kit", description = "This improved version of a waypoint scanner kit is specially fitted to recalibrate waypoints in the Middle Lands." },
    [2381] = { name = "Twelve Orders dossier", description = "A stack of papers new and old received from Reja Ygridhi. Inscribed upon the documents is information pertaining to each of Adoulin's Twelve Orders." },
    [2382] = { name = "ravine water testing kit", description = "Jhen Durheka has prepared this kit to collect and test water samples from the river in Marjami Ravine. It contains three vials and a strange apparatus." },
    [2383] = { name = "fistful of numbing soil", description = "This purplish soil was collected from an area in Yorcia Weald where numbing blossoms flourish. It is unfit for growing plants of any other species." },
    [2384] = { name = "hunk of bedrock", description = "This sedimentary stone excavated from a Mog Garden has a unique pattern carved into its surface." },
    [2385] = { name = "Yorcia's tear", description = "This light, clear gem shimmers like a small droplet of water." },
    [2386] = { name = "blightberry", description = "Named after a disease that plagues crops due to its lumpy green skin that looks as if it has harbored mold for weeks, this succulent fruit has a strikingly red center that drips with decadent juices." },
    [2387] = { name = "large strip of Velkk hide", description = "A large strip of hide cured by the Velkk. Though such hide is generally small and easily torn, this strip is large and tough." },
    [2388] = { name = "\"Climbing\"", description = "A survival skill that grants the ability to climb vines and cliffs that dot the landscape of Eastern Ulbuka." },
    [2389] = { name = "box of Adoulinian tomatoes", description = "Fresh and juicy with bright red skin, these tomatoes were grown in Adoulin's own Civic Arboretum. The seeds, however, were brought back from the jungle by Arciela." },
    [2390] = { name = "kaleidoscopic clam", description = "A shellfish dragged up from the waters off the coast of a Mog Garden. This marine bivalve's carapace glistens with all seven colors of the rainbow, overshadowing its relatively displeasing jaundiced body." },
    [2391] = { name = "glass pendulum", description = "A crystalline device that sways back and forth and was salvaged off the coast of a Mog Garden. Its appearance gives no obvious clues as to its purpose." },
    [2393] = { name = "ivory wing talisman", description = "A charm crafted in the shape of ivory wings, the symbol of the Goddess Altana. Reduces the amount of experience lost when knocked out during reives." },
    [2394] = { name = "bronze mattock cordon", description = "Embroidered with a gleaming bronze mattock, this badge is given only to pioneers who have gone above and beyond the call of duty in advancing the colonization initiative. Increases the maximum number of coalition imprimaturs able to be held at one time." },
    [2395] = { name = "bronze shovel cordon", description = "Embroidered with a gleaming bronze shovel, this badge is given only to pioneers who have gone above and beyond the call of duty in advancing the colonization initiative. Reduces the waiting period for new coalition imprimaturs." },
    [2396] = { name = "Tarutaru Sauce invoice", description = "A collection of invoices addressed to the Mummers' Coalition. Cafe des Larmes: 4,560 gil; Cafeteria: 5,600 gil; Fishmonger's stall: 6,832 gil; Bakery: 19,440 gil; Sweets shop: 3,000 gil." },
    [2397] = { name = "Tarutaru Sauce receipt", description = "A collection of receipts addressed to the Mummers' Coalition. Those two pigs surely worked up quite the tab..." },
    [2398] = { name = "GPS crystal", description = "Its acronym a shorthand form of \"Garden Positioning System\", this mineral device guides pioneers via moogle magic to their Mog Gardens. It glows with the iridescence of an additional star for each day (Earth time) the Green Thumb Moogle lays his fuzzy paws upon it. As to what significance the stars have, that remains a moogle mystery." },
    [2399] = { name = "pair of Velkk gloves", description = "These sturdy green gloves were created from a large Velkk hide. Neither the thorniest vines nor the sheerest of cliffs can stop a pioneer who has them in his possession." },
    [2400] = { name = "lost article", description = "Left behind by a careless pioneer, this article should be delivered to the Mummers' Coalition with utmost haste." },
    [2401] = { name = "lost article", description = "Left behind by a careless pioneer, this article should be delivered to the Mummers' Coalition with utmost haste." },
    [2402] = { name = "geomancer claim ticket", description = "An order slip from Wescolina detailing the armor piece ordered from her shop." },
    [2403] = { name = "Mar. FB op. materials container", description = "A collection of materials that must be delivered to a frontier bivouac in Marjami Ravine." },
    [2404] = { name = "Yor. FB op. materials container", description = "A collection of materials that must be delivered to a frontier bivouac in Yorcia Weald." },
    [2405] = { name = "Mar. FS building mat. container", description = "A collection of materials to assist in the construction of a frontier station in Marjami Ravine." },
    [2406] = { name = "Yor. FS building mat. container", description = "A collection of materials to assist in the construction of a frontier station in Yorcia Weald." },
    [2407] = { name = "proof of order: runic headgear", description = "This barely legible document is scribbled in Jerra Ndala's childish handwriting. It contractually binds her to provide its bearer with a piece of headgear specially made for rune fencers once he pays the requisite amount of bayld. It also reeks of tomatoes." },
    [2408] = { name = "proof of order: runic handgear", description = "This barely legible document is scribbled in Jerra Ndala's childish handwriting. It contractually binds her to provide its bearer with a set of handgear specially made for rune fencers once he pays the requisite amount of bayld. It also reeks of tomatoes." },
    [2409] = { name = "proof of order: runic footgear", description = "This barely legible document is scribbled in Jerra Ndala's childish handwriting. It contractually binds her to provide its bearer with a set of footgear specially made for rune fencers once he pays the requisite amount of bayld. It also reeks of tomatoes." },
    [2410] = { name = "Rosulatia's pome", description = "This mystical fruit, red in color and soft to the touch, was given to you by Rosulatia, the leafkin queen." },
    [2411] = { name = "Celennia Memorial Library card", description = "Displaying twelve freshly sharpened swords glinting from the glow of the Sun behind, this card serves as authorization for viewing the shelves upon shelves of knowledge the Scouts' Coalition has stored within the Celennia Memorial Library." },
    [2412] = { name = "\"SowYourSeed!\"", description = "The story of a few young farmtown women that never actually goes anywhere, but has gained massive popularity for its revolutionary eschewal of traditional narrative techniques. Its tale is so enticing that many pioneers who have read it have laid down their arms for the plow. Increases the rank of the reader's furrows by one." },
    [2413] = { name = "\"My First Furrow\"", description = "A primer to the basics of farming. Its prose is easily understandable even for beginners, and those who finish reading it report having the rank of their furrows increase by one." },
    [2414] = { name = "\"Fields And Fertilizing\"", description = "A step-by-step instructional guide that focuses specifically on the agronomics of Mog Gardens. Plastered with a plethora of pictures as well as the written word, this volume also accommodates intermediate farmers who learn best by seeing rather than reading. Readers report having the rank of their furrows increase by one." },
    [2415] = { name = "\"Designer Farming\"", description = "An advanced manual covering QoS Design-pattering farming--named after the Queen of San d'Oria. It explains the farming method's theoretical framework in-depth and its practical applications. Though not a book for beginners, those able to understand it report having the rank of their furrows increase by one." },
    [2416] = { name = "\"Homesteader''s Compendium\"", description = "This tome was coauthored by Kupalika's own Kupofried and Lytchii, of whom no other records remain. It details numerous local farming tips, yet the lack of background information and its eccentric prose render it accessible only to sophisticated gardeners. Those able to understand it report having the rank of their furrows increase by one." },
    [2417] = { name = "\"MHMU Treatise on Agronomy\"", description = "The official source on Mog Garden furrow development, issued by the Mog House Management Union. While it purportedly takes a critical look at the farming across Vana'diel, no one can decipher the abstruse and florid style of its authors. Nevertheless, flipping through its pages might increase the rank of the reader's furrows by one." },
    [2419] = { name = "\"Give My Regards to Reodoan\"", description = "A tale based off the legend of Reodoan, who secretly worked to save the dying forestry industry. It follows a teenage lumberjack torn between two loves: his forest and his work. Older generations of housewives swoon for the main character, but pioneers who read it report having the rank of their Mog Garden grove increase by one." },
    [2420] = { name = "\"Adoulin''s Topiary Treasures\"", description = "A collection of watercolor paintings detailing the gardens of those belonging to Adoulin's Twelve Orders. Many have gained an interest in pruning and trimming simply from gazing upon these stellar examples of topiary magnificence. Pioneers who read it report having the rank of their Mog Garden grove increase by one." },
    [2421] = { name = "\"Grandiloquent Groves\"", description = "This famous \"How-to\" book is as pertinent to topiary techniques as its title suggests, with the majority of its pages devoted to unrelated topics such as the number of masons it took to build Jorius Yett and the purported thread count of Arciela's undergarments. Still, pioneers who read it report having the rank of their Mog Garden grove increase by one." },
    [2422] = { name = "\"Arboreal Abracadabra\"", description = "Popular phrases used to describe this tome on landscaping include \"ticket to enlightenment\" and \"taking control of your destiny.\" The book's numerous illustrations make it easy to understand for topiary artists, but many see it as an exercise in self-aggrandizement. Pioneers who read it report having the rank of their Mog Garden grove increase by one." },
    [2423] = { name = "\"Verdant and Verdon''ts\"", description = "Written by a vocal anti-colonialist, this thesis asserts that colonization is advancing disproportionately fast compared to tree growth, thus threatening Ulbuka's ecological balance. To cure this problem, its author proposes planting more trees in Mog Gardens. Pioneers who read it report having the rank of their Mog Garden grove increase by one." },
    [2424] = { name = "\"MHMU Treatise on Forestry\"", description = "The official source on Mog Garden groves, issued by the Mog House Management Union. While it purportedly takes a critical look at forestry techniques across Vana'diel, no one can decipher the abstruse and florid style of its authors. Nevertheless, flipping through its pages might increase the rank of the reader's grove by one." },
    [2426] = { name = "\"Mythril Marathon Quarterly\"", description = "A magazine that features articles by famous Bastokers. It outlines a unique type of race in which guest participants must carry back mythril ore from the Palborough Mines, but the concept remains wildly unpopular outside of its native home of Bastok. Pioneers who read it report having the rank of their Mog Garden mineral vein increase by one." },
    [2427] = { name = "\"Take A Lode Off\"", description = "Covering a plethora of topics from mental preparation to what fashions are raging, this handbook for new miners is oft denigrated for catering to capricious twits who spurn mining's serious side to flirt with adventurers of the opposite sex. Still, pioneers who read it report having the rank of their Mog Garden mineral vein increase by one." },
    [2428] = { name = "\"Varicose Mineral Veins\"", description = "Written by the goldsmith Fatimah, this book is populated with diagrams and illustrations explaining how to find the biggest veins possible. Short stories accompany the descriptions of rare and valuable gems, making the tome ideal for beginners. Pioneers who read it report having the rank of their Mog Garden mineral vein increase by one." },
    [2429] = { name = "\"Tales from the Tunnel\"", description = "Though many of the stories in this collection are surreal--featuring protagonists such as gems and hunks of ore--those who understand the basics of mineralogy appreciate the underlying themes sprinkled throughout each fable. Pioneers who read it report having the rank of their Mog Garden mineral vein increase by one." },
    [2430] = { name = "\"The Gusgen Mines Tragedy\"", description = "This book takes a look at how the terrible incident that occurred in the Gusgen Mines could have been prevented from a technological standpoint. The meticulous descriptions of highly technical subjects make it difficult to read, but pioneers who do report having the rank of their Mog Garden mineral vein increase by one." },
    [2431] = { name = "\"MHMU Treatise on Minerals\"", description = "The official source on Mog Garden mining, issued by the Mog House Management Union. While it purportedly takes a critical look at mining techniques across Vana'diel, no one can decipher the abstruse and florid style of its authors. Nevertheless, flipping through its pages might increase the rank of the reader's mineral vein by one." },
    [2433] = { name = "\"A Farewell to Freshwater\"", description = "This biography focuses on two boys called the \"Moat Carp Kin\" by San d'Orians. According to critics, it raises more questions--such as, \"Why are they still fighting?\"-- than it answers. Still, the simplistic prose makes it accessible to all. Pioneers who read it report having the rank of their Mog Garden's pond dredger increase by one." },
    [2434] = { name = "\"Water, Water Everywhere!\"", description = "The sophomore work of the author behind \"A Farewell to Freshwater,\" this volume tackles the heady questions all inquiring minds want to know about the Moat Carp Kin. It also makes some revolutionary claims, such as, \"One cannot really get crystals from crystal bass.\" Pioneers who read it report having the rank of their Mog Garden's pond dredger increase by one." },
    [2435] = { name = "\"Dredging''s No Drudgery\"", description = "A step-by-step instructional guide that focuses specifically on freshwater fishing in Mog Gardens. Plastered with a plethora of pictures as well as the written word, this volume also accommodates intermediate farmers who learn bes by seeing rather than reading. Readers report having the rank of their pond dredger increase by one." },
    [2436] = { name = "\"All the Ways to Skin a Carp\"", description = "A compendium cataloguing the various methods by which a fisherman can employ nets to bring home a whopper--and bragging rights--and explains in detail the ones voted the most popular. Published annually, this is the book's eleventh edition, and pioneers who read it report having the rank of their Mog Garden's pond dredger increase by one." },
    [2437] = { name = "\"Anatomy of an Angler\"", description = "This collection of interviews from world-renowned net anglers in on what qualities are necessary for a professional fisherman to survive the highs and lows of this volatile vocation. Pioneers who read it report having the rank of their Mog Garden's pond dredger increase by one." },
    [2438] = { name = "\"MHMU Treatise on Fish I\"", description = "The official source on Mog Garden freshwater fishing, issued by the Mog House Management Union. While it takes a critical look at net casting techniques across Vana'diel, no one can decipher the abstruse and florid style of its authors. Nevertheless, flipping through its pages might increase the rank of the reader's pond dredger by one." },
    [2440] = { name = "\"The Old Men of the Sea\"", description = "A magazine that includes monthly interviews from famous sea fishermen all around the world. Many maniacal net casters dream of having their philosophy on fishing discussed within its pages, so it sports a relatively rabid readership. Pioneers who read it report having the rank of their Mog Garden's coastal fishing net increase by one." },
    [2441] = { name = "\"Susuroon''s Biiig Catch\"", description = "While this children's book has garnered praise from many for showing the young and old how fun and invigorating hauling fish in from the sea can be, it is also infamous for the horrendous scribbles the Qiqirn author boldly claims are illustrations. Pioneers who read it report having the rank of their Mog Garden's coastal fishing net increase by one." },
    [2442] = { name = "\"Black Fish of the Family\"", description = "This story of a minnow born a midnight hue concentrates on how he overcomes the obstacles imposed on him from the orange fish of his school. He eventually triumphs over their prejudices and proves that no matter what the color, all fish are created equal. Pioneers who read it report having the rank of their Mog Garden's coastal fishing net increase by one." },
    [2443] = { name = "\"20,000 Yalms Under the Sea\"", description = "A tale about how the protagonist, Nene, builds a submarines all by herself and plunges it into the darkest depths of the Senroh Sea. She describes an encyclopedia's worth of mystical deep sea creatures, and pioneers who read it report having the rank of their Mog Garden's coastal fishing net increase by one." },
    [2444] = { name = "\"Encyclopedia Icthyonnica\"", description = "This comprehensive collection contains everything pertaining to anything catchable with a net. Measuring five ilms from binding to binding and full of quixotic jargon, this tome is dense in terms of both physical dimensions and content. Pioneers who read it report having the rank of their Mog Garden's coastal fishing net increase by one." },
    [2445] = { name = "\"MHMU Treatise on Fish II\"", description = "The official source on Mog Garden saltwater fishing, issued by the Mog House Management Union. While it takes a critical look at net casting techniques across Vana'diel, no one can decipher the abstruse and florid style of its authors. Nevertheless, flipping through its pages might increase the rank of the reader's coastal fishing net by one." },
    [2447] = { name = "Mar. FS resource container", description = "A collection of materials from Marjami Ravine that are bound for the Couriers' Coalition." },
    [2448] = { name = "Yor. FS resource container", description = "A collection of materials from Yorcia Weald that are bound for the Couriers' Coalition." },
    [2449] = { name = "note detailing seditious plans", description = "A scrap of paper with the words \"We strike during the dead of night. You know what to do once inside the castle.\" hastily scrawled upon it." },
    [2450] = { name = "waterway facility crank", description = "This terribly rusty crank was once fitted to devices that must have fallen out of use decades ago." },
    [2451] = { name = "vial of translurry", description = "A peculiar liquid flecked with bits of indeterminate matter suspended within, this mixture is used for transmuting certain pieces of equipment." },
    [2452] = { name = "gil repository", description = "This rather understated box is designed to hold up to one billion gil. It is kept under constant watch by the Green Thumb Moogle, so there is no need to worry about prying hands emptying its contents." },
    [2453] = { name = "crab caller", description = "This unique device uses pheromonal essences to further attract crabaubles in Mog Gardens to you." },
    [2454] = { name = "piece of a stone wall", description = "This piece of stone wall touched by the light of dawn was taken from a lighthouse standing in Adoulin Waterfront." },
    [2455] = { name = "vial of untainted holy water", description = "This vial of holy water untainted by impurity was taken from the fountain in Western Adoulin." },
    [2456] = { name = "eternal flame", description = "This flame that has gone unextinguished for many years was given to you by an exorcist in Eastern Adoulin." },
    [2457] = { name = "weather vane wings", description = "These wings from a weather vane that has stood the test of time were retrieved from a storied manse in Eastern Adoulin." },
    [2458] = { name = "aureate ball of fur", description = "A matted collection of shed fur that once adorned Darrcuiln's hide. It absorbs any magical traces emitted by visitors to the wildcat's cave, allowing its bearer to track them." },
    [2459] = { name = "Inventors' Coalition pickaxe", description = "A made-to-order pickaxe crafted in celebration of Logan's imminent return." },
    [2460] = { name = "tintinnabulum", description = "A small, spherical bell bequeathed by Margret. It unleashes an auditory cataclysm that Margret assures is only perceptible to certain beasts' ears." },
    [2461] = { name = "\"Fragmenting\"", description = "A survival skill that grants the ability to obliterate the ice walls that dot the landscape of Eastern Ulbuka." },
    [2462] = { name = "pair of fuzzy earmuffs", description = "A warm pair of earmuffs is just what an intrepid adventurer needs to protect his ears when he attempts to find the weak spot in a barrier of ice." },
    [2463] = { name = "Kam. FB op. materials container", description = "A collection of materials that must be delivered to a frontier bivouac in the Kamihr Drifts." },
    [2464] = { name = "Kam. FS building mat. container", description = "A collection of materials to assist in the construction of a frontier station in Kamihr Drifts." },
    [2465] = { name = "Kam. FS resource container", description = "A collection of materials from Kamihr Drifts that are bound for the Couriers' Coalition." },
    [2466] = { name = "memorandoll", description = "This magic mannequin distributed by the A.M.A.N. records each and every Records of Eminence objective completed. Coated with a layer of astral essence, it slides easily between dimensions every time its owner claps their hands." },
    [2467] = { name = "algor resilience", description = "A survival skill that grants the tenacity to withstand the graupel formations that protrude from the banks of Kamihr Drifts." },
    [2468] = { name = "Shadow Lord phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2469] = { name = "Celestial Nexus phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2470] = { name = "Stellar Fulcrum phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2471] = { name = "phantom gem of apathy", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2472] = { name = "phantom gem of arrogance", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2473] = { name = "phantom gem of envy", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2474] = { name = "phantom gem of cowardice", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2475] = { name = "phantom gem of rage", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2476] = { name = "P. Perpetrator phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2477] = { name = "copper A.M.A.N. voucher", description = "Given to adventurers who have proven themselves in Records of Eminence, this tawny and reflective ticket is indispensible for acquiring rewards from the Adventurers' Mutual Aid Network." },
    [2482] = { name = "Matriarch Naakual paragon", description = "A monstrous and perfectly rounded gemstone, within which the violent winds associated with Colkhab swirl menacingly. Rumor states that this stone is the very reason she can summon destructive gales with a single twitch of her tail." },
    [2483] = { name = "Riptide Naakual paragon", description = "A monstrous and perfectly rounded gemstone, from within which the relentless pounding of Tchakka's aquatic lance can be heard. Rumor states that, depending on the bearer, this jewel has the power to drown continents." },
    [2484] = { name = "Firebrand Naakual paragon", description = "A monstrous and perfectly rounded gemstone, within which the scalding heat associated with Achuka flares restlessly. Rumor states that, should this gem suffer even a single crack, wildfires will rage unstoppable for months." },
    [2485] = { name = "Ligneous Naakual paragon", description = "A monstrous and perfectly rounded gemstone, within which the ominous rustling of Yumcax's leaves can be heard. Rumor states that this jewel can provide harvests bountiful enough to feed a city for centuries." },
    [2486] = { name = "Booming Naakual paragon", description = "A monstrous and perfectly rounded gemstone, within which the soft rumbling of Hurkan's thunderstorms can be heard. Rumor states that, depending on the bearer, this stone has the power to rend the heavens in twain." },
    [2487] = { name = "Flashfrost Naakual paragon", description = "A monstrous and perfectly rounded gemstone, from which Kumhau's icy breath emanates. Rumor states that this gem can freeze an adversary so thoroughly that he cannot be thawed even by the heat of a thousand hells." },
    [2489] = { name = "Mog Kupon I-AF109", description = "Issued by the Mog House Management Union (MHMU). Tradeable for chapters of Rem's Tale used in reforging job-specific equipment." },
    [2490] = { name = "Mog Kupon W-EWS", description = "Issued by the Mog House Management Union (MHMU). Tradeable for weapons used in acquiring empyrean weaponskills." },
    [2491] = { name = "Mog Kupon AW-WK", description = "Issued by the Mog House Management Union (MHMU). Tradeable for weapons and armor from wildskeeper reives." },
    [2492] = { name = "Mog Kupon I-S3", description = "Issued by the Mog House Management Union (MHMU). Tradeable for rank III simulacrum segments." },
    [2493] = { name = "Mog Kupon A-PK109", description = "Issued by the Mog House Management Union (MHMU). Tradeable for item level 109 Peacekeepers' Coalition armor." },
    [2494] = { name = "Mog Kupon I-S1", description = "Issued by the Mog House Management Union (MHMU). Tradeable for rank I simulacrum segments." },
    [2495] = { name = "Mog Kupon I-Skill", description = "Issued by the Mog House Management Union (MHMU). Tradeable for skill-boosting tomes." },
    [2496] = { name = "green institute card", description = "This emerald green card received in Windurst from the finicky Wetata of the Jeuno Institute of Magical Studies permits the bearer to participate in the Trust initiative." },
    [2497] = { name = "Windurst Trust permit", description = "This small certificate from Kupipi permits the bearer to officially use Trust magic." },
    [2498] = { name = "blue institute card", description = "This sapphire blue card received in Bastok from the wishy-washy Clarion Star of the Jeuno Institute of Magical Studies permits the bearer to participate in the Trust initiative." },
    [2499] = { name = "Bastok Trust permit", description = "This small certificate from Naji permits the bearer to officially use Trust magic." },
    [2500] = { name = "red institute card", description = "This ruby red card received in San d'Oria from the affable Gondebaud of the Jeuno Institute of Magical Studies permits the bearer to participate in the Trust initiative." },
    [2501] = { name = "San d'Oria Trust permit", description = "This small certificate from Excenmille permits the bearer to officially use Trust magic." },
    [2502] = { name = "Mog Kupon I-RME", description = "Issued by the Mog House Management Union (MHMU). Tradeable for pluton, beitetsu, and riftborn boulders." },
    [2503] = { name = "\"Pulverizing\"", description = "A survival skill that grants the ability to eradicate the occult doorways that dot the landscape of Eastern Ulbuka." },
    [2504] = { name = "Lerene's paten", description = "This small paten fashioned by Lerene dissolves magic enshrouding the doors within Ra'Kaznar, enabling the bearer to smash them to bits." },
    [2505] = { name = "Amchuchu's Missive", description = "This missive addressed to Cid explains in a roundabout manner that Midras is deemed to have done no wrong in the eyes of the Inventors' Coalition." },
    [2506] = { name = "Temple Knight key", description = "This master key to the Sacrarium held by Quelveuiat may only be carried by chevaliers of purest heart and mind." },
    [2507] = { name = "unblemished pioneer's badge", description = "This brand-new badge proving one's status as participant in the colonization initiative purportedly belongs to Emjook-Renook." },
    [2508] = { name = "silvery plate", description = "Pale blue light blinks off this silvery plate, which is needed to operate the lifts within Ra'Kaznar." },
    [2509] = { name = "soul siphon", description = "Once worn by Ingrid, this pendant harbors occult powers that interact negatively with spiritual energy, which she used to separate Arciela's transcendental soul from its corporeal form." },
    [2510] = { name = "bundle of half-inscribed scrolls", description = "These scrolls, supplied to you by Jamal of the Jeuno Institute of Magical Studies, are magical tableaus referred to as \"ciphers,\" and call upon the bonds of a third party to summon another being into this world." },
    [2511] = { name = "tapestry of bagua poetry", description = "Short, rhyming verses about Ulbuka's natural scenery are inscribed on this miniature tapestry. Turning it over on its side reveals some strange writing whose mysteries are begging to be solved." },
    [2512] = { name = "Futharkic Concepts in Flux", description = "This revisionist treatise mainly expands upon the phasal shift theory that currently enjoys much popularity among prominent runeologists. Authored by an anonymous individual, it imparts nothing particularly new on first glance." },
    [2513] = { name = "crystallized lifestream essence", description = "A soft warmth radiates from this brightly glowing crystal formed from the energies of gargantuan tree roots in Ra'Kaznar." },
    [2514] = { name = "strand of Ra'Kaznar filament", description = "Removed from a specific Ra'Kaznar partition, this fiber is so translucent it nearly escapes the naked eye. Each individual weave rhythmically swells with sorcerous energy." },
    [2515] = { name = "order slip: lifestream headgear", description = "The bubbly Wescolina provided you with this proof of purchase of a piece of bagua armor. Return to her at a later date to collect your order." },
    [2516] = { name = "order slip: lifestream bodygear", description = "The bubbly Wescolina provided you with this proof of purchase of a piece of bagua armor. Return to her at a later date to collect your order." },
    [2517] = { name = "order slip: lifestream handgear", description = "The bubbly Wescolina provided you with this proof of purchase of a piece of bagua armor. Return to her at a later date to collect your order." },
    [2518] = { name = "order slip: lifestream leggear", description = "The bubbly Wescolina provided you with this proof of purchase of a piece of bagua armor. Return to her at a later date to collect your order." },
    [2519] = { name = "order slip: lifestream footgear", description = "The bubbly Wescolina provided you with this proof of purchase of a piece of bagua armor. Return to her at a later date to collect your order." },
    [2520] = { name = "order slip: logomorph headgear", description = "This barely legible document is written in the hurried hand of the slightly snobbish--if not skillful-- Yestin-Ovestin. It promises that the clothier extraordinaire will provide a piece of runic armor once he deems his handiwork blemishless." },
    [2521] = { name = "order slip: logomorph bodygear", description = "This barely legible document is written in the hurried hand of the slightly snobbish--if not skillful-- Yestin-Ovestin. It promises that the clothier extraordinaire will provide a piece of runic armor once he deems his handiwork blemishless." },
    [2522] = { name = "order slip: logomorph handgear", description = "This barely legible document is written in the hurried hand of the slightly snobbish--if not skillful-- Yestin-Ovestin. It promises that the clothier extraordinaire will provide a piece of runic armor once he deems his handiwork blemishless." },
    [2523] = { name = "order slip: logomorph leggear", description = "This barely legible document is written in the hurried hand of the slightly snobbish--if not skillful-- Yestin-Ovestin. It promises that the clothier extraordinaire will provide a piece of runic armor once he deems his handiwork blemishless." },
    [2524] = { name = "order slip: logomorph footgear", description = "This barely legible document is written in the hurried hand of the slightly snobbish--if not skillful-- Yestin-Ovestin. It promises that the clothier extraordinaire will provide a piece of runic armor once he deems his handiwork blemishless." },
    [2525] = { name = "pristine hair ribbon", description = "This auburn ribbon, oft worn by Arciela as she headed to the Ulbukan wildlands, was found lying in the dirt of Ceizak Battlegrounds, where she was last seen." },
    [2526] = { name = "vial of transmelange", description = "A peculiar liquid flecked with bits of indeterminate matter suspended within, this mixture is used for transmuting certain pieces of equipment." },
    [2527] = { name = "lost article", description = "Left behind by a careless pioneer, this article should be delivered to the Mummers' Coalition with utmost haste." },
    [2528] = { name = "breath of dawn", description = "Light as a feather, this object slips away the more you strive to grasp it." },
    [2529] = { name = "phlox yantric planchette", description = "This board is made of finely polished phlox yggrete and is attuned to lift the veil in Marjami Ravine shrouding an obscured domain." },
    [2530] = { name = "russet yantric planchette", description = "This board is made of finely polished russet yggrete and is attuned to lift the veil in Yorcia Weald shrouding an obscured domain." },
    [2531] = { name = "aster yantric planchette", description = "This board is made of finely polished aster yggrete and is attuned to lift the veil in Kamihr Drifts shrouding an obscured domain." },
    [2532] = { name = "sparking tail feather", description = "Plucked from Cailimh, Marjami Ravine's avian terror, this caudal plumage still occasionally emits an electric pulse." },
    [2533] = { name = "piece of inviolable bark", description = "Mercilessly ripped from the trunk of Wopket, a ligneous abomination rooted in the obscured domain within Yorcia Weald, this hunk of wooden armor drips with a quickly hardening sap." },
    [2534] = { name = "frosted incisor", description = "Wrenched from the mouth of Utkux, the chill-inducing feline that hunts along the tundra of Kamihr Drifts, this frigid tooth is encrusted in small, knife-edged ice crystals." },
    [2535] = { name = "impure phlox yggzi", description = "A petrified phlox yggzi bead of questionable quality." },
    [2536] = { name = "semi-pure phlox yggzi", description = "A semi-pure petrified phlox yggzi bead with large variances in shape." },
    [2537] = { name = "impure russet yggzi", description = "A petrified russet yggzi bead of questionable quality." },
    [2538] = { name = "semi-pure russet yggzi", description = "A semi-pure petrified russet yggzi bead with large variances in shape." },
    [2539] = { name = "impure aster yggzi", description = "A petrified aster yggzi bead of questionable quality." },
    [2540] = { name = "semi-pure aster yggzi", description = "A semi-pure petrified aster yggzi bead with large variances in shape." },
    [2541] = { name = "breath of dawn", description = "Light as a feather, this object found in Ronfaure in the Shadowreign Era slips away the more you strive to grasp it." },
    [2542] = { name = "breath of dawn", description = "Light as a feather, this object found in Jugner Forest in the Shadowreign Era slips away the more you strive to grasp it." },
    [2543] = { name = "breath of dawn", description = "Light as a feather, this object found in Beaucedine Glacier in the Shadowreign Era slips away the more you strive to grasp it." },
    [2544] = { name = "job breaker", description = "You have been recognized by Nomad Moogles across Vana'diel as an expert in your profession." },
    [2545] = { name = "Savage's phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2546] = { name = "Warrior's Path phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2547] = { name = "Peppe-Aleppe's superlative tonic", description = "This foul-smelling liquid, made from the natural oils contained in ruszor leather, protects against the biting gales expelled from vents in Kamihr Drifts." },
    [2548] = { name = "Sajj'aka's protective ward", description = "Sajj'aka infused this small athame with a miniscule portion of the latent energies protecting the wilds." },
    [2549] = { name = "sunkissed scale", description = "This scale, scoured wholesale from Sajj'aka's chest, glows a vibrant yellow as bright as the mid-noon sun." },
    [2550] = { name = "moontouched scale", description = "This scale, scoured wholesale from Sajj'aka's chest, glows a pale amber as soft as a lenten moon." },
    [2551] = { name = "starblessed scale", description = "This scale, scoured wholesale from Sajj'aka's chest, glows a twinkling white as sparkling as the nighttime sky." },
    [2552] = { name = "tuft of golden fur", description = "This fluffy fistful seems to be calling you to Darrcuiln's master..." },
    [2553] = { name = "ivory wing talisman", description = "A charm crafted in the shape of ivory wings, the symbol of the Goddess Altana. Reduces the amount of experience lost when knocked out during reives." },
    [2554] = { name = "silver mattock cordon", description = "Embroidered with a gleaming silver mattock, this badge is given only to pioneers who have gone above and beyond the call of duty in advancing the colonization initiative. Increases the maximum number of coalition imprimaturs able to be held at one time." },
    [2555] = { name = "silver shovel cordon", description = "Embroidered with a gleaming silver shovel, this badge is given only to pioneers who have gone above and beyond the call of duty in advancing the colonization initiative. Reduces the waiting period for new coalition imprimaturs." },
    [2556] = { name = "Puppet in Peril phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2557] = { name = "Legacy phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2558] = { name = "World Tree sapling", description = "Sajj'aka procured this 12-ilm tall sapling from a Lightsland sheltered away in an unknown location. It is said August planted one in the most sacred area of Ulbuka..." },
    [2559] = { name = "Mog Kupon I-???", description = "Issued by the Mog House Management Union (MHMU)." },
    [2560] = { name = "Mog Kupon W-Job", description = "Issued by the Mog House Management Union (MHMU). Tradeable for job-specific weapons crafted by Oboro." },
    [2561] = { name = "Mog Kupon I-Mat", description = "Issued by the Mog House Management Union (MHMU). Tradeable for various special materials." },
    [2562] = { name = "Mog Kupon W-DeIII", description = "Issued by the Mog House Management Union (MHMU). Tradeable for weapons from Delve bosses." },
    [2563] = { name = "Mog Kupon AW-Mis", description = "Issued by the Mog House Management Union (MHMU). Tradeable for spoils from high-tier mission battlefields other than A Stygian Pact, Champion of the Dawn, Divine Interference, and Maiden of the Dusk." },
    [2564] = { name = "sheet of Zilart tunes", description = "Sheet music that can be played on an orchestrion. Music List: Kazham The Sanctuary of Zi'Tah Tu'Lia" },
    [2565] = { name = "rusted handbell", description = "Covered in a layer of rust, this cracked handbell has seen better days, and issues forth no sound even with the strongest of shakes." },
    [2566] = { name = "emblazoned handbell", description = "High-purity bayld infused this bell with geomantic energy. Its ring echoes clear and true." },
    [2567] = { name = "Ripple Prominence concretion", description = "Created from high-purity bayld, this crystal imparts the bearer with an intense feeling of sadness." },
    [2568] = { name = "inferno concretion", description = "Created from high-purity bayld, this crystal imparts the bearer with an intense enthusiasm." },
    [2569] = { name = "cyclone concretion", description = "Created from high-purity bayld, this crystal imparts the bearer with an intense feeling of affection." },
    [2570] = { name = "numbing blossom seed", description = "This nascent wild peril exudes a special oil that is used in the manufacture of myriad goods." },
    [2571] = { name = "broken rapier hilt", description = "The rusted remains of an ancient sword. The blade itself has been severed just above its base, rendering it completely useless." },
    [2572] = { name = "vial of crimson catalyst", description = "Rumors surrounding this violently red solution state that it enables the bearer to travel to worlds beyond by suppressing his runic powers. Should it fall into the hands of a fool, however, his puissance shall be sealed away for all eternity." },
    [2573] = { name = "\"Quiescence\"", description = "Bestowed upon rune fencers who have awakened to their true potential, the character itself causes a bright light to shine around its bearer." },
    [2574] = { name = "superlative runic ring of deluge", description = "Purchased with high-purity bayld and fashioned via a clandestine process of synthesis, this ring imparts its bearer with the chill of an icy waterfall." },
    [2575] = { name = "superlative runic ring of luster", description = "Purchased with high-purity bayld and fashioned via a clandestine process of synthesis, this ring intermittently glows as bright as a flash of lightning." },
    [2576] = { name = "superlative runic ring of vision", description = "Purchased with high-purity bayld and fashioned via a clandestine process of synthesis, this ring imparts its bearer with an acute feeling of transience, as if he is dreaming." },
    [2577] = { name = "nicked dagger", description = "Viscous fluid covers this blade, found in the brush in Foret de Hennetiel. The tip has been completely shattered." },
    [2578] = { name = "magicked astrolabe", description = "Etched into this board's wooden surface is a detailed depiction of astral body relationships, with small gems representing each of the different constellations." },
    [2579] = { name = "bracelet of verve", description = "The might of a thousand trolls pulses in the metal confines of this trinket." },
    [2580] = { name = "copy of \"Wrath of the Land\"", description = "\"Multiple sources corroborate the intermittent occurrence of landshivers throughout the centuries, but almost none mention such phenomena before the Ulbukan continent was buried under a dense jungle.\" AoWv" },
    [2581] = { name = "copy of \"Hallowed Wood\"", description = "This painting of a sacred tree is thought to have been finished around Crystal Era 480 and is widely considered one of the most influential landscapes in Adoulinian history." },
    [2582] = { name = "\"Hallowed Wood\" replica", description = "An imitation of the famous ancient Adoulinian painting that depicts a sacred tree." },
    [2583] = { name = "copy of \"Shrouded in Enigma\"", description = "An article with the intriguing headline of \"Scoop of the century! Gentleman of the Night's identity discovered!\" but ends with a disappointing \"Everyone has a bit of the Gentleman inside them.\" Jt" },
    [2584] = { name = "report of a sorcerous nation", description = "\"Though Sverdhried is most often known for his rigorous training on the large hillock in Eastern Adoulin, he also traveled the world. One spot he supposedly visited was a now-forgotten country on the Rhazowan continent.\"" },
    [2585] = { name = "copy of \"The Verdancy\"", description = "\"I shall write only what I have seen, with no embellishments. Not only had the trees I cleared to make a path grown back overnight, but the whole of Ulbuka was covered in vegetation! Just what has possessed this land?\" JvJo" },
    [2586] = { name = "giant sheep export record", description = "A simple clerical document noting the export of domesticated giant sheep to the Quon continent in Crystal Era 607 along with the exact price of the transaction. WhAt" },
    [2587] = { name = "dictum on colonization", description = "\"...the citizens of.... In accordance with.........any acts...elopment or coloni...no lo...bbiden. However, this does no......to deface or oth...harm to...orest.\" Jt" },
    [2588] = { name = "Adoulinian agricultural treatise", description = "\"Due to the poor quality of our soil, we have mostly failed in our agrarian pursuits. However, trading giant sheep for flour milled in the Zulkheim region and constructing a greenhouse in the Rala Waterways have somewhat mitigated our woes.\"" },
    [2589] = { name = "mystifying metal rod", description = "This long metal projection found in the Woh Gates is heavier than its appearance would make it seem." },
    [2590] = { name = "rusty katana", description = "This blade is thought to be one of the traditional military swords used by ancient Adoulinians. The layers of rust that encompass it are so thick that the katana cannot be removed from its sheath." },
    [2591] = { name = "traditional Adoulinian katana", description = "A military-issue sword used during the internal struggle that took place between the Twelve Orders. Its weight could very well symbolize the heavy heart with which its owner swung the blade." },
    [2592] = { name = "piece of a SCT Coalition report", description = "This appears to be nothing more than a scrap torn from a larger sheet of normal paper." },
    [2593] = { name = "cryptic memorandum", description = "soft embrace = repugnant face rid = rob sorrows = joy sun = underworld rise every morrow = consume and destroy love = loathe set me free = should hang from a tree" },
    [2594] = { name = "memo found in Rala Waterways", description = "k v s h o t A A B C D E F G G H --J K L J M ----P Q R W S T ----W X R Y --------- We------------" },
    [2595] = { name = "Head Wind phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2596] = { name = "butterfly-shaped key", description = "This small key, comprised of two intertwined bands of metal, opens the door to the sealed arena in the Walk of Echoes." },
    [2597] = { name = "sturdy hide pouch", description = "This hardened leather pouch bequeathed upon you by the Blackthorn Coven has separate compartments for holding water from various ergon loci." },
    [2598] = { name = "\"Suffering Sacchariferous\"", description = "Often cited as the definitive cookbook for young women who exhibit a soft spot for sweets, this volume details dozens of adorable recipes. Even the cover is enticing enough to eat, though that would surely put the Celennia Memorial Library out a coveted text." },
    [2599] = { name = "sepulcher ensign", description = "Formerly one of Chancellor Ygnas's possessions, this slightly disturbing insignia emits an almost maternal warmth. It also appears to serve as a key to the founder king's resting place." },
    [2600] = { name = "consummate simulacrum", description = "A simulacrum Balamor dispersed to a frenzied beast that stalked the waterways. Logic dictates that holding it up to an Augural Conveyor in Rala Waterways should do the trick." },
    [2601] = { name = "broken fuse", description = "This scorched fuse was likely the source of a massive explosion in Rala Waterways." },
    [2602] = { name = "Rala eudaemon", description = "A statue assembled from four different segments that grants its bearer access to alluvion skirmishes in Rala Waterways [U]." },
    [2603] = { name = "Yorcia eudaemon", description = "A statue assembled from four different segments that grants its bearer access to alluvion skirmishes in Yorcia Weald [U]." },
    [2604] = { name = "Cirdas eudaemon", description = "A statue assembled from four different segments that grants its bearer access to alluvion skirmishes in Cirdas Caverns [U]." },
    [2606] = { name = "Velkk fetish", description = "This charm, often used by Velkk mystics in unholy rituals, is fashioned from the hide of one of their own." },
    [2607] = { name = "Ymmr-Ulvid's necklace", description = "The noxious odor emanating from this most unfashionable bauble once owned by Ymmr-Ulvid Gloomlight causes nearby flora to wither." },
    [2608] = { name = "Ignor-Mnt's bracelet", description = "Ignor-Mnt Stealthslayer used only the most rusted and repulsive of metal scraps to fashion this abomination." },
    [2609] = { name = "Durs-Vike's earring", description = "Only Durs-Vike Deathspell could pull off leathery charms of as malodorous an attire as these." },
    [2610] = { name = "Tryl-Wuj's belt", description = "This belt, once proudly worn by Tryl-Wuj Wingrip as a sign of his many victories in battle, is so worn and rancid that it's impossible to discern whether it is leather or cloth." },
    [2611] = { name = "pair of Liij-Vok's gloves", description = "The numerous pricks and holes in this flimsy hand attire are indicative of where Liij-Vok Waxwane's scaly flesh tore at the inseams." },
    [2612] = { name = "Gramk-Droog's circlet", description = "A symbol of power amongst the Velkk, this circlet confers upon its bearer a measure of barbarous authority." },
    [2613] = { name = "elder wooden box", description = "Though old, this box still maintains its original shape." },
    [2614] = { name = "imprint device S", description = "This wooden device is said to transmit images of the past to its bearer when held up to the forehead under certain conditions. Disposable." },
    [2615] = { name = "record of the generals' foray", description = "This recording depicts August and his eleven generals pitted in a momentous struggle against a winged beast. Swirling storms and booming thunder are etched into the plate." },
    [2616] = { name = "record of a cavernous foray", description = "This recording depicts August and his eleven generals in a phalanx formation as they assault a sickly-colored fiend. A choking miasma is seared into the plate." },
    [2617] = { name = "record of the knight in black", description = "This recording depicts August facing off against a man of unknown origin. What happened after their inauspicious meeting is lost to the ages, but the weight of their presence is ingrained into the plate." },
    [2618] = { name = "record of a thousand lights", description = "This record depicts the miracle that Ceizak bore witness to. A brilliant wall of light dispelled the forces of darkness and scattered the remaining Velkk armies. The will of Jorius is inscribed into the plate." },
    [2619] = { name = "avatar phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [2620] = { name = "Heroes and Legends of Adoulin", description = "This volume, faithfully transcribed by Oshasha, boasts not only myriad tales of heroic deeds and valorous tales of August and his eleven generals, but details the minutiae of their personality quirks, hopes, and fears." },
    [2621] = { name = "hastily scribbled note", description = "Though the envelope is delicately sealed with wax in the shape of a swallow, the letter inside contains but two words: \"The port.\"" },
    [2622] = { name = "sky blue pome", description = "This pome from Rosulatia, blue as the sky on a clear winter day, beckons you to a spot of power in Yorcia Weald." },
    [2623] = { name = "sun yellow pome", description = "This pome from Rosulatia, yellow as the sun at high noon, beckons you to a spot of power in Cirdas Caverns." },
    [2624] = { name = "Ashrakk's blood sigil", description = "This pulsating red abomination, which fits not-so-cleanly in the palm of your hand, was severed from the body of Ashrakk, the Duskbrood Xol." },
    [2625] = { name = "Dhokmak's blood sigil", description = "This pulsating red abomination, which fits not-so-cleanly in the palm of your hand, was severed from the body of Dhokmak, the Brash Xol." },
    [2626] = { name = "ash runic board", description = "Though the script seared into the board is wholly illegible, Teodor claims it is a key to enter the Watergarden Coliseum in Rala Waterways." },
    [2627] = { name = "Teodor's blood sigil", description = "This pulsating red abomination, which fits not-so-cleanly in the palm of your hand, was severed from the body of Teodor, the former Deathborne Xol." },
    [2628] = { name = "awakened crystallized psyche", description = "The will of Tartarus pulses fervently, beckoning you to where Hades awaits." },
    [2629] = { name = "Arciela's spare bonnet", description = "Arciela bequeathed unto you one of her spare white summer bonnets...but it feels like something is missing." },
    [2630] = { name = "Arciela's skirt", description = "It was undoubtedly improper for you to obtain an item of such a personal nature, but the ornate plates of adaman and gold make it as fanciful as it is eye-catching." },
    [2631] = { name = "concordoll", description = "This magic mannequin distributed by the A.M.A.N. bonds with memorandolls from Records of Eminence, recording the deeds of those participating in Unity Concord. It also enables long-distance communiques similar to those of linkshell origin. Model No.: U-lyne-0." },
    [2632] = { name = "crystallized psyche", description = "The three blood sigils wrested from control of the Xol Triumvirate have coagulated into a pure black stone. The gates of Ra'Kaznar Turris should open now." },
    [2633] = { name = "\"Sakura and the Magic Spoon\"", description = "This work of fiction written by Markovic details a magic spoon used by the prestigious Sakura that, when used to consume a meal, enables her to communicate with all living things. Pioneers who read it report having their monster rearing rank increase by one." },
    [2640] = { name = "blank ash runic board", description = "The lettering on the slate bequeathed unto you by Teodor has completely vanished." },
    [2641] = { name = "prototype sigil pearl", description = "The marbled swirlings in this pearl can copy and replicate information gleaned from the memories of the bearer's battles." },
    [2642] = { name = "lamb memento", description = "A pleasant memory of a lamb within the Mog Garden that gives Chacharoon the strength to cheer you on." },
