    [2716] = { name = "Cheer: Lamb", description = "A cheer from Chacharoon based on the pleasant memories of raising a lamb. Confers an experience point bonus of 2%." },
    [2717] = { name = "Cheer: Sheep", description = "A cheer from Chacharoon based on the pleasant memories of raising a sheep. Increases clothcraft skill gain rate by 1% and alter ego attack by 5%. Also affects ranged attack." },
    [2718] = { name = "Cheer: Karakul", description = "A cheer from Chacharoon based on the pleasant memories of raising a karakul. Increases leathercraft skill gain rate by 1% and alter ego attack and ranged attack by 5%." },
    [2719] = { name = "Cheer: Ram", description = "A cheer from Chacharoon based on the pleasant memories of raising a ram. Increases bonecrafting skill gain rate by 1% and alter ego attack and ranged attack by 5%." },
    [2720] = { name = "Cheer: Sapling", description = "A cheer from Chacharoon based on the pleasant memories of raising a sapling. Increases guarding and shield skills gain rate by 10%." },
    [2721] = { name = "Cheer: G. Fol. Treant", description = "A cheer from Chacharoon based on the pleasant memories of raising a green foliage treant. Increases woodworking skill gain rate by 1% and alter ego defense by 5%." },
    [2722] = { name = "Cheer: R. Fol. Treant", description = "A cheer from Chacharoon based on the pleasant memories of raising a red foliage treant. Increases the healing magic, enhancing magic, geomancy, and handbell skills gain rate by 10% and alter ego magic defense by 5%." },
    [2723] = { name = "Cheer: Baby Rabbit", description = "A cheer from Chacharoon based on the pleasant memories of raising a baby rabbit. Increases the evasion and parrying skills gain rate by 10%." },
    [2724] = { name = "Cheer: Rabbit", description = "A cheer from Chacharoon based on the pleasant memories of raising a rabbit. Increases cooking skill gain rate by 1% and alter ego weapon skill damage by 5%." },
    [2725] = { name = "Cheer: White Rabbit", description = "A cheer from Chacharoon based on the pleasant memories of raising a white rabbit. Confers a capacity point bonus of 1%." },
    [2726] = { name = "Cheer: Baby Lizard", description = "A cheer from Chacharoon based on the pleasant memories of raising a baby lizard. Increases the ninjutsu, enfeebling magic, and dark magic skills gain rate by 10%." },
    [2727] = { name = "Cheer: Lizard", description = "A cheer from Chacharoon based on the pleasant memories of raising a lizard. Increases leathercraft skill gain rate by 1% and alter ego accuracy and ranged accuracy by 5%." },
    [2728] = { name = "Cheer: Alabaster Lizard", description = "A cheer from Chacharoon based on the pleasant memories of raising an alabaster lizard. Increases goldsmithing skill gain rate by 1% and alter ego accuracy and ranged accuracy by 5%." },
    [2729] = { name = "Cheer: Baby Cockatrice", description = "A cheer from Chacharoon based on the pleasant memories of raising a baby cockatrice. Increases the archery, marksmanship, and throwing skills gain rate by 10%." },
    [2730] = { name = "Cheer: Cockatrice", description = "A cheer from Chacharoon based on the pleasant memories of raising a cockatrice. Increases alchemy skill gain rate by 1% and alter ego magic attack by 5%." },
    [2731] = { name = "Cheer: Ziz", description = "A cheer from Chacharoon based on the pleasant memories of raising a ziz. Increases smithing skill gain rate by 1% and alter ego magic attack by 5%." },
    [2732] = { name = "Cheer: Baby Raptor", description = "A cheer from Chacharoon based on the pleasant memories of raising a baby raptor. Increases hand-to-hand skill gain rate by 10%." },
    [2733] = { name = "Cheer: Raptor", description = "A cheer from Chacharoon based on the pleasant memories of raising a raptor. Increases the dagger, sword, axe, katana, and club skills gain rate by 10% and alter ego evasion by 5%." },
    [2734] = { name = "Cheer: Red Raptor", description = "A cheer from Chacharoon based on the pleasant memories of raising a red raptor. Increases the great sword, great axe, scythe, polearm, great katana, and staff skills gain rate by 10% and alter ego evasion by 5%." },
    [2735] = { name = "Cheer: Baby Eft", description = "A cheer from Chacharoon based on the pleasant memories of raising a baby eft. Increases fishing skill gain rate by 1%." },
    [2736] = { name = "Cheer: Eft", description = "A cheer from Chacharoon based on the pleasant memories of raising an eft. Increases the elemental, divine, and blue magic magic skills gain rate by 10% and alter ego magic evasion by 5%. * Only when average item level is over 100." },
    [2737] = { name = "Cheer: Tarichuk", description = "A cheer from Chacharoon based on the pleasant memories of raising a tarichuk. Increases the summoning magic, singing, wind instrument, and stringed instrument skills gain rate by 10% and alter ego magic evasion by 5%. * Only when average item level is over 100." },
    [2738] = { name = "Cheer: Dhalmel Calf", description = "A cheer from Chacharoon based on the pleasant memories of raising a dhalmel calf. Increases mind by 2 and guarding and shield skills gain rate by 10%." },
    [2739] = { name = "Cheer: Dhalmel", description = "A cheer from Chacharoon based on the pleasant memories of raising a dhalmel. Increases mind by 3 and alter ego \"Cure\" potency by 5%." },
    [2740] = { name = "Cheer: Great Dhalmel", description = "A cheer from Chacharoon based on the pleasant memories of raising a great dhalmel. Increases mind by 4 and alter ego \"Cure\" potency by 8%." },
    [2741] = { name = "Cheer: Sea Monk Larva", description = "A cheer from Chacharoon based on the pleasant memories of raising a sea monk larva. Increases dexterity by 2 and guarding and shield skills gain rate by 10%." },
    [2742] = { name = "Cheer: Sea Monk", description = "A cheer from Chacharoon based on the pleasant memories of raising a sea monk. Increases dexterity by 3 and alter ego attack and ranged attack by 5%." },
    [2743] = { name = "Cheer: Blue Sea Monk", description = "A cheer from Chacharoon based on the pleasant memories of raising a blue sea monk. Increases dexterity by 3 and alter ego accuracy and ranged accuracy by 5%." },
    [2744] = { name = "Cheer: Uragnite Youngling", description = "A cheer from Chacharoon based on the pleasant memories of raising an uragnite youngling. Increases vitality by 2 and summoning magic, singing, wind instrument, and stringed instrument skills gain rate by 10%." },
    [2745] = { name = "Cheer: Uragnite", description = "A cheer from Chacharoon based on the pleasant memories of raising an uragnite. Increases capacity point gains by 3% and experience point gains by 5%." },
    [2746] = { name = "Cheer: Limascabra", description = "A cheer from Chacharoon based on the pleasant memories of raising a limascabra. Confers a capacity point bonus of 5% and experience point bonus of 3%." },
    [2747] = { name = "Cheer: Immature Crab", description = "A cheer from Chacharoon based on the pleasant memories of raising an immature crab. Increases vitality by 2 and bonecraft skill gain rate by 1%." },
    [2748] = { name = "Cheer: Crab", description = "A cheer from Chacharoon based on the pleasant memories of raising a crab. Increases vitality by 3 and alter ego physical defense by 5%." },
    [2749] = { name = "Cheer: Porter Crab", description = "A cheer from Chacharoon based on the pleasant memories of raising a porter crab. Increases vitality by 4 and alter ego physical defense by 8%." },
    [2750] = { name = "Cheer: Baby Colibri", description = "A cheer from Chacharoon based on the pleasant memories of raising a baby colibri. Increases intelligence by 2 and evasion and parrying skills gain rate by 10%." },
    [2751] = { name = "Cheer: Colibri", description = "A cheer from Chacharoon based on the pleasant memories of raising a colibri. Increases intelligence by 3 and alter ego magic defense bonus by 5." },
    [2752] = { name = "Cheer: Toucalibri", description = "A cheer from Chacharoon based on the pleasant memories of raising a toucalibri. Increases intelligence by 3 and alter ego magic evasion by 5%. * Only when average item level is over 100." },
    [2753] = { name = "Cheer: Coeurl Cub", description = "A cheer from Chacharoon based on the pleasant memories of raising a coeurl cub. Increases agility by 2 and alter ego attack and ranged attack by 3%." },
    [2754] = { name = "Cheer: Coeurl", description = "A cheer from Chacharoon based on the pleasant memories of raising a coeurl. Confers an experience point bonus of 3%, increases agility by 3, and increases alter ego attack and ranged attack by 5%." },
    [2755] = { name = "Cheer: Lynx", description = "A cheer from Chacharoon based on the pleasant memories of raising a lynx. Confers a capacity point bonus of 3%, increases agility by 3, and increases alter ego attack and ranged attack by 5%." },
    [2756] = { name = "Cheer: Buffalo Calf", description = "A cheer from Chacharoon based on the pleasant memories of raising a buffalo calf. Increases vitality by 2 and alter ego defense by 3%." },
    [2757] = { name = "Cheer: Buffalo", description = "A cheer from Chacharoon based on the pleasant memories of raising a buffalo. Confers a capacity point bonus of 3%, increases vitality by 3, and increases alter ego defense by 5%." },
    [2758] = { name = "Cheer: Mini Slime", description = "A cheer from Chacharoon based on the pleasant memories of raising a mini slime. Increases strength by 2 and alter ego accuracy and ranged accuracy by 3%." },
    [2759] = { name = "Cheer: Slime", description = "A cheer from Chacharoon based on the pleasant memories of raising a slime. Confers a capacity point bonus of 3%, increases strength by 3, and increases alter ego accuracy and ranged accuracy by 5%." },
    [2760] = { name = "Cheer: Clot", description = "A cheer from Chacharoon based on the pleasant memories of raising a clot. Confers a capacity point bonus of 3%, increases strength by 3, and increases alter ego attack and ranged attack by 5%." },
    [2761] = { name = "Cheer: Hecteyes", description = "A cheer from Chacharoon based on the pleasant memories of raising a hecteyes. Confers a capacity point bonus of 5%, increases intelligence by 4, and increases alter ego magic attack by 8." },
    [2762] = { name = "Cheer: Tiny Bugard", description = "A cheer from Chacharoon based on the pleasant memories of raising a tiny bugard. Confers an experience point bonus of 4% and increases alter ego weapon skill damage by 3%." },
    [2763] = { name = "Cheer: Bugard", description = "A cheer from Chacharoon based on the pleasant memories of raising a bugard. Confers a capacity point bonus of 4%, increases strength by 5, and increases alter ego weapon skill damage by 5%." },
    [2764] = { name = "Cheer: Abyssobugard", description = "A cheer from Chacharoon based on the pleasant memories of raising an abyssobugard. Confers a capacity point bonus of 4%, increases physical and ranged attack by 2%, and increases alter ego critical damage dealt by 3%." },
    [2765] = { name = "Cheer: Baby Adamantoise", description = "A cheer from Chacharoon based on the pleasant memories of raising a baby adamantoise. Confers an experience point bonus of 3%, increases vitality by 4, and increases alter ego HP by 5%." },
    [2766] = { name = "Cheer: Adamantoise", description = "A cheer from Chacharoon based on the pleasant memories of raising an adamantoise. Confers a capacity point bonus of 4%, increases vitality by 6, and increases alter ego HP by 7%." },
    [2767] = { name = "Cheer: Great Adamantoise", description = "A cheer from Chacharoon based on the pleasant memories of raising a great adamantoise. Confers a capacity point bonus of 5%, increases vitality by 8, and increases alter ego HP by 10%." },
    [2768] = { name = "Cheer: White Adamantoise", description = "A cheer from Chacharoon based on the pleasant memories of raising a white adamantoise. Confers a capacity point bonus of 5%, increases Auto Regen by 1, and increases alter ego chance of countering attacks by 1%." },
    [2769] = { name = "Cheer: Ferromantoise", description = "A cheer from Chacharoon based on the pleasant memories of raising a ferromantoise. Confers a capacity point bonus of 4%, increases magic defense by 1, and increases alter ego magic defense by 5." },
    [2770] = { name = "Cheer: Great Ferromantoise", description = "A cheer from Chacharoon based on the pleasant memories of raising a great ferromantoise. Confers a capacity point bonus of 5%, increases magic defense by 2, and increases alter ego magic defense by 6." },
    [2771] = { name = "Cheer: Cluster", description = "A cheer from Chacharoon based on the pleasant memories of raising a cluster. Confers an experience point bonus of 5%, increases magic skill gain rate by 10%, and increases magic accuracy by 2." },
    [2772] = { name = "Cheer: Bomb", description = "A cheer from Chacharoon based on the pleasant memories of raising a bomb. Confers a capacity point bonus of 5%; increases magic attack, intelligence, mind, and charisma by 2; and increases alter ego magic attack by 10." },
    [2773] = { name = "Cheer: Djinn", description = "A cheer from Chacharoon based on the pleasant memories of raising a djinn. Confers a capacity point bonus of 5%; increases intelligence, mind, charisma, and magic accuracy by 2; and increases alter ego magic accuracy by 10." },
    [2774] = { name = "Cheer: Snoll", description = "A cheer from Chacharoon based on the pleasant memories of raising a snoll. Confers a capacity point bonus of 6%, increases MP by 16%, increases Resist Silence by 10, and increases alter ego Resist Silence by 10." },
    [2775] = { name = "Cheer: Behemoth Cub", description = "A cheer from Chacharoon based on the pleasant memories of raising a behemoth cub. Confers an experience point bonus of 5%, increases combat skill gain rate by 10%, and increases physical accuracy by 3." },
    [2776] = { name = "Cheer: Behemoth", description = "A cheer from Chacharoon based on the pleasant memories of raising a behemoth. Confers a capacity point bonus of 5%, increases physical attack by 2%, and increases alter ego physical attack by 6%." },
    [2777] = { name = "Cheer: King Behemoth", description = "A cheer from Chacharoon based on the pleasant memories of raising a king behemoth. Confers a capacity point bonus of 7%, increases physical attack by 2%, and increases alter ego physical attack by 7%." },
    [2778] = { name = "Cheer: Elasmoth", description = "A cheer from Chacharoon based on the pleasant memories of raising an elasmoth. Confers a capacity point bonus of 8%, increases Resist Curse by 10, and increases alter ego Resist Curse by 10." },
    [2779] = { name = "Cheer: Skormoth", description = "A cheer from Chacharoon based on the pleasant memories of raising a skormoth. Confers a capacity point bonus of 9%, increases Resist Amnesia by 10, and increases alter ego Resist Amnesia by 10." },
    [2780] = { name = "Cheer: Dragon Hatchling", description = "A cheer from Chacharoon based on the pleasant memories of raising a dragon hatchling. Increases strength, dexterity, agility, vitality, intelligence, mind, and charisma by 2; magic skill gain rate by 10%; and alter ego HP and MP by 10%." },
    [2781] = { name = "Cheer: Wyvern", description = "A cheer from Chacharoon based on the pleasant memories of raising a wyvern. Confers a capacity point bonus of 6% and increases strength and dexterity by 3, \"Zanshin\" by 2%, and alter ego double attack rate by 3%." },
    [2782] = { name = "Cheer: Blue Wyvern", description = "A cheer from Chacharoon based on the pleasant memories of raising a blue wyvern. Confers a capacity point bonus of 6%; increases strength, dexterity, and physical and ranged accuracy by 4; and increases alter ego haste by 5%." },
    [2783] = { name = "Cheer: Green Wyvern", description = "A cheer from Chacharoon based on the pleasant memories of raising a green wyvern. Confers a capacity point bonus of 6%, increases strength and dexterity by 4, increases haste by 1%, and increases alter ego double attack rate by 5%." },
    [2784] = { name = "Cheer: Abyssal Wyrm", description = "A cheer from Chacharoon based on the pleasant memories of raising an abyssal wyrm. Confers a capacity point bonus of 6%, increases \"Demon Killer\" by 10, and increases alter ego Counter rate by 2% and potency of \"Cure\" effects received by 10%." },
    [2785] = { name = "Cheer: Lunar Wyrm", description = "A cheer from Chacharoon based on the pleasant memories of raising a lunar wyrm. Confers a capcity point bonus of 8%, increases magic defense by 3, and increases alter ego \"Fast Cast\" by 20 and magic accuracy by 10%." },
    [2786] = { name = "Cheer: Blazing Wyrm", description = "A cheer from Chacharoon based on the pleasant memories of raising a blazing wyrm. Confers a capacity point bonus of 8%, increases Counter rate by 2%, and increases alter ego \"Store TP\" by 5 and physical and ranged accuracy by 10%." },
    [2787] = { name = "Cheer: Pequetender", description = "A cheer from Chacharoon based on the pleasant memories of raising a pequetender. Confers an experience point bonus of 6%, increases vitality and agility by 3, and increases alter ego weapon skill damage by 8% and critical hit damage by 5%." },
    [2788] = { name = "Cheer: Sabotender", description = "A cheer from Chacharoon based on the pleasant memories of raising a sabotender. Confers an experience point bonus of 6%, increases vitality and agility by 4, and increases alter ego weapon skill accuracy by 10 and magic burst damage by 5%." },
    [2789] = { name = "Cheer: Jumbotender", description = "A cheer from Chacharoon based on the pleasant memories of raising a jumbotender. Confers a capacity point bonus of 7%, increases movement speed by 3%, and increases alter ego \"Regen\" by 5 and \"Refresh\" by 3." },
    [2790] = { name = "sheet of conflict tunes", description = "Sheet music that can be played on an orchestrion. Music List: Awakening, Belief, A Realm of Emptiness" },
    [2791] = { name = "sheet of Promathia tunes", description = "Sheet music that can be played on an orchestrion. Music List: Distant Worlds (instrumental version)" },
    [2792] = { name = "sheet of Adoulinian tunes", description = "Sheet music that can be played on an orchestrion. Music List: Forever Today (instrumental version)" },
    [2793] = { name = "\"Sakura and the Fountain\"", description = "The continuation of Markovic's epic saga follows the journeys of the erstwhile Sakura as she stumbles upon a fantastical fountain that promises to change her life forever. What fortunes await our feathered friend? Pioneers who read it report having their monster rearing rank increase by one." },
    [2794] = { name = "treatise on azimuth clothcraft", description = "This bound red leather volume contains the secrets to crafting garments identical to those worn by Sih Renaye." },
    [2795] = { name = "Holla crystal of gales", description = "A miniature tempest brews in the confines of this translucent gem." },
    [2796] = { name = "Dem crystal of dunes", description = "A miniature sandstorm brews in the confines of this mostly opaque gem." },
    [2797] = { name = "Mea crystal of flames", description = "Crackling black flames dance within the confines of this semi-translucent gem." },
    [2798] = { name = "pale azure cloth", description = "The otherworldly blue hue of this silken cloth pulses in the twilight." },
    [2799] = { name = "order slip: azimuth hood", description = "The wandering seamstress Helina gave you this piece of parchment as proof of payment for one azimuth hood. The crisp writing says to bring the slip back later to obtain the armor." },
    [2800] = { name = "order slip: azimuth coat", description = "The wandering seamstress Helina gave you this piece of parchment as proof of payment for one azimuth coat. The crisp writing says to bring the slip back later to obtain the armor." },
    [2801] = { name = "order slip: azimuth gloves", description = "The wandering seamstress Helina gave you this piece of parchment as proof of payment for one pair of azimuth gloves. The crisp writing says to bring the slip back later to obtain the armor." },
    [2802] = { name = "order slip: azimuth tights", description = "The wandering seamstress Helina gave you this piece of parchment as proof of payment for one pair of azimuth tights. The crisp writing says to bring the slip back later to obtain the armor." },
    [2803] = { name = "order slip: azimuth gaiters", description = "The wandering seamstress Helina gave you this piece of parchment as proof of payment for one pair of azimuth gaiters. The crisp writing says to bring the slip back later to obtain the armor." },
    [2804] = { name = "refined Ra'Kaznar fiber", description = "This taut thread, infused with an upswell of power from the depths of Outer Ra'Kaznar, doesn't break no matter how hard it's pulled." },
    [2805] = { name = "order slip: erilaz galea", description = "This receipt, redeemable for one erilaz galea, should be turned in to Octavernost after some time has passed." },
    [2806] = { name = "order slip: erilaz surcoat", description = "This receipt, redeemable for one erilaz surcoat, should be turned in to Octavernost after some time has passed." },
    [2807] = { name = "order slip: erilaz gauntlets", description = "This receipt, redeemable for one pair of erilaz gauntlets, should be turned in to Octavernost after some time has passed." },
    [2808] = { name = "order slip: erilaz leg guards", description = "This receipt, redeemable for one pair of erilaz leg guards, should be turned in to Octavernost after some time has passed." },
    [2809] = { name = "order slip: erilaz greaves", description = "This receipt, redeemable for one pair of erilaz greaves, should be turned in to Octavernost after some time has passed." },
    [2810] = { name = "purple purgation cloth", description = "Marcellurin provided this large square cloth used as part of a purgation ritual. It has been dipped countless times in holy water, yet the lustrous purple shows no signs of fading." },
    [2811] = { name = "Margret's writ of summons", description = "Curved writing spelling out the sentence \"Meet me on Sverdhried Hillock\" adorns this over-the-top stationery." },
    [2812] = { name = "portrait of Melvien", description = "This piece by Margret depicts Melvien in his younger days. The abstract form and judicious use of color are quite striking." },
    [2813] = { name = "Melvien's turn", description = "This memo dictates the changes in Melvien's personality as described to you by Estienneux. The cause: a tragic incident occuring ten-something years ago." },
    [2814] = { name = "Melvien's death?", description = "This memo contains notes on the incident with Melvien ten-something years ago, as told through the eyes of Mastan. Melvien made a miraculous recovery, having been pronounced all but dead after being struck by lightning." },
    [2815] = { name = "Margret's memo", description = "Curved writing spelling out the sentence \"Meet me by the storage container in Rala Waterways (H-6)\" adorns this over-the-top stationery." },
    [2816] = { name = "Margret's imposter's cipher", description = "The decorations on the stationery are frayed around the edges, and spell out in jagged lettering, \"Carry memories on your back and head for the strange light.\"" },
    [2817] = { name = "Margret's imposter's cipher redux", description = "The decorations on the stationery are frayed around the edges, and spell out in jagged lettering, \"I shall foul the very earth thou walkest on.\"" },
    [2818] = { name = "fabricated pearl of impurity", description = "Black eddies of impurity pulse within this otherwise gleaming pearl." },
    [2819] = { name = "fabricated pearl of miasma", description = "Sickly green noxious threads threaten to erupt from this otherwise gleaming pearl." },
    [2820] = { name = "fabricated pearl of biting winds", description = "A tiny tempest rages within this otherwise gleaming pearl." },
    [2821] = { name = "fabricated pearl of ashen wings", description = "An ashen imprint of a torn wing mars the surface of this otherwise gleaming pearl." },
    [2822] = { name = "fabricated pearl of the false king", description = "Necrotic energies seep from the surface of this otherwise gleaming pearl." },
    [2823] = { name = "prototype pearl of ashen wings", description = "The marbled swirlings in this pearl can copy and replicate information gleaned from the memories of the bearer's battles. By itself, the pearl has no power to open up the extant gates in Outer Ra'Kaznar." },
    [2824] = { name = "prototype pearl of the false king", description = "The marbled swirlings in this pearl can copy and replicate information gleaned from the memories of the bearer's battles. By itself, the pearl has no power to open up the extant gates in Outer Ra'Kaznar." },
    [2825] = { name = "Gilgamesh's introductory letter", description = "This letter of introduction, provided by Gilgamesh, serves as an unmistakable sign of his faith and trust in you. Present it to Vera in Mhaura or Isacio in Selbina and see if his words carry any weight." },
    [2826] = { name = "imperial chair", description = "This comfortable chair was fashioned by a renowned designer collective for the nobility of San d'Oria. Using the text command \"/sitchair 1\" enables the bearer to relax upon this luxurious furnishing." },
    [2827] = { name = "decorative chair", description = "This comfortable chair was fashioned by a renowned designer collective for Bastok's movers and shakers. Using the text command \"/sitchair 2\" enables the bearer to relax upon this luxurious furnishing." },
    [2828] = { name = "ornate stool", description = "This comfortable stool was fashioned by a renowned designer collective for the upper echelons of Windurstian society to greet guests in Heavens Tower. Using the text command \"/sitchair 3\" enables the bearer to relax upon this luxurious furnishing." },
    [2829] = { name = "refined chair", description = "Using the text command \"/sitchair 4\" enables the bearer to relax upon this luxurious furnishing given only to the most accomplished of adventurers." },
    [2830] = { name = "portable container", description = "Using the text command \"/sitchair 5\" enables the bearer to relax upon this luxurious furnishing." },
    [2831] = { name = "chocobo chair", description = "Using the text command \"/sitchair 6\" enables the bearer to relax upon this luxurious furnishing." },
    [2832] = { name = "Ephramadian throne", description = "Using the text command \"/sitchair 7\" enables the bearer to relax upon this luxurious furnishing." },
    [2833] = { name = "shadow throne", description = "Using the text command \"/sitchair 8\" enables the bearer to relax upon this luxurious furnishing." },
    [2834] = { name = "leaf bench", description = "Using the text command \"/sitchair 9\" enables the bearer to relax upon this luxurious furnishing." },
    [2835] = { name = "astral cube", description = "Using the text command \"/sitchair 10\" enables the bearer to relax upon this luxurious furnishing." },
    [2836] = { name = "chocobo chair II", description = "Using the text command \"/sitchair 11\" enables the bearer to relax upon this luxurious furnishing." },
    [2837] = { name = "Reisenjima Sanctorium orb", description = "A pale yellow orb given to you by Iroha that can light the way to the future." },
    [2838] = { name = "\"Sakura and the Magicked Net\"", description = "Entry three in the Sakura series, this volume details an enigmatic net that washed ashore and changed the course of chocobo evolution. Pioneers who read it report having their monster rearing rank increase by one." },
    [2839] = { name = "reaper", description = "An enigmatic device used to harvest materials from within Escha and Reisenjima." },
    [2840] = { name = "forgotten memory", description = "A vivid scene depicting the struggle between the dread jester Balamor and two adventurers. A valiant warrior suffered a grievous wound shielding his young daughter in the conflict, and his wife made an impossible decision to save her husband's life--a decision that cost them their daughter and led to the creation of an entirely new entity." },
    [2841] = { name = "?", description = "???" },
    [2842] = { name = "weathered Haverton hat", description = "A long-brimmed hat bearing the crest of a raven. It shields the wearer's gaze from the sun, enabling them to fire off a swift barrage of arrows that always strike their mark. Only those with proven prowess are given the honor of donning such a priceless piece." },
    [2843] = { name = "lightsworm", description = "This tiny glowing worm given to you by Cait Sith allows for safe passage into the Walk of Echoes." },
    [2844] = { name = "\"Sakura''s Excellent Adventure\"", description = "The fourth volume in Markovic's magnum opus depicts Sakura chancing upon one of the famous Mog Tablets. Yet who is the shadowy figure that wrests the artifact from her clutches? Pioneers who read it report having their monster rearing rank increase by one." },
    [2845] = { name = "\"Sakura and the Cactus Corps\"", description = "The fifth volume in this endless series of adventures traces the origin of a mysterious letter sent to Sakura by Cactrot Rapido challenging her to a duel for the ages. The hopes of a nation rest on the chocobo's fluffy wings! Pioneers who read it report having their monster rearing rank increase by one." },
    [2846] = { name = "\"Sakura and the Holy Grail\"", description = "The seemingly endless Sakura series reaches its thrilling conclusion! Sakura, having heard tales of a holy grail in Ulbuka, successfully makes a voyage to the western continent only to be besieged by crabs and Qiqirns on all sides! How will she ever work her way out of this one? Pioneers who read it report having their monster rearing rank increase by one." },
    [2847] = { name = "Siren's plume", description = "This verdant green plume flutters delicately even when the skies are perfectly still, and its tip points unerringly toward the nearest crystal." },
    [2848] = { name = "Moglification: Resist Sleep", description = "Moogle-powered assistance from your Mog House. Slightly improves your resistance to sleep effects." },
    [2849] = { name = "Moglification: Resist Poison", description = "Moogle-powered assistance from your Mog House. Slightly improves your resistance to poison effects." },
    [2850] = { name = "Moglification: Resist Paralysis", description = "Moogle-powered assistance from your Mog House. Slightly improves your resistance to paralysis effects." },
    [2852] = { name = "Moglification: Resist Silence", description = "Moogle-powered assistance from your Mog House. Slightly improves your resistance to silence effects." },
    [2853] = { name = "Moglification: Resist Petrification", description = "Moogle-powered assistance from your Mog House. Slightly improves your resistance to petrification effects." },
    [2854] = { name = "Moglification: Resist Virus", description = "Moogle-powered assistance from your Mog House. Slightly improves your resistance to virus effects." },
    [2855] = { name = "Moglification: Resist Curse", description = "Moogle-powered assistance from your Mog House. Slightly improves your resistance to curse effects." },
    [2880] = { name = "iridal core of the ruins", description = "This core is said to resonate with a strange device found in Fei'Yin." },
    [2881] = { name = "iridal core of the tomb", description = "This core is said to resonate with a strange device found in King Ranperre's Tomb." },
    [2882] = { name = "iridal core of the pass", description = "This core is said to resonate with a strange device found in Ranguemont Pass." },
    [2883] = { name = "arcus fiber", description = "This iridescent fiber contains vital essences of each of the eight elements." },
