    [2958] = { name = "most curious curio", description = "This tiny figure created by Koru-Moru can sense all manner of evil and ill will throughout Vana'diel. The three most vaunted academics in all of Windurst can put their heads together to interpret its signs." },
    [2959] = { name = "most confounding curio", description = "This tiny figure created by Koru-Moru could once sense all manner of evil and ill will throughout Vana'diel, but it appears to have fully stopped functioning due to an overload of energies. Perhaps it will regain its powers if you step away from the interference." },
    [2960] = { name = "macabre simulacrum", description = "A lurid white skull stares back at you from the back of this moth simulacrum. Those possessing one can enter Balamor's alternate universe via an infernal transposer." },
    [2961] = { name = "motionless plume", description = "The color and energy have been all but drained from this plume, which once contained a portion of Siren's essence. It may be revitalized upon reaching the skies." },
    [2962] = { name = "guffawshroom", description = "The dotted patterns in this tiny shroom found in Sih Gates are arranged in a cute smiley-face pattern. Though mildly toxic, it can be crushed into a fine powder and used to treat a variety of maladies." },
    [2963] = { name = "job gesture: geomancer", description = "Strike a pose befitting a storied geomancer." },
    [2964] = { name = "job gesture: rune fencer", description = "Strike a pose befitting an attuned rune fencer." },
    [2965] = { name = "golden shovel cordon", description = "Embroidered with a gleaming golden shovel, this badge is given only to pioneers who have gone above and beyond the call of duty in advancing the colonization initiative. Reduces the waiting period for new coalition imprimaturs." },
    [2966] = { name = "fabricated ward of impurity", description = "Black eddies of impurity dot the surface of this glowing rune." },
    [2967] = { name = "fabricated ward of miasma", description = "Sickly green noxious threads threaten to erupt from this glowing rune." },
    [2968] = { name = "fabricated ward of biting winds", description = "A tiny tempest rages within this glowing rune." },
    [2969] = { name = "fabricated ward of ashen wings", description = "The marbled swirlings in this glowing rune can copy and replicate information gleaned from the memories of the bearer's battles." },
    [2970] = { name = "fabricated ward of the false king", description = "The marbled swirlings in this glowing rune can copy and replicate information gleaned from the memories of the bearer's battles." },
    [2971] = { name = "song of hope", description = "Iroha has called out to you in a vision, bequeathing unto you a divine radiance that can guide you ever forward. You may be able to learn more at the crag of Holla, Dem, or Mea." },
    [2972] = { name = "founder king's orb", description = "A precious artifact of the founder king that Balamor has long been hunting for. A fearsome upswell of magic threatens to burst from its glassy confines." },
    [2973] = { name = "Cait Sith's whisker", description = "A thin strand plucked directly from Cait Sith's regal visage. It possesses the power to ensure that the bearer cannot stray from his true path." },
    [2974] = { name = "extradimensional scar", description = "A small device presented by Selh'teus that lights the way in times of danger." },
    [2975] = { name = "breath of the avatars", description = "A small portion of power that the avatars bestowed upon you in the stone circle in La Theine Plateau. Its soft embrace will enable to you pass through the crystal in Reisenjima even without having the ability to become a god of light." },
