    [3026] = { name = "Phoenix's blessing", description = "A portion of Phoenix's vim and vigor entrusted to you by Iroha. She will always remain by your side, even though you may not be able to see her." },
    [3027] = { name = "packet of Midras's explosives", description = "A custom blend of explosives for blasting through Palborough Mines' bedrock. While the explosive force is small, the chemical reaction it produces with the rock makes it perfect for clearing obstacles where delicacy is required." },
    [3028] = { name = "tarnished ring", description = "A simple silver band found in Palborough Mines. It may have once belonged to a victim of the explosion." },
    [3029] = { name = "rusty locket", description = "A worn and rusty locket found in Palborough Mines. It may have once belonged to a victim of the explosion." },
    [3030] = { name = "invitation to a feast most dire", description = "A letter of invitation to a feast most dire given to you by Kupofried. Content level: 119 Applicable battlefields: Horlais Peak, Waughroon Shrine, and Balga's Dais" },
    [3031] = { name = "radialens", description = "A special lens whose refractive properties can see through unholy veils to unmask threats within Reisenjima and Escha areas." },
    [3032] = { name = "mollifier", description = "Quells the anger of certain foes, preventing them from calling their leaders to aid them in battle." },
