    [3051] = { name = "Mog Patio design document", description = "This plan, written by the Mog House Management Union, describes in intricate detail the parameters, requirements, and necessities regarding a Mog Patio. Those in possession of these plans can construct a Mog Patio if their Mog House has a second floor." },
    [3052] = { name = "Ambuscade Primer Volume One", description = "The first installment of a primer detailing the ins and outs of Ambuscade, penned by the esteemed mage Abdhaljs and a particularly diligent member of the Adventurers' Mutual Aid Network (A.M.A.N.)." },
    [3053] = { name = "Ambuscade Primer Volume Two", description = "The second installment of a primer detailing the ins and outs of Ambuscade, penned by the esteemed mage Abdhaljs and a particularly diligent member of the Adventurers' Mutual Aid Network (A.M.A.N.)." },
    [3055] = { name = "trainer's whistle", description = "This whistle enables the bearer to call forth their trusty steed--or its equivalent--to their side. Once properly registered, the adventurer will be able to ride the mount of their choice." },
