    [3147] = { name = "Ygnas's leaf", description = "A leafkin leaf once found on Ygnas's alternate form. Deep green veins running through the blue leaf give off a regal air." },
    [3148] = { name = "Ancient Melody: O", description = "A brief stanza of melody said to be older than time itself. It is largely worthless on its own." },
