    [3153] = { name = "after-party pass", description = "This pass permits the bearer to attend Fantastic Fraulein Mumor's Superheroine Show after-party in Qu'Bia arena. One-time use only. Content level 117." },
    [3154] = { name = "reassembling technique", description = "This technique enables one who has learned it to reassemble items that meet certain conditions into other items." },
    [3155] = { name = "memory gem", description = "This diamond, as hard as it is lustrous, was specially magicked by Marjory to resonate with alter ego energies." },
    [3156] = { name = "empty hourglass", description = "This hourglass is almost completely empty except for a few tiny granules of black sand." },
    [3157] = { name = "filled memory gem", description = "This pure diamond, currently experimental, can be used as a medium by which to potentially call forth even stronger alter egos." },
    [3158] = { name = "Elvaan Mask of Darkness", description = "An Elvaan mask from San d'Oria (D). It is imbued with the power of darkness." },
    [3159] = { name = "Elvaan Mask of Light", description = "An Elvaan mask from San d'Oria (D). It is bathed in light that banishes the darkness." },
    [3160] = { name = "Galka Mask of Darkness", description = "A Galka mask from Bastok (D). It is imbued with the power of darkness." },
    [3161] = { name = "Galka Mask of Light", description = "A Galka mask from Bastok (D). It is bathed in light that banishes the darkness." },
    [3162] = { name = "Tarutaru Mask of Darkness", description = "A Tarutaru mask from Windurst (D). It is imbued with the power of darkness." },
    [3163] = { name = "Tarutaru Mask of Light", description = "A Tarutaru mask from Windurst (D). It is bathed in light that banishes the darkness." },
    [3164] = { name = "Mithra Mask of Darkness", description = "A Mithra mask from Jeuno (D). It is imbued with the power of darkness." },
    [3165] = { name = "Mithra Mask of Light", description = "A Mithra mask from Jeuno (D). It is bathed in light that banishes the darkness." },
    [3166] = { name = "broken flying machine", description = "An odd contraption once ridden by Eald'narche. It appears to be in quite the state of disrepair, but perhaps it can be restored to its former state." },
    [3167] = { name = "levitation device", description = "An attachment likely to have been used in the flying machine, this device serves no purpose on its own. You may be able to get a hint for how to repair it by examining the strange apparatus in Fei'Yin." },
    [3168] = { name = "whirring engine", description = "An attachment likely to have been used in the flying machine, this device vibrates softly as it rapidly spins." },
    [3169] = { name = "Mog Kupon W-RMEA", description = "Issued by the Mog House Management Union (MHMU). Tradeable for item level 119 relic, mythic, empyrean, ergon, and aeonic weapons." },
    [3170] = { name = "Deed Voucher", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for a full set of item level 109 artifact armor (head, chest, hands, legs, and feet) of your choosing." },
    [3171] = { name = "Deed Voucher +1: Head", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 artifact headpiece of your choosing." },
    [3172] = { name = "Deed Voucher +1: Chest", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 artifact chestpiece of your choosing." },
    [3173] = { name = "Deed Voucher +1: Hands", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 artifact handgear of your choosing." },
    [3174] = { name = "Deed Voucher +1: Legs", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 artifact leggear of your choosing." },
    [3175] = { name = "Deed Voucher +1: Feet", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 artifact footwear of your choosing." },
    [3176] = { name = "Deed Voucher +2: Head", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) artifact headpiece of your choosing." },
    [3177] = { name = "Deed Voucher +2: Chest", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) artifact chestpiece of your choosing." },
    [3178] = { name = "Deed Voucher +2: Hands", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) artifact handgear of your choosing." },
    [3179] = { name = "Deed Voucher +2: Legs", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) artifact leggear of your choosing." },
    [3180] = { name = "Deed Voucher +2: Feet", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) artifact footwear of your choosing." },
    [3181] = { name = "tentacle touching ticket", description = "A ticket that permits the bearer to shake appendages with the members of the morbol idol group Shining Bless. Written in tiny chigoe-sized font at the back is a disclaimer: Vana'diel Productions and the M.H.M.U. bear no responsibility for any paralysis, silence, poison, blindness, weight, slow, sudden death, or any related trauma real or perceived that may occur during the performance." },
    [3182] = { name = "Invitation from Excenmille", description = "I await you at the Peak of Horlais, where I hope you will do me the favor of crossing blades...or whatever means of warfare you deem necessary." },
    [3183] = { name = "Invitation from Naji", description = "Think you've got what it takes to beat me? Then I'll be waiting at Waughroon Shrine--but don't get your hopes up!" },
    [3184] = { name = "Invitation from Kupipi", description = "I'm ve^ry pleased-weased to challenge you at Balga's Dais! Don't be lataru, or you'll be in for a good smacking!" },
    [3185] = { name = "Stygian Pact phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [3186] = { name = "Champion phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [3187] = { name = "Divine phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [3188] = { name = "Maiden phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [3189] = { name = "inert geomancy bell", description = "A small copper bell found in Escha - Ru'Aun. Could this have any link to Siren?" },
    [3190] = { name = "fistful of familiar soil", description = "A coalescence of ergon locus energy harnessed from a place of powerful earth magics. Surely this has some relation to Siren." },
    [3191] = { name = "sheet of Mapitoto tunes", description = "Sheet music that can be played on an orchestrion. Music List: Full Speed Ahead!" },
    [3192] = { name = "mandragora sproutling memento", description = "A pleasant memory of a mandragora sproutling within the Mog Garden that gives Chacharoon the strength to cheer you on." },
