    [3202] = { name = "Cheer: Mandragora Sproutling", description = "A cheer from Chacharoon based on the pleasant memories of raising a mandragora sproutling. Increases vitality by 2 and increases alter ego auto-regen by 2." },
    [3203] = { name = "Cheer: Mandragora", description = "A cheer from Chacharoon based on the pleasant memories of raising a mandragora. Increases vitality by 3 and increases alter ego physical evasion by 6%." },
    [3204] = { name = "Cheer: Elder Mandragora", description = "A cheer from Chacharoon based on the pleasant memories of raising an elder mandragora. Increases vitality by 4, and increases alter ego auto-regen by 4 and physical evasion by 7%." },
    [3205] = { name = "Cheer: Lycopodium", description = "A cheer from Chacharoon based on the pleasant memories of raising a lycopodium. Increases charisma by 3 and increases alter ego physical defense by 4%." },
    [3206] = { name = "Cheer: Ake-Ome", description = "A cheer from Chacharoon based on the pleasant memories of raising an ake-ome. Increases charisma by 4, increases alter ego physical defense by 5%, and confers a capacity point bonus of 5%." },
    [3207] = { name = "Cheer: Adenium", description = "A cheer from Chacharoon based on the pleasant memories of raising an adenium. Increases Resist Sleep by 10 and increases alter ego auto-regen by 3 and magic evasion by 6% (effective at item level 100 and above)." },
    [3208] = { name = "Cheer: Elder Adenium", description = "A cheer from Chacharoon based on the pleasant memories of raising an elder adenium. Increases Resist Sleep by 10 and increases alter ego auto-regen by 4, magic evasion by 7% (effective at item level 100 and above), and Double Attack by 2%." },
    [3209] = { name = "Cheer: Korrigan", description = "A cheer from Chacharoon based on the pleasant memories of raising a korrigan. Increases Resist Poison by 10 and increases alter ego auto-regen by 3 and physical and ranged attack by 5%." },
    [3210] = { name = "Cheer: Pachypodium", description = "A cheer from Chacharoon based on the pleasant memories of raising a pachypodium. Increases Resist Poison by 10 and alter ego auto-regen by 4, physical and ranged attack by 6%, and Double Attack by 2%." },
    [3211] = { name = "Cheer: Citrullus", description = "A cheer from Chacharoon based on the pleasant memories of raising a citrullus. Increases Resist Blind by 10 and alter ego auto-regen by 5 and haste by 5%." },
    [3212] = { name = "moglophone", description = "A convenient device created by mysterious moogle magic that automatically sends information about \"the secret place\" to the moogle who devised it." },
