    [3219] = { name = "Deed Token +2: Head", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) relic headpiece of your choosing." },
    [3220] = { name = "Deed Token +2: Chest", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) relic chestpiece of your choosing." },
    [3221] = { name = "Deed Token +2: Hands", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) relic handgear of your choosing." },
    [3222] = { name = "Deed Token +2: Legs", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) relic leggear of your choosing." },
    [3223] = { name = "Deed Token +2: Feet", description = "A voucher given to adventurers who have received a certain number of Deeds of Heroism through Records of Eminence. Exchangeable for an item level 119 (reforged once) relic footwear of your choosing." },
    [3224] = { name = "Primer on Martial Techniques", description = "A heavy, cloth-wrapped book on all manner of special techniques for mastering various armaments." },
    [3225] = { name = "Treatise on Martial Techniques", description = "A heavy, cloth-wrapped book on an even greater number of special techniques for mastering various armaments." },
    [3226] = { name = "sheet of Al'Taieu tunes", description = "Sheet music that can be played on an orchestrion. Music List: The Celestial Capital - Al'Taieu" },
    [3227] = { name = "sheet of Jeuno tunes", description = "Sheet music that can be played on an orchestrion. Music List: The Grand Duchy of Jeuno Ru'Lude Gardens" },
    [3228] = { name = "sheet of harvest tunes", description = "Sheet music that can be played on an orchestrion. Music List: Devils' Delight" },
    [3229] = { name = "star-crested summons", description = "A special missive emblazoned with a white star. Each individual letter seems to glimmer with an inner glow. Intended recipient: Tosuka-Porika." },
    [3230] = { name = "strange doll", description = "This doll, found in Giddeus, is ostensibly a magicked figure, but to your eyes it appears as harmless and cute as a child's toy. It is wholly lacking in the vengeful nature you would expect of the real thing." },
    [3231] = { name = "piece of evidence", description = "L uhtxluh wkh vshfldo hjj dqg d yhub vwurqj lqglylgxdo. Iluvw frphv wkh hjj. *A treble for when you're in trouble." },
    [3232] = { name = "sublime lucky egg", description = "An egg inscribed with a special pattern said to bring good luck to the bearer. This one is of exceptional quality." },
    [3233] = { name = "magicked doll", description = "A magicked doll liberated from Honoi-Gomoi. It is incredibly old, and of a color you're not sure you've ever seen before. Its eyes give a glimpse into its dark soul." },
    [3234] = { name = "moglophone II", description = "A convenient device created by mysterious moogle magic that automatically sends information about \"the secret place\" to the moogle who devised it. The range is shorter than the original model." },
    [3235] = { name = "moglophone II", description = "A convenient device created by mysterious moogle magic that automatically sends information about \"the secret place\" to the moogle who devised it. The range is shorter than the original model." },
