    [3254] = { name = "Orcish battle plan", description = "This map, doubtless from the northern continent of Rhazowa, is surprisingly detailed for one of Orcish origin. A skilled cartographer or tactician could surely interpret what it means." },
    [3255] = { name = "Quemaricond's report", description = "Quemaricond of the Royal Knights mentioned some details of a secret meeting between the Orcish emissary and the Orcs prowling Davoi. This report summarizes his findings." },
    [3256] = { name = "solidago flower", description = "The bright yellow pollen of this flower gleams in the sunlight, and its redolent fragrance helps clear the mind of distractions. Unlike many other wild flowers, it is difficult to grow in controlled conditions." },
    [3257] = { name = "missive to Altennia", description = "This letter, addressed to Altennia, has been sealed with the finest wax in all of San d'Oria. It would be unwise to break the seal just to sate your own curiosity, but you suspect it has something to do with dancing with Prince Trion." },
    [3258] = { name = "Carmine Swallows' map", description = "This map was likely used by the Carmine Swallows during their travels in Beaucedine Glacier. Orcish fingers have sullied the parchment, which is hopelessly torn and barely legible. Perhaps someone from the Royal Knights can provide more information." },
    [3259] = { name = "lock of golden hair", description = "A trophy taken as proof of victory against the soulflayer." },
    [3260] = { name = "Mnejing's receiver", description = "A special device with various Besieged-related messages recorded by Mnejing. Permits the bearer to hear information on beastmen movements." },
    [3261] = { name = "Wyrm God phantom gem", description = "An ephemerally crystallized corpus of memories that revolve around a battle for the ages." },
    [3262] = { name = "master breaker", description = "You have been recognized by Nomad Moogles across Vana'diel as a master of your profession." },
    [3263] = { name = "gift for Megomak", description = "A metallic red-tinted box from Ghatsad inscribed with the seal of Caduceus. It is sealed by a special incantation, preventing it from being opened by anyone but its intended recipient. Perhaps Megomak will be a bit more receptive with this in tow." },
    [3264] = { name = "pure white ampoule", description = "An enigmatic white vial dropped by the Gloom Phantom. Some special material found from the Hazhalm Testing Grounds is contained within." },
    [3265] = { name = "aeropearl", description = "The special pearl from the Olduum civilization is said to produce near-limitless quanities of breathable air. A crystal resides in the translucent jewel's center, but the liquid that should be contained within has been almost completely emptied. It is unlikely that the pearl can perform its intended purpose as-is." },
    [3266] = { name = "man-made solution", description = "A special liquid made by distilling breathable air via an aetheric process. Once injected in an automaton or similar vessel, it provides protection via the power of water." },
    [3267] = { name = "repaired aeropearl", description = "Ghatsad has restored the original functionality of the aeropearl. You would go so far as to say that it's better than new." },
    [3268] = { name = "sheet of ancient tunes", description = "Sheet music that can be played on an orchestrion. Music List: Griffons Never Die Thunder of the March Stargazing" },
    [3269] = { name = "aspirant's canteen", description = "A powerful Goblin-made vessel containing a condensed version of Phoenix's blessing. Its puissance remains intact until one's training in Omen has expired." },
