    [3293] = { name = "Memorian, the Magicked Doll", description = "A magicked doll crafted by Professor Koru-Moru that reacts to places or people whose memories have been manipulated by Uran-Mafran. It would behoove you to visit those you think may have been affected." },
    [3294] = { name = "depleted Memorian", description = "A magicked doll given to you by Professor Koru-Moru. It has successfully reacted to Uran-Mafran's magick and thus has wholly run out of juice." },
    [3295] = { name = "Trion's directive", description = "This note contains orders for Rahal, head of the Royal Knights, to Uran-Mafran, the mage from Windurst. Expectations for Altennia and her retinue are high." },
    [3296] = { name = "ember-encrusted orichalcum", description = "This lump of orichalcum has been purified by the flames of Ifrit's Cauldron." },
    [3297] = { name = "cloth-lined basket", description = "This basket, adorned with a beautiful floral print cloth, once held hard-boiled eggs brought to Maat as a gift. You can't help but sense a familiar odor wafting from the reeds..." },
    [3298] = { name = "map to the woman's home", description = "Muckvix hastily scrawled this map on a yellowed piece of parchment. This should help you find the woman Maat was looking for. Perhaps Miladi-Nildi near the rental houses in Lower Jeuno can assist you in deciphering it." },
    [3299] = { name = "Maat's pillow", description = "A pink pillow left behind by Maat as he went on the warpath. The cute red and purple hearts that adorn it are brimming with positive energy." },
    [3300] = { name = "shiny Ra'Kaznarian plate", description = "A prismatic sheet of metal found in Outer Ra'Kaznar." },
    [3301] = { name = "dull Ra'Kaznarian plate", description = "A nondescript sheet of metal that has clearly seen better days." },
    [3302] = { name = "Liber Daemonium", description = "A forbidden volume housed in Celennia Memorial Library. Author unknown. Countless tragedies are said to befall any who foolishly peruse its pages." },
    [3303] = { name = "bronze-hued tag", description = "The metallic tag, a symbol of infinite knowledge, gleams with an inner light. It doubles as a key to open the door to a research chamber in northeastern Outer Ra'Kaznar." },
    [3304] = { name = "Silver Knife membership card", description = "This card permits the bearer entry to the Silver Knife, a members-only auction house in Eastern Adoulin." },
