    [3327] = { name = "Uran-Mafran's orb", description = "Uran-Mafran carelessly dropped this orb as he was fleeing from the scene. It appears to harbor the essence of life...the power of the crystals." },
    [3328] = { name = "Ruspix's plate", description = "A plate of dubious origins developed by the surprisingly eloquent Ruspix. He claims that it can slowly accumulate energies from expended Ra'kaznarian plates. A wax seal on the back confirms yet again that it is an authentic Ruspix original." },
    [3329] = { name = "sheet of ancient battle tunes", description = "Sheet music that can be played on an orchestrion. Music List: Autumn Footfalls Echoes of a Zephyr The Cosmic Wheel" },
