    [3331] = { name = "sheet of character selection tunes", description = "Sheet music that can be played on an orchestrion. Music List: Hume Male Hume Female Elvaan Male Elvaan Female Tarutaru Male Tarutaru Female Mithra Galka" },
    [3332] = { name = "sheet of Starlight tunes", description = "Sheet music that can be played on an orchestrion. Music List: Jeuno -Starlight Celebration-" },
    [3333] = { name = "despairing psyche", description = "A fragment of a soul traped in Dynamis. It is brimming with despair, and most assuredly once belonged to the Shadow Lord." },
    [3334] = { name = "suffering psyche", description = "A fragment of a soul traped in Dynamis. It is brimming with suffering, and most assuredly once belonged to Raebrimm." },
    [3335] = { name = "anguished psyche", description = "A fragment of a soul traped in Dynamis. It is brimming with anguish, and most assuredly once belonged to Raebrimm." },
    [3336] = { name = "rancorous psyche", description = "A fragment of a soul traped in Dynamis. It is brimming with rancor, and most assuredly once belonged to Raebrimm." },
    [3337] = { name = "determined psyche", description = "A fragment of a soul traped in Dynamis. It is brimming with determination, and most assuredly once belonged to Raebrimm." },
    [3338] = { name = "Raebrimm's memento", description = "This wispy black cloth once belonging to Raebrimm somehow found its way to Dynamis - Xarcabard." },
    [3339] = { name = "vial of Chaos's blood", description = "This vial gives off a foul stench, as if the magical energies within were the very lifeblood of Chaos." },
